// ==========================================
// 🏷️ Barcode Aliases & Smart Match Normalizer
// ==========================================
const KNOWN_BARCODE_ALIASES = {
    '5011061058027': '7015661058027', // دابل ديرز جيلى بين شطه 90 جم
    '7015661058027': '5011061058027',
    '855400091266': '8857660091266',  // سموكي بوبينج تفاح 7 جم
    '8857660091266': '855400091266',
};
window.KNOWN_BARCODE_ALIASES = KNOWN_BARCODE_ALIASES;

window.getBarcodeVariants = function(rawBarcode) {
    if (!rawBarcode) return [];
    const set = new Set();
    const cleanRaw = String(rawBarcode).trim().toLowerCase();
    const subCodes = cleanRaw.split(',').map(s => s.trim()).filter(Boolean);
    const aliases = window.KNOWN_BARCODE_ALIASES || KNOWN_BARCODE_ALIASES;
    
    subCodes.forEach(code => {
        if (!code) return;
        set.add(code);
        if (aliases[code]) {
            set.add(String(aliases[code]).trim().toLowerCase());
        }
        for (const [a, b] of Object.entries(aliases)) {
            if (a.toLowerCase() === code) set.add(b.toLowerCase());
            if (b.toLowerCase() === code) set.add(a.toLowerCase());
        }
        if (code.length === 12) set.add('0' + code);
        if (code.length === 13 && code.startsWith('0')) set.add(code.substring(1));
        const stripped = code.replace(/^0+/, '');
        if (stripped) set.add(stripped);
    });
    return Array.from(set);
};

// ==========================================
// ⭐ Supabase Local Backend Interceptor
// ==========================================
const originalFetch = window.fetch;

async function fetchAllSupabaseRows(queryBuilder) {
    let allData = [];
    let page = 0;
    const pageSize = 1000;
    while (true) {
        const { data, error } = await queryBuilder.range(page * pageSize, (page + 1) * pageSize - 1);
        if (error) throw error;
        if (!data || data.length === 0) break;
        allData = allData.concat(data);
        if (data.length < pageSize) break;
        page++;
    }
    return { data: allData, error: null };
}

// 🛡️ Secure Delete Wrapper
window.secureDelete = async function(tableName, matchColumn, matchValue) {
    let user = null;
    try { user = JSON.parse(localStorage.getItem('cc_user')); } catch (e) {}
    let pass = sessionStorage.getItem('cc_pass');
    
    if (!user || user.permissions !== 'ALL' || !pass) {
        if (typeof showToast === 'function') showToast("ليس لديك صلاحية الحذف", "error");
        return { error: "Unauthorized" };
    }
    
    const { data, error } = await supabase.rpc('secure_delete_record', {
        p_table: tableName,
        p_column: matchColumn,
        p_value: String(matchValue),
        p_user: user.username,
        p_pass: pass
    });
    if (!error && typeof window.bumpSystemActivity === 'function') {
        window.bumpSystemActivity();
    }
    return { data, error };
};

// 🔄 Recalculate & Sync Customer Stats in Supabase
async function updateCustomerStatsInDatabase(phone, fallbackData = {}) {
    if (!phone) return;
    const cleanPhone = String(phone).trim();
    if (!cleanPhone) return;

    try {
        // Fetch all orders for this customer phone
        const { data: custOrders, error: ordErr } = await supabase.from('orders')
            .select('customer_name,governorate,address,final_total,status,order_date')
            .eq('phone', cleanPhone);

        if (ordErr) {
            console.error('Error fetching orders for customer sync:', ordErr);
            return;
        }

        let ordersCount = 0;
        let totalPaid = 0;
        let lastOrderDate = null;
        let custName = fallbackData.name || fallbackData.customer_name || '';
        let custGov = fallbackData.gov || fallbackData.governorate || '';
        let custAddress = fallbackData.address || '';

        (custOrders || []).forEach(o => {
            const isCancelledOrReturned = (o.status === 'ملغي' || o.status === 'مرتجع');
            if (!isCancelledOrReturned) {
                ordersCount += 1;
                totalPaid += parseFloat(o.final_total) || 0;
            }
            if (o.order_date && (!lastOrderDate || o.order_date > lastOrderDate)) {
                lastOrderDate = o.order_date;
            }
            if (o.customer_name && o.customer_name !== 'بدون اسم') custName = o.customer_name;
            if (o.governorate) custGov = o.governorate;
            if (o.address) custAddress = o.address;
        });

        totalPaid = Math.round(totalPaid * 100) / 100;

        // Check if customer exists in customers table
        const { data: existing, error: existErr } = await supabase.from('customers')
            .select('id,customer_name,governorate,address')
            .eq('phone', cleanPhone)
            .limit(1);

        if (existing && existing.length > 0) {
            const currentCust = existing[0];
            await supabase.from('customers').update({
                orders_count: ordersCount,
                total_paid: totalPaid,
                last_order_date: lastOrderDate,
                customer_name: custName || currentCust.customer_name || 'بدون اسم',
                governorate: custGov || currentCust.governorate || '',
                address: custAddress || currentCust.address || ''
            }).eq('id', currentCust.id);
        } else {
            await supabase.from('customers').insert([{
                customer_name: custName || 'بدون اسم',
                phone: cleanPhone,
                governorate: custGov || '',
                address: custAddress || '',
                orders_count: ordersCount,
                total_paid: totalPaid,
                last_order_date: lastOrderDate
            }]);
        }
    } catch (e) {
        console.error('Error syncing customer stats in DB:', e);
    }
}

