window.receiptsArchiveData = [];

window.loadReceiptsArchiveData = async function() {
    try {
        if (!window.supabase) return false;
        const { data: rawArchive, error: arcErr } = await fetchAllSupabaseRows(
            supabase.from('expiry_receipts_log').select('*').order('created_at', { ascending: false })
        );
        if (!arcErr && Array.isArray(rawArchive)) {
            window.receiptsArchiveData = rawArchive.map(e => ({
                id: e.id,
                name: e.product_name,
                qty: e.quantity !== undefined ? parseFloat(e.quantity) : (parseFloat(e.qty) || 0),
                expiryDate: e.expiry_date,
                location: e.location || '',
                regDate: e.reg_date || '',
                receiver: e.receiver || '',
                notes: e.notes || '',
                originalPrice: e.original_price || '',
                offerPrice: e.offer_price || '',
                status: e.status || '',
                barcode: e.barcode || '',
                talabatStatus: window.normalizeMarketplaceStatus(e.talabat_status),
                instashopStatus: window.normalizeMarketplaceStatus(e.instashop_status)
            }));
            console.log("Loaded immutable expiry receipts archive:", window.receiptsArchiveData.length, "records");
            
            // Re-render calendar dots if flatpickr exists
            if (typeof renderExpiryCalendarDots === 'function') {
                renderExpiryCalendarDots();
            }
            if (typeof window.renderMarketplaceArchive === 'function') {
                window.renderMarketplaceArchive();
            }
            return true;
        }
        return false;
    } catch(err) {
        console.warn("Could not load expiry_receipts_log:", err);
        return false;
    }
};

window.getReceiptsForSelectedDates = function(selectedDates) {
    let result = [];
    selectedDates.forEach(dateKey => {
        // Strictly export from the immutable receipts archive
        let fromArchive = (window.receiptsArchiveData || []).filter(item => {
            if (!item.regDate) return false;
            return getCalendarDateKey(item.regDate) === dateKey;
        });
        result.push(...fromArchive);
    });
    return result;
};

window.renderExpiryCalendarDots = function() {
    if (!window.expiryDataDatesSet) window.expiryDataDatesSet = new Set();
    window.expiryDataDatesSet.clear();
    
    // Strictly mark dates from the immutable receipts archive (starts fresh from today)
    (window.receiptsArchiveData || []).forEach(item => {
        if (item.regDate) {
            window.expiryDataDatesSet.add(getCalendarDateKey(item.regDate));
        }
    });
    
    if (typeof expiryExportDatePicker !== 'undefined' && expiryExportDatePicker) {
        expiryExportDatePicker.redraw();
    }
};

window.normalizeMarketplaceStatus = function(status) {
    return ['present', 'absent'].includes(status) ? status : 'unknown';
};

window.marketplaceStatusLabel = function(status) {
    const labels = { present: 'موجود', absent: 'غير موجود', unknown: 'غير محدد' };
    return labels[window.normalizeMarketplaceStatus(status)];
};

function syncLedgerCustomMarketplaceSelect(selectId) {
    const select = document.getElementById(selectId);
    const customSelect = document.querySelector(`.ledger-custom-select[data-select-id="${selectId}"]`);
    if (!select || !customSelect) return;
    const value = window.normalizeMarketplaceStatus(select.value);
    const button = customSelect.querySelector('.ledger-custom-select__button');
    if (button) {
        button.textContent = window.marketplaceStatusLabel(value);
        button.dataset.status = value;
    }
    customSelect.querySelectorAll('[role="option"]').forEach(option => {
        option.setAttribute('aria-selected', option.dataset.value === value ? 'true' : 'false');
    });
}

function setupLedgerCustomMarketplaceSelects() {
    document.querySelectorAll('.ledger-custom-select[data-select-id]').forEach(customSelect => {
        const selectId = customSelect.dataset.selectId;
        const select = document.getElementById(selectId);
        const button = customSelect.querySelector('.ledger-custom-select__button');
        if (!select || !button || customSelect.dataset.ready === 'true') return;
        customSelect.dataset.ready = 'true';
        button.addEventListener('click', () => {
            const willOpen = !customSelect.classList.contains('is-open');
            document.querySelectorAll('.ledger-custom-select.is-open').forEach(openSelect => {
                openSelect.classList.remove('is-open');
                openSelect.querySelector('.ledger-custom-select__button')?.setAttribute('aria-expanded', 'false');
            });
            customSelect.classList.toggle('is-open', willOpen);
            button.setAttribute('aria-expanded', String(willOpen));
        });
        customSelect.querySelectorAll('[role="option"]').forEach(option => {
            option.addEventListener('click', () => {
                select.value = option.dataset.value;
                select.dispatchEvent(new Event('change', { bubbles: true }));
                syncLedgerCustomMarketplaceSelect(selectId);
                customSelect.classList.remove('is-open');
                button.setAttribute('aria-expanded', 'false');
            });
        });
        syncLedgerCustomMarketplaceSelect(selectId);
    });
    document.addEventListener('click', event => {
        if (event.target.closest('.ledger-custom-select')) return;
        document.querySelectorAll('.ledger-custom-select.is-open').forEach(customSelect => {
            customSelect.classList.remove('is-open');
            customSelect.querySelector('.ledger-custom-select__button')?.setAttribute('aria-expanded', 'false');
        });
    });
}

window.getMarketplaceStatusForBarcode = function(barcode) {
    const normalizedBarcode = String(barcode || '').trim().toLowerCase();
    if (!normalizedBarcode) return { talabatStatus: 'unknown', instashopStatus: 'unknown' };
    const previousEntry = (window.receiptsArchiveData || []).find(entry =>
        String(entry.barcode || '').trim().toLowerCase() === normalizedBarcode
    );
    return {
        talabatStatus: window.normalizeMarketplaceStatus(previousEntry && previousEntry.talabatStatus),
        instashopStatus: window.normalizeMarketplaceStatus(previousEntry && previousEntry.instashopStatus)
    };
};

function escapeMarketplaceArchiveHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, character => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    })[character]);
}

window.marketplaceArchiveFilteredData = [];
window.marketplaceArchivePage = 1;
window.marketplaceRecentlyEditedKeys = new Set();
const MARKETPLACE_ARCHIVE_PAGE_SIZE = 50;

function extractMarketplaceItemDate(item) {
    if (!item || !item.regDate) return '';
    if (typeof getCalendarDateKey === 'function') {
        const key = getCalendarDateKey(item.regDate);
        if (key) return key;
    }
    const raw = String(item.regDate).trim();
    const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (match) return `${match[1]}-${match[2]}-${match[3]}`;
    return raw.slice(0, 10);
}

window.setMarketplaceDateRangePreset = function(preset) {
    const startInput = document.getElementById('marketplaceArchiveStartDate');
    const endInput = document.getElementById('marketplaceArchiveEndDate');
    if (!startInput || !endInput) return;

    let refDate = new Date();
    if (startInput.value) {
        const parsed = new Date(startInput.value + 'T00:00:00');
        if (!isNaN(parsed.getTime())) refDate = parsed;
    }
    const year = refDate.getFullYear();
    const month = refDate.getMonth();
    const monthStr = String(month + 1).padStart(2, '0');
    const lastDayOfMonth = new Date(year, month + 1, 0).getDate();

    if (preset === 'first-half') {
        startInput.value = `${year}-${monthStr}-01`;
        endInput.value = `${year}-${monthStr}-15`;
    } else if (preset === 'second-half') {
        startInput.value = `${year}-${monthStr}-16`;
        endInput.value = `${year}-${monthStr}-${String(lastDayOfMonth).padStart(2, '0')}`;
    } else if (preset === 'full-month') {
        startInput.value = `${year}-${monthStr}-01`;
        endInput.value = `${year}-${monthStr}-${String(lastDayOfMonth).padStart(2, '0')}`;
    }

    document.querySelectorAll('.date-range-preset-chip').forEach(chip => {
        chip.classList.toggle('active', chip.dataset.preset === preset);
    });

    if (window.marketplaceRecentlyEditedKeys) window.marketplaceRecentlyEditedKeys.clear();
    window.marketplaceArchivePage = 1;
    window.renderMarketplaceArchive();
};

window.updateMarketplaceKpis = function() {
    const startDate = document.getElementById('marketplaceArchiveStartDate')?.value || '';
    const endDate = document.getElementById('marketplaceArchiveEndDate')?.value || '';
    let tPresent = 0, tAbsent = 0, tUnknown = 0;
    let iPresent = 0, iAbsent = 0, iUnknown = 0;

    (window.receiptsArchiveData || []).forEach(item => {
        const itemDate = extractMarketplaceItemDate(item);
        if (startDate && itemDate && itemDate < startDate) return;
        if (endDate && itemDate && itemDate > endDate) return;
        const ts = window.normalizeMarketplaceStatus(item.talabatStatus);
        const is = window.normalizeMarketplaceStatus(item.instashopStatus);
        if (ts === 'present') tPresent++; else if (ts === 'absent') tAbsent++; else tUnknown++;
        if (is === 'present') iPresent++; else if (is === 'absent') iAbsent++; else iUnknown++;
    });

    const elTalPresent = document.getElementById('kpiTalabatPresent');
    const elTalAbsent = document.getElementById('kpiTalabatAbsent');
    const elTalUnknown = document.getElementById('kpiTalabatUnknown');
    const elInsPresent = document.getElementById('kpiInstashopPresent');
    const elInsAbsent = document.getElementById('kpiInstashopAbsent');
    const elInsUnknown = document.getElementById('kpiInstashopUnknown');

    if (elTalPresent) elTalPresent.textContent = tPresent;
    if (elTalAbsent) elTalAbsent.textContent = tAbsent;
    if (elTalUnknown) elTalUnknown.textContent = tUnknown;
    if (elInsPresent) elInsPresent.textContent = iPresent;
    if (elInsAbsent) elInsAbsent.textContent = iAbsent;
    if (elInsUnknown) elInsUnknown.textContent = iUnknown;
};

window.renderMarketplaceArchive = function() {
    const tbody = document.getElementById('marketplaceArchiveTableBody');
    if (!tbody) return;

    window.updateMarketplaceKpis();

    const startDate = document.getElementById('marketplaceArchiveStartDate')?.value || '';
    const endDate = document.getElementById('marketplaceArchiveEndDate')?.value || '';
    const query = (document.getElementById('marketplaceArchiveSearch')?.value || '').trim().toLowerCase();
    const sortVal = document.getElementById('marketplaceArchiveSort')?.value || 'name_asc';
    const talabatFilter = document.getElementById('marketplaceArchiveTalabatFilter')?.value || 'all';
    const instashopFilter = document.getElementById('marketplaceArchiveInstashopFilter')?.value || 'all';

    const rows = (window.receiptsArchiveData || []).filter(item => {
        const itemDate = extractMarketplaceItemDate(item);
        if (startDate && itemDate && itemDate < startDate) return false;
        if (endDate && itemDate && itemDate > endDate) return false;

        const searchable = `${item.name || ''} ${item.barcode || ''}`.toLowerCase();
        const matchesQuery = !query || searchable.includes(query);
        const matchesTalabat = talabatFilter === 'all' || window.normalizeMarketplaceStatus(item.talabatStatus) === talabatFilter;
        const matchesInstashop = instashopFilter === 'all' || window.normalizeMarketplaceStatus(item.instashopStatus) === instashopFilter;

        // ثبات الصف: إذا قام المستخدم بتعديل هذا الصنف في الجلسة الحالية، يظل ظاهراً حتى لا يختفي قبل تعديل المنصة الأخرى
        const itemKey = item.barcode ? `barcode:${String(item.barcode).trim().toLowerCase()}` : `id:${item.id}`;
        const isRecentlyModified = window.marketplaceRecentlyEditedKeys && window.marketplaceRecentlyEditedKeys.has(itemKey);
        const matchesFilter = (matchesTalabat && matchesInstashop) || isRecentlyModified;

        return matchesQuery && matchesFilter;
    });

    // 🔤 فرز وترتيب الأصناف (الافتراضي: أبجدي أ - ي لضمان ثبات كامل وعدم تغير أماكن الأصناف بعد التحديد)
    rows.sort((a, b) => {
        if (sortVal === 'name_asc') {
            const cmp = String(a.name || '').localeCompare(String(b.name || ''), 'ar');
            if (cmp !== 0) return cmp;
            return String(a.barcode || '').localeCompare(String(b.barcode || ''));
        } else if (sortVal === 'name_desc') {
            const cmp = String(b.name || '').localeCompare(String(a.name || ''), 'ar');
            if (cmp !== 0) return cmp;
            return String(b.barcode || '').localeCompare(String(a.barcode || ''));
        } else if (sortVal === 'date_desc') {
            return (typeof getSortDateValue === 'function' ? getSortDateValue(b.regDate) : 0) -
                   (typeof getSortDateValue === 'function' ? getSortDateValue(a.regDate) : 0);
        } else if (sortVal === 'date_asc') {
            return (typeof getSortDateValue === 'function' ? getSortDateValue(a.regDate) : 0) -
                   (typeof getSortDateValue === 'function' ? getSortDateValue(b.regDate) : 0);
        }
        return 0;
    });

    window.marketplaceArchiveFilteredData = rows;
    const pageCount = Math.max(1, Math.ceil(rows.length / MARKETPLACE_ARCHIVE_PAGE_SIZE));
    window.marketplaceArchivePage = Math.min(Math.max(1, window.marketplaceArchivePage), pageCount);
    const pageStart = (window.marketplaceArchivePage - 1) * MARKETPLACE_ARCHIVE_PAGE_SIZE;
    const visibleRows = rows.slice(pageStart, pageStart + MARKETPLACE_ARCHIVE_PAGE_SIZE);
    const count = document.getElementById('marketplaceArchiveCount');
    const pageInfo = document.getElementById('marketplaceArchivePageInfo');
    if (count) count.textContent = `${rows.length} منتج`;
    if (pageInfo) pageInfo.innerHTML = `<span>صفحة <b class="page-current">${window.marketplaceArchivePage}</b> من <b class="page-total">${pageCount}</b></span>`;
    const previousButton = document.getElementById('marketplaceArchivePrevBtn');
    const nextButton = document.getElementById('marketplaceArchiveNextBtn');
    if (previousButton) previousButton.disabled = window.marketplaceArchivePage <= 1;
    if (nextButton) nextButton.disabled = window.marketplaceArchivePage >= pageCount;
    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" class="marketplace-archive-empty">لا توجد سجلات مطابقة. جرّب تغيير الفترة المحددة أو الفلاتر.</td></tr>';
        return;
    }

    const renderMarketplaceCustomSelect = (id, barcode, name, platform, status) => {
        const safeName = escapeMarketplaceArchiveHtml(name || '');
        const currentLabel = window.marketplaceStatusLabel(status);
        return `
            <div class="marketplace-custom-select marketplace-custom-select--${platform}" 
                data-archive-id="${id}" 
                data-archive-barcode="${barcode}" 
                data-archive-name="${safeName}" 
                data-marketplace-status="${platform}" 
                data-status="${status}">
                <button type="button" class="marketplace-custom-select__btn" aria-haspopup="listbox" aria-expanded="false" title="تغيير حالة ${platform === 'talabat' ? 'طلبات' : 'InstaShop'}">
                    <span class="marketplace-status-dot dot--${status}"></span>
                    <span class="marketplace-status-text">${currentLabel}</span>
                    <i class="fa-solid fa-chevron-down marketplace-custom-select__arrow"></i>
                </button>
                <div class="marketplace-custom-select__menu" role="listbox">
                    <div class="marketplace-custom-select__option option--present ${status === 'present' ? 'is-selected' : ''}" data-value="present" role="option">
                        <span class="marketplace-status-dot dot--present"></span>
                        <span class="option-label">موجود</span>
                    </div>
                    <div class="marketplace-custom-select__option option--absent ${status === 'absent' ? 'is-selected' : ''}" data-value="absent" role="option">
                        <span class="marketplace-status-dot dot--absent"></span>
                        <span class="option-label">غير موجود</span>
                    </div>
                    <div class="marketplace-custom-select__option option--unknown ${status === 'unknown' ? 'is-selected' : ''}" data-value="unknown" role="option">
                        <span class="marketplace-status-dot dot--unknown"></span>
                        <span class="option-label">غير محدد</span>
                    </div>
                </div>
            </div>`;
    };

    tbody.innerHTML = visibleRows.map(item => {
        const id = escapeMarketplaceArchiveHtml(item.id || '');
        const barcode = escapeMarketplaceArchiveHtml(item.barcode || '');
        const talabatStatus = window.normalizeMarketplaceStatus(item.talabatStatus);
        const instashopStatus = window.normalizeMarketplaceStatus(item.instashopStatus);
        const registrationDate = escapeMarketplaceArchiveHtml(item.regDate || '-');
        const itemKey = barcode ? `barcode:${barcode.toLowerCase()}` : `id:${id}`;
        const isRecentlyModified = window.marketplaceRecentlyEditedKeys && window.marketplaceRecentlyEditedKeys.has(itemKey);

        return `
            <tr class="${isRecentlyModified ? 'marketplace-row--recently-modified' : ''}" data-row-key="${itemKey}">
                <td class="marketplace-product-name" data-label="المنتج">
                    <div class="marketplace-prod-name-wrap">
                        <span class="marketplace-name-text">${escapeMarketplaceArchiveHtml(item.name || 'اسم غير مسجل')}</span>
                        ${isRecentlyModified ? '<span class="marketplace-modified-tag" title="تم تعديل هذا المنتج ويظل ظاهراً حتى تغيير الفلتر"><i class="fa-solid fa-clock-rotate-left"></i> مُعدّل مؤقتاً</span>' : ''}
                    </div>
                </td>
                <td class="marketplace-barcode" data-label="الباركود" dir="ltr">
                    ${barcode ? `
                        <button type="button" class="marketplace-barcode-pill" data-barcode="${barcode}" title="انقر لنسخ الباركود">
                            <span class="barcode-pill-text">${barcode}</span>
                            <i class="fa-regular fa-copy barcode-pill-icon"></i>
                        </button>
                    ` : '<span class="marketplace-no-barcode">-</span>'}
                </td>
                <td class="marketplace-reg-date" data-label="تاريخ التسجيل" dir="ltr">${registrationDate}</td>
                <td class="marketplace-col-talabat" data-label="طلبات">
                    ${renderMarketplaceCustomSelect(id, barcode, item.name, 'talabat', talabatStatus)}
                </td>
                <td class="marketplace-col-instashop" data-label="InstaShop">
                    ${renderMarketplaceCustomSelect(id, barcode, item.name, 'instashop', instashopStatus)}
                </td>
            </tr>`;
    }).join('');
};

async function saveMarketplaceArchiveStatus(customSelect, targetStatus) {
    const platform = customSelect.dataset.marketplaceStatus;
    const barcode = String(customSelect.dataset.archiveBarcode || '').trim();
    const productName = String(customSelect.dataset.archiveName || '').trim();
    const id = customSelect.dataset.archiveId;
    const status = window.normalizeMarketplaceStatus(targetStatus);
    const field = platform === 'talabat' ? 'talabat_status' : platform === 'instashop' ? 'instashop_status' : '';
    if (!field) throw new Error('منصة غير معروفة لتحديث الحالة.');
    if (!barcode && !id && !productName) throw new Error('لا يوجد باركود أو معرّف لهذا السجل.');

    // حفظ في قاعدة بيانات Supabase
    let query = supabase.from('expiry_receipts_log').update({ [field]: status });
    if (barcode) {
        query = query.eq('barcode', barcode);
    } else if (id) {
        query = query.eq('id', id);
    } else {
        query = query.eq('product_name', productName);
    }
    const { error } = await query;
    if (error) throw error;

    // تسجيل الصنف كمُعدّل لمنع اختفائه أثناء الفلترة
    const itemKey = barcode ? `barcode:${barcode.toLowerCase()}` : `id:${id}`;
    if (!window.marketplaceRecentlyEditedKeys) window.marketplaceRecentlyEditedKeys = new Set();
    window.marketplaceRecentlyEditedKeys.add(itemKey);

    // تحديث ذاكرة السجلات الحالية
    const normalizedBarcode = barcode.toLowerCase();
    (window.receiptsArchiveData || []).forEach(item => {
        const matches = barcode
            ? String(item.barcode || '').trim().toLowerCase() === normalizedBarcode
            : (id && String(item.id) === String(id)) || (productName && String(item.name || '').trim() === productName);
        if (matches) {
            if (platform === 'talabat') item.talabatStatus = status;
            else item.instashopStatus = status;
        }
    });

    // تحديث عناصر القائمة المخصصة الحالية
    customSelect.dataset.status = status;
    const btn = customSelect.querySelector('.marketplace-custom-select__btn');
    if (btn) {
        const textSpan = btn.querySelector('.marketplace-status-text');
        const dotSpan = btn.querySelector('.marketplace-status-dot');
        if (textSpan) textSpan.textContent = window.marketplaceStatusLabel(status);
        if (dotSpan) dotSpan.className = `marketplace-status-dot dot--${status}`;
    }
    customSelect.querySelectorAll('.marketplace-custom-select__option').forEach(opt => {
        opt.classList.toggle('is-selected', opt.dataset.value === status);
    });

    // إظهار شارة التعديل على الصف في حال عدم وجودها
    const row = customSelect.closest('tr');
    if (row && !row.classList.contains('marketplace-row--recently-modified')) {
        row.classList.add('marketplace-row--recently-modified');
        const nameWrap = row.querySelector('.marketplace-prod-name-wrap');
        if (nameWrap && !nameWrap.querySelector('.marketplace-modified-tag')) {
            const tag = document.createElement('span');
            tag.className = 'marketplace-modified-tag';
            tag.title = 'تم تعديل هذا المنتج ويظل ظاهراً حتى تغيير الفلتر';
            tag.innerHTML = '<i class="fa-solid fa-clock-rotate-left"></i> مُعدّل مؤقتاً';
            nameWrap.appendChild(tag);
        }
    }

    // تحديث شريط الإحصائيات الحية
    window.updateMarketplaceKpis();
}

document.addEventListener('DOMContentLoaded', () => {
    const startInput = document.getElementById('marketplaceArchiveStartDate');
    const endInput = document.getElementById('marketplaceArchiveEndDate');
    if (startInput && endInput && !startInput.value && !endInput.value) {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        const monthStr = String(month + 1).padStart(2, '0');
        const lastDay = new Date(year, month + 1, 0).getDate();
        startInput.value = `${year}-${monthStr}-01`;
        endInput.value = `${year}-${monthStr}-${String(lastDay).padStart(2, '0')}`;
    }

    // تصفير قائمة المعدّلات مؤقتاً عند تعديل أي فلتر يدوي للبحث وتحديث الجدول فورياً
    ['marketplaceArchiveStartDate', 'marketplaceArchiveEndDate', 'marketplaceArchiveSearch', 'marketplaceArchiveSort', 'marketplaceArchiveTalabatFilter', 'marketplaceArchiveInstashopFilter']
        .forEach(id => {
            const el = document.getElementById(id);
            if (!el) return;
            const eventName = (el.tagName === 'SELECT' || el.type === 'date') ? 'change' : 'input';
            el.addEventListener(eventName, () => {
                if (id === 'marketplaceArchiveStartDate' || id === 'marketplaceArchiveEndDate') {
                    const s = startInput?.value || '';
                    const e = endInput?.value || '';
                    document.querySelectorAll('.date-range-preset-chip').forEach(chip => {
                        const p = chip.dataset.preset;
                        let matches = false;
                        if (s && e) {
                            const y = s.slice(0, 4);
                            const m = s.slice(5, 7);
                            const lastDay = new Date(Number(y), Number(m), 0).getDate();
                            if (p === 'first-half' && s === `${y}-${m}-01` && e === `${y}-${m}-15`) matches = true;
                            if (p === 'second-half' && s === `${y}-${m}-16` && e === `${y}-${m}-${String(lastDay).padStart(2, '0')}`) matches = true;
                            if (p === 'full-month' && s === `${y}-${m}-01` && e === `${y}-${m}-${String(lastDay).padStart(2, '0')}`) matches = true;
                        }
                        chip.classList.toggle('active', matches);
                    });
                }
                if (window.marketplaceRecentlyEditedKeys) window.marketplaceRecentlyEditedKeys.clear();
                window.marketplaceArchivePage = 1;
                window.renderMarketplaceArchive();
            });
        });

    document.getElementById('marketplaceArchivePrevBtn')?.addEventListener('click', () => {
        window.marketplaceArchivePage -= 1;
        window.renderMarketplaceArchive();
        document.querySelector('.marketplace-archive-table-wrap')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
    document.getElementById('marketplaceArchiveNextBtn')?.addEventListener('click', () => {
        window.marketplaceArchivePage += 1;
        window.renderMarketplaceArchive();
        document.querySelector('.marketplace-archive-table-wrap')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });

    // استماع النقرات على جدول المتابعة (النسخ والقوائم المنسدلة)
    document.getElementById('marketplaceArchiveTableBody')?.addEventListener('click', event => {
        // 1. نسخ الباركود من الكبسولة التفاعلية
        const barcodeBtn = event.target.closest('.marketplace-barcode-pill');
        if (barcodeBtn) {
            event.preventDefault();
            const barcode = barcodeBtn.dataset.barcode;
            if (barcode) {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(barcode).then(() => {
                        barcodeBtn.classList.add('copied');
                        const icon = barcodeBtn.querySelector('.barcode-pill-icon');
                        if (icon) icon.className = 'fa-solid fa-check barcode-pill-icon';
                        setTimeout(() => {
                            barcodeBtn.classList.remove('copied');
                            if (icon) icon.className = 'fa-regular fa-copy barcode-pill-icon';
                        }, 1200);
                        if (typeof window.showToast === 'function') window.showToast(`تم نسخ الباركود (${barcode}) إلى الحافظة`, 'info');
                    }).catch(() => {
                        window.prompt('انسخ الباركود:', barcode);
                    });
                } else {
                    window.prompt('انسخ الباركود:', barcode);
                }
            }
            return;
        }

        // 2. فتح/إغلاق القائمة المنسدلة المخصصة
        const customSelectBtn = event.target.closest('.marketplace-custom-select__btn');
        if (customSelectBtn) {
            event.preventDefault();
            const customSelect = customSelectBtn.closest('.marketplace-custom-select');
            const willOpen = !customSelect.classList.contains('is-open');
            document.querySelectorAll('.marketplace-custom-select.is-open').forEach(el => {
                if (el !== customSelect) {
                    el.classList.remove('is-open');
                    el.querySelector('.marketplace-custom-select__btn')?.setAttribute('aria-expanded', 'false');
                }
            });
            customSelect.classList.toggle('is-open', willOpen);
            customSelectBtn.setAttribute('aria-expanded', String(willOpen));
            return;
        }

        // 3. اختيار حالة من القائمة المنسدلة المخصصة
        const option = event.target.closest('.marketplace-custom-select__option');
        if (option) {
            event.preventDefault();
            const customSelect = option.closest('.marketplace-custom-select');
            const targetValue = option.dataset.value;
            customSelect.classList.remove('is-open');
            customSelect.querySelector('.marketplace-custom-select__btn')?.setAttribute('aria-expanded', 'false');

            const previousStatus = customSelect.dataset.status;
            if (targetValue === previousStatus) return;

            const btn = customSelect.querySelector('.marketplace-custom-select__btn');
            if (btn) btn.disabled = true;

            saveMarketplaceArchiveStatus(customSelect, targetValue)
                .then(() => {
                    if (typeof window.showToast === 'function') window.showToast('تم حفظ الحالة بنجاح.', 'success');
                })
                .catch(error => {
                    console.error('Marketplace status update failed:', error);
                    if (typeof window.showToast === 'function') {
                        window.showToast(`تعذر حفظ الحالة: ${error.message || 'خطأ غير معروف'}`, 'error');
                    }
                })
                .finally(() => {
                    if (btn) btn.disabled = false;
                });
            return;
        }
    });

    // إغلاق أي قائمة منسدلة مفتوحة عند النقر خارجها
    document.addEventListener('click', event => {
        if (!event.target.closest('.marketplace-custom-select')) {
            document.querySelectorAll('.marketplace-custom-select.is-open').forEach(el => {
                el.classList.remove('is-open');
                el.querySelector('.marketplace-custom-select__btn')?.setAttribute('aria-expanded', 'false');
            });
        }
    });

    // زر التحديث اليدوي
    document.getElementById('refreshMarketplaceArchiveBtn')?.addEventListener('click', async event => {
        const button = event.currentTarget;
        button.disabled = true;
        try {
            if (window.marketplaceRecentlyEditedKeys) window.marketplaceRecentlyEditedKeys.clear();
            const loaded = await window.loadReceiptsArchiveData();
            if (!loaded) throw new Error('لم يتم تحميل بيانات الأرشيف من قاعدة البيانات.');
            window.renderMarketplaceArchive();
            if (typeof window.showToast === 'function') window.showToast('تم تحديث أرشيف المنصات بنجاح.', 'success');
        } catch (error) {
            console.error('Marketplace archive refresh failed:', error);
            if (typeof window.showToast === 'function') window.showToast('تعذر تحديث أرشيف المنصات.', 'error');
        } finally {
            button.disabled = false;
        }
    });

    window.renderMarketplaceArchive();
});

async function handleSupabaseRequest(url, options) {
    let action = null;
    let params = {};
    
    // Parse GET query params
    const urlObj = new URL(url.replace('DISABLED - MIGRATED TO SUPABASE', 'http://localhost'));
    urlObj.searchParams.forEach((val, key) => {
        params[key] = val;
    });
    
    // Parse POST body (URLSearchParams or FormData)
    if (options && options.body) {
        if (options.body instanceof FormData || options.body instanceof URLSearchParams) {
            options.body.forEach((val, key) => {
                params[key] = val;
            });
        }
    }
    
    action = params.action;
    if (!action && params.date) action = 'getStats';
    
    try {
        let responseData = { success: true };
        
        switch (action) {

            case 'addOrder': {
                // Fetch the latest order to get the max order_id
                const { data: latestOrder } = await supabase.from('orders')
                    .select('order_id')
                    .order('id', { ascending: false })
                    .limit(1);
                    
                let nextNum = 1;
                if (latestOrder && latestOrder.length > 0 && latestOrder[0].order_id) {
                    const match = String(latestOrder[0].order_id).match(/\d+/);
                    if (match) {
                        nextNum = parseInt(match[0]) + 1;
                    }
                }
                const newOrderId = 'CANDY-' + String(nextNum).padStart(6, '0');
                
                // Get Date and Time in Egypt time
                const d = new Date();
                const dateStr = d.toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
                const timeStr = d.toLocaleTimeString('en-GB', { timeZone: 'Africa/Cairo' });

                const insertData = {
                    order_id: newOrderId,
                    order_date: dateStr,
                    order_time: timeStr,
                    platform: params.platform || '',
                    customer_name: params.customerName || '',
                    governorate: params.gov || '',
                    address: params.address || '',
                    phone: params.phone1 || '',
                    alt_phone: params.phone2 || '',
                    delivery_type: params.orderType || '',
                    payment_method: params.payMethod || '',
                    delivery_date: params.expDate || '',
                    products: params.products || '',
                    products_total: params.pTotal ? parseFloat(params.pTotal) : 0,
                    discount: params.discount ? parseFloat(params.discount) : 0,
                    shipping_cost: params.shipping ? parseFloat(params.shipping) : 0,
                    final_total: params.finalTotal ? parseFloat(params.finalTotal) : 0,
                    status: 'قيد التجهيز',
                    notes: params.notes || '',
                    moderator_name: params.moderator || '',
                    deposit: params.deposit ? parseFloat(params.deposit) : 0,
                    remaining: params.remaining ? parseFloat(params.remaining) : (params.finalTotal ? parseFloat(params.finalTotal) : 0)
                };

                const { data: inserted, error: insErr } = await supabase.from('orders').insert([insertData]).select();
                if (insErr) {
                    responseData = { success: false, error: insErr.message };
                } else {
                    responseData = { success: true, orderId: newOrderId, message: 'تم الإضافة بنجاح', data: inserted[0] };
                    // Sync customer stats in customers table
                    if (params.phone1) {
                        await updateCustomerStatsInDatabase(params.phone1, { 
                            customer_name: params.customerName, 
                            governorate: params.gov, 
                            address: params.address 
                        });
                    }
                }
                break;
            }

            case 'editOrder':
            case 'updateOrder': {
                const orderId = params.orderId || params.order_id;
                if (!orderId) {
                    responseData = { success: false, error: 'Missing orderId' };
                    break;
                }

                const updateData = {
                    platform: params.platform || '',
                    customer_name: params.customerName || '',
                    governorate: params.gov || '',
                    address: params.address || '',
                    phone: params.phone1 || '',
                    alt_phone: params.phone2 || '',
                    delivery_type: params.orderType || '',
                    payment_method: params.payMethod || '',
                    delivery_date: params.expDate || '',
                    products: params.products || '',
                    products_total: params.pTotal ? parseFloat(params.pTotal) : 0,
                    discount: params.discount ? parseFloat(params.discount) : 0,
                    shipping_cost: params.shipping ? parseFloat(params.shipping) : 0,
                    final_total: params.finalTotal ? parseFloat(params.finalTotal) : 0,
                    notes: params.notes || '',
                    moderator_name: params.moderator || '',
                    deposit: params.deposit ? parseFloat(params.deposit) : 0,
                    remaining: params.remaining ? parseFloat(params.remaining) : (params.finalTotal ? parseFloat(params.finalTotal) : 0)
                };

                const { data: updated, error: updErr } = await supabase.from('orders')
                    .update(updateData)
                    .eq('order_id', orderId)
                    .select();

                if (updErr) {
                    responseData = { success: false, error: updErr.message };
                } else {
                    responseData = { success: true, orderId: orderId, message: 'تم تحديث الأوردر بنجاح', data: updated ? updated[0] : null };
                    if (params.phone1) {
                        await updateCustomerStatsInDatabase(params.phone1, { 
                            customer_name: params.customerName, 
                            governorate: params.gov, 
                            address: params.address 
                        });
                    }
                }
                break;
            }

            case 'updateOrderStatus': {
                const updateData = { status: params.status };
                if (params.driverName !== undefined) updateData.driver_name = params.driverName;
                if (params.orderType !== undefined) updateData.delivery_type = params.orderType;

                const { data: updated, error: updErr } = await supabase.from('orders')
                    .update(updateData)
                    .eq('order_id', params.orderId)
                    .select();

                if (updErr) {
                    responseData = { success: false, error: updErr.message };
                } else {
                    responseData = { success: true, data: updated[0] };
                    if (updated && updated[0] && updated[0].phone) {
                        await updateCustomerStatsInDatabase(updated[0].phone);
                    }
                }
                break;
            }

            case 'suspendOrder': {
                let draftJsonObj = {};
                try {
                    draftJsonObj = JSON.parse(params.draftJson || '{}');
                } catch(e) {}
                
                // Get Date and Time in Egypt time
                const d = new Date();
                const dateStr = d.toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
                const timeStr = d.toLocaleTimeString('en-GB', { timeZone: 'Africa/Cairo' });

                const draftData = {
                    draft_id: params.draftId,
                    suspend_date: dateStr,
                    suspend_time: timeStr,
                    moderator_name: draftJsonObj.moderator || 'غير محدد',
                    customer_name: draftJsonObj.customerName || 'بدون اسم',
                    draft_id: String(params.draftId),
                    draft_json: params.draftJson || '{}'
                };

                const { data: drafted, error: dftErr } = await supabase.from('suspended_orders')
                    .insert([draftData])
                    .select();

                if (dftErr) {
                    console.error('Error suspending order in Supabase:', dftErr);
                    responseData = { success: false, error: dftErr.message };
                } else {
                    responseData = { success: true, data: drafted[0] };
                    responseData = { success: true, data: drafted ? drafted[0] : null };
                }
                break;
            }



            case 'globalSearch': {
                const keyword = (params.query || '').toLowerCase();
                const { data: searchResults } = await fetchAllSupabaseRows(supabase.from('orders').select('*').or(`order_id.ilike.%${keyword}%,customer_name.ilike.%${keyword}%,phone.ilike.%${keyword}%`));
                let results = (searchResults || []).map(o => ({
                    id: o.order_id, date: o.order_date, time: o.order_time,
                    name: o.customer_name, phone: o.phone, phone2: o.alt_phone || "",
                    address: o.address, products: o.products, subtotal: o.products_total,
                    discount: o.discount, shipping: o.shipping_cost, total: parseFloat(o.final_total) || 0,
                    status: o.status, payment: o.payment_method, seller: o.moderator_name,
                    orderType: o.delivery_type, deposit: o.deposit || 0,
                    remaining: o.remaining || o.final_total,
                    gov: o.governorate, platform: o.platform, driver: o.driver_name,
                    reservationDate: o.delivery_date || ""
                })).reverse();
                return createJsonResponse(results); // Return array directly for globalSearch
            }
            case 'getCustomers': {
                const [ { data: rawCust }, { data: rawOrders } ] = await Promise.all([
                    fetchAllSupabaseRows(supabase.from('customers').select('*').order('orders_count', { ascending: false })),
                    fetchAllSupabaseRows(supabase.from('orders').select('phone, final_total, order_date, status'))
                ]);

                let stats = {};
                (rawOrders || []).forEach(o => {
                    let p = String(o.phone).trim();
                    if(!p) return;
                    if(!stats[p]) stats[p] = { count: 0, total: 0, lastDate: '' };
                    
                    if (o.status !== 'ملغي' && o.status !== 'مرتجع') {
                        stats[p].count += 1;
                        stats[p].total += parseFloat(o.final_total) || 0;
                    }
                    if (o.order_date && (!stats[p].lastDate || o.order_date > stats[p].lastDate)) {
                        stats[p].lastDate = o.order_date;
                    }
                });

                responseData.customers = (rawCust || []).map(c => {
                    let p = String(c.phone).trim();
                    let st = stats[p] || { count: c.orders_count || 0, total: c.total_paid || 0, lastDate: c.last_order_date || "" };
                    return {
                        id: c.id,
                        name: c.customer_name,
                        phone: c.phone,
                        gov: c.governorate,
                        address: c.address,
                        count: st.count !== undefined ? st.count : (c.orders_count || 0),
                        total: st.total !== undefined ? Math.round(st.total * 100) / 100 : (c.total_paid || 0),
                        lastDate: st.lastDate || c.last_order_date || ""
                    };
                });
                break;
            }
            case 'getPendingLeaves': {
                const { data: pendingData } = await fetchAllSupabaseRows(supabase.from('attendance').select('*').eq('request_status', 'بانتظار الموافقة'));
                responseData.pending = (pendingData || []).map(r => ({
                    employee: r.employee_name, date: r.date, type: r.status, notes: r.notes
                }));
                break;
            }
            case 'getAttendance': {
                let query = supabase.from('attendance').select('*').order('date', { ascending: true }).order('id', { ascending: true });
                if (params.employee) query = query.eq('employee_name', params.employee);
                if (params.exactDate) query = query.eq('date', params.exactDate);
                else if (params.month) query = query.like('date', params.month + '-%');
                
                const { data: attData } = await fetchAllSupabaseRows(query);
                
                // Deduplicate by employee + date to ensure all views (employee, manager, PDF export) match perfectly
                const dedupedMap = new Map();
                (attData || []).forEach(r => {
                    const key = `${r.employee_name}___${r.date}`;
                    if (!dedupedMap.has(key)) {
                        dedupedMap.set(key, r);
                    } else {
                        const existing = dedupedMap.get(key);
                        const hasCheckOut = r.check_out && r.check_out !== '-' && String(r.check_out).trim() !== '';
                        const existHasCheckOut = existing.check_out && existing.check_out !== '-' && String(existing.check_out).trim() !== '';
                        if (hasCheckOut && !existHasCheckOut) {
                            dedupedMap.set(key, r);
                        } else if (r.status === 'حاضر' && existing.status !== 'حاضر') {
                            dedupedMap.set(key, r);
                        }
                    }
                });

                responseData.attendance = Array.from(dedupedMap.values()).map(r => ({
                    id: r.id, employee: r.employee_name, date: r.date, checkIn: r.check_in, checkOut: r.check_out,
                    hours: r.hours, status: r.status, notes: r.notes, requestStatus: r.request_status
                }));
                break;
            }
            case 'getStats': {
                const month = params.date ? params.date.substring(0, 7) : new Date().toISOString().substring(0, 7);
                const [yr, mo] = month.split('-');
                const lastDay = new Date(parseInt(yr, 10), parseInt(mo, 10), 0).getDate();
                const startMonthDate = `${month}-01`;
                const endMonthDate = `${month}-${String(lastDay).padStart(2, '0')}`;
                const { data: monthOrders, error: mErr } = await fetchAllSupabaseRows(
                    supabase.from('orders').select('*')
                    .gte('order_date', startMonthDate)
                    .lte('order_date', endMonthDate)
                );
                if (mErr) throw mErr;
                
                let topProducts = {};
                let platforms = {};
                let shipping = {};
                let mods = {};
                
                let monthOrderCount = 0;
                let monthSales = 0;
                let completedMonthCount = 0;
                let returnedCount = 0;
                
                (monthOrders || []).forEach(o => {
                    if (o.status !== 'مرتجع') {
                        monthOrderCount++;
                        monthSales += parseFloat(o.final_total || o.total) || 0;
                        
                        // Platforms
                        let p = (o.platform || 'غير محدد').toLowerCase();
                        platforms[p] = (platforms[p] || 0) + 1;
                        
                        // Mods
                        let mod = o.moderator_name || o.seller || o.moderator || 'غير محدد';
                        if (!mods[mod]) mods[mod] = { name: mod, orders: 0, sales: 0 };
                        mods[mod].orders++;
                        mods[mod].sales += parseFloat(o.final_total || o.total) || 0;
                        
                        // Products
                        let prodsLines = [];
                        if (typeof o.products === 'string') {
                            prodsLines = o.products.split('\n');
                        } else if (Array.isArray(o.products)) {
                            o.products.forEach(pObj => {
                                if (pObj && pObj.name) prodsLines.push(...String(pObj.name).split('\n'));
                            });
                        } else if (o.products && typeof o.products === 'object') {
                            if (o.products.name) prodsLines = String(o.products.name).split('\n');
                        }
                        
                        prodsLines.forEach(line => {
                            if (!line.trim()) return;
                            let match = line.match(/^(.+?)\s*[-–]?\s*الكمية:\s*(\d+)/i) || line.match(/^(.+?)\s*\(x(\d+)\)/i);
                            if (match) {
                                let name = match[1].trim();
                                let qty = parseInt(match[2]);
                                if (!topProducts[name]) topProducts[name] = 0;
                                topProducts[name] += qty;
                            } else {
                                let name = line.split('-')[0].trim();
                                if (name) {
                                    if (!topProducts[name]) topProducts[name] = 0;
                                    topProducts[name] += 1;
                                }
                            }
                        });
                    }
                    
                    if (o.status === 'تم التوصيل' || o.status === 'تم التوصيل ومُحاسب') {
                        completedMonthCount++;
                        let gov = o.governorate || 'أخرى';
                        if (!shipping[gov]) shipping[gov] = { name: gov, count: 0, totalShipping: 0 };
                        shipping[gov].count++;
                        shipping[gov].totalShipping += parseFloat(o.shipping_cost || o.shipping) || 0;
                    }
                    
                    if (o.status === 'مرتجع') returnedCount++;
                });
                
                responseData.monthTopProducts = Object.entries(topProducts)
                    .map(([name, qty]) => ({ name, qty }))
                    .sort((a, b) => b.qty - a.qty).slice(0, 10);
                
                responseData.monthPlatforms = platforms;
                responseData.monthZonesStats = Object.values(shipping).sort((a, b) => b.count - a.count);
                
                responseData.monthOrderCount = monthOrderCount;
                responseData.monthSales = monthSales;
                responseData.completedMonthCount = completedMonthCount;
                responseData.returnedCount = returnedCount;
                responseData.modStats = Object.values(mods);
                
                break;
            }

            case 'addShipping':
                await supabase.from('settings_shipping').insert([{ zone_name: params.name, price: params.price, zone_type: params.zoneType === 'alex' ? 'alex' : 'govs', delivery_type: params.deliveryType, duration: params.duration }]);
                break;
            case 'editShipping': {
                let targetName = params.originalName || params.name;
                let updData = { price: params.price, delivery_type: params.deliveryType, duration: params.duration };
                if (params.name) updData.zone_name = params.name;
                if (params.zoneType) updData.zone_type = params.zoneType === 'alex' ? 'alex' : 'govs';
                await supabase.from('settings_shipping').update(updData).eq('zone_name', targetName);
                break;
            }
            case 'addDriver':
                await supabase.from('couriers').insert([{ name: params.name, phone: params.phone }]);
                break;
            case 'editDriver':
                await supabase.from('couriers').update({ phone: params.phone }).eq('name', params.name);
                break;
            case 'addModerator':
                await supabase.from('moderators').insert([{ name: params.name }]);
                break;
            case 'addCustomer':
                await updateCustomerStatsInDatabase(params.phone, { customer_name: params.name, governorate: params.gov, address: params.address });
                responseData = { success: true };
                break;
            case 'addExpiry': {
                let existingZero = null;
                try {
                    const { data: matchedRows } = await supabase.from('expiries')
                        .select('id, qty, status')
                        .eq('product_name', params.name)
                        .eq('expiry_date', params.expiryDate)
                        .limit(5);
                    if (matchedRows && matchedRows.length > 0) {
                        existingZero = matchedRows.find(r => parseFloat(r.qty) <= 0 || r.status === 'نافد');
                    }
                } catch(e) {}

                if (existingZero) {
                    const newQty = parseFloat(params.qty) || 0;
                    await supabase.from('expiries').update({
                        qty: newQty,
                        status: params.status || 'مش في عرض',
                        location: params.location || '',
                        receiver: params.receiver || '',
                        notes: params.notes || '',
                        barcode: params.barcode || '',
                        reg_date: params.regDate || ''
                    }).eq('id', existingZero.id);
                } else {
                    const expRow = { product_name: params.name, qty: params.qty, expiry_date: params.expiryDate, location: params.location, registrar_name: params.regDate, receiver: params.receiver, notes: params.notes, original_price: params.originalPrice, offer_price: params.offerPrice, status: params.status, barcode: params.barcode };
                    await supabase.from('expiries').insert([expRow]);
                }

                try {
                    const arcRow = {
                        product_name: params.name,
                        barcode: params.barcode || '',
                        quantity: params.qty || 0,
                        expiry_date: params.expiryDate || '',
                        location: params.location || '',
                        reg_date: params.regDate || '',
                        receiver: params.receiver || '',
                        notes: params.notes || '',
                        original_price: params.originalPrice || '',
                        offer_price: params.offerPrice || '',
                        status: params.status || ''
                    };
                    const { data: insArc } = await supabase.from('expiry_receipts_log').insert([arcRow]).select('id').single();
                    if (Array.isArray(window.receiptsArchiveData)) {
                        window.receiptsArchiveData.push({
                            id: insArc ? insArc.id : undefined,
                            name: arcRow.product_name,
                            qty: arcRow.quantity,
                            expiryDate: arcRow.expiry_date,
                            location: arcRow.location,
                            regDate: arcRow.reg_date,
                            receiver: arcRow.receiver,
                            notes: arcRow.notes,
                            originalPrice: arcRow.original_price,
                            offerPrice: arcRow.offer_price,
                            status: arcRow.status,
                            barcode: arcRow.barcode
                        });
                        if (typeof window.renderExpiryCalendarDots === 'function') window.renderExpiryCalendarDots();
                    }
                } catch(errLog) {
                    console.warn("Could not insert into expiry_receipts_log:", errLog);
                }
                break;
            }
            case 'addExpiriesBatch': {
                const batchItems = JSON.parse(params.batchData);
                const archiveRows = batchItems.map(item => ({
                    product_name: item.name,
                    barcode: item.barcode || '',
                    quantity: item.qty || 0,
                    expiry_date: item.expiryDate || '',
                    location: item.location || '',
                    reg_date: item.regDate || '',
                    receiver: item.receiver || '',
                    notes: item.notes || '',
                    status: item.status || '',
                    talabat_status: window.normalizeMarketplaceStatus(item.talabatStatus),
                    instashop_status: window.normalizeMarketplaceStatus(item.instashopStatus)
                }));

                const { data: insertedArchiveRows, error: archiveInsertError } = await supabase
                    .from('expiry_receipts_log')
                    .insert(archiveRows)
                    .select('*');
                if (archiveInsertError) {
                    responseData = { success: false, error: `تعذر حفظ سجل الاستلام في الأرشيف: ${archiveInsertError.message}` };
                    break;
                }

                // Restock zero-balance rows or insert new
                const expRowsToInsert = [];
                for (const item of batchItems) {
                    let updatedExisting = false;
                    try {
                        const { data: existingRows } = await supabase.from('expiries')
                            .select('id, qty, status')
                            .eq('product_name', item.name)
                            .eq('expiry_date', item.expiryDate)
                            .limit(5);
                        if (existingRows && existingRows.length > 0) {
                            const zeroRow = existingRows.find(r => parseFloat(r.qty) <= 0 || r.status === 'نافد');
                            if (zeroRow) {
                                await supabase.from('expiries').update({
                                    qty: parseFloat(item.qty) || 0,
                                    status: item.status || 'مش في عرض',
                                    location: item.location || '',
                                    receiver: item.receiver || '',
                                    notes: item.notes || '',
                                    barcode: item.barcode || '',
                                    reg_date: item.regDate || ''
                                }).eq('id', zeroRow.id);
                                updatedExisting = true;
                            }
                        }
                    } catch(e) {}
                    if (!updatedExisting) {
                        expRowsToInsert.push({ product_name: item.name, qty: item.qty, expiry_date: item.expiryDate, location: item.location, reg_date: item.regDate, receiver: item.receiver, notes: item.notes, status: item.status, barcode: item.barcode });
                    }
                }

                if (expRowsToInsert.length > 0) {
                    const { error: expiryInsertError } = await supabase.from('expiries').insert(expRowsToInsert);
                    if (expiryInsertError) {
                        const insertedIds = (insertedArchiveRows || []).map(row => row.id).filter(id => id !== undefined && id !== null);
                        let rollbackError = null;
                        if (insertedIds.length) {
                            const { error } = await supabase.from('expiry_receipts_log').delete().in('id', insertedIds);
                            rollbackError = error;
                        }
                        responseData = {
                            success: false,
                            partial: Boolean(rollbackError),
                            error: rollbackError
                                ? `فشل حفظ الصلاحيات (${expiryInsertError.message}) وتعذر التراجع عن سجل الأرشيف (${rollbackError.message}). راجع الأرشيف قبل إعادة المحاولة.`
                                : `تعذر حفظ الصلاحيات الأساسية: ${expiryInsertError.message}`
                        };
                        break;
                    }
                }

                const latestStatusByBarcode = new Map();
                batchItems.forEach(item => {
                    const barcode = String(item.barcode || '').trim();
                    if (barcode) {
                        latestStatusByBarcode.set(barcode, {
                            talabat_status: window.normalizeMarketplaceStatus(item.talabatStatus),
                            instashop_status: window.normalizeMarketplaceStatus(item.instashopStatus)
                        });
                    }
                });
                let statusSyncError = null;
                for (const [barcode, platformStatuses] of latestStatusByBarcode) {
                    const { error } = await supabase.from('expiry_receipts_log')
                        .update(platformStatuses)
                        .eq('barcode', barcode);
                    if (error) {
                        statusSyncError = error;
                        break;
                    }
                }

                if (Array.isArray(window.receiptsArchiveData)) {
                    const addedRows = (insertedArchiveRows || []).map(row => ({
                        id: row.id,
                        name: row.product_name,
                        qty: row.quantity !== undefined ? parseFloat(row.quantity) : (parseFloat(row.qty) || 0),
                        expiryDate: row.expiry_date,
                        location: row.location || '',
                        regDate: row.reg_date || '',
                        receiver: row.receiver || '',
                        notes: row.notes || '',
                        originalPrice: row.original_price || '',
                        offerPrice: row.offer_price || '',
                        status: row.status || '',
                        barcode: row.barcode || '',
                        talabatStatus: window.normalizeMarketplaceStatus(row.talabat_status),
                        instashopStatus: window.normalizeMarketplaceStatus(row.instashop_status)
                    }));
                    if (!statusSyncError) {
                        addedRows.forEach(row => {
                            const latestStatus = latestStatusByBarcode.get(String(row.barcode || '').trim());
                            if (latestStatus) {
                                row.talabatStatus = latestStatus.talabat_status;
                                row.instashopStatus = latestStatus.instashop_status;
                            }
                        });
                        latestStatusByBarcode.forEach((statuses, barcode) => {
                            window.receiptsArchiveData.forEach(row => {
                                if (String(row.barcode || '').trim() === barcode) {
                                    row.talabatStatus = statuses.talabat_status;
                                    row.instashopStatus = statuses.instashop_status;
                                }
                            });
                        });
                    }
                    window.receiptsArchiveData.push(...addedRows);
                    if (typeof window.renderExpiryCalendarDots === 'function') window.renderExpiryCalendarDots();
                    if (typeof window.renderMarketplaceArchive === 'function') window.renderMarketplaceArchive();
                }
                responseData = statusSyncError
                    ? { success: false, partial: true, error: `تم تسجيل الاستلام، لكن تعذر تحديث الحالات السابقة لنفس الباركود: ${statusSyncError.message}. حدّث الحالة من الأرشيف.` }
                    : { success: true };
                break;
            }
            case 'updateExpiryItemData':
                const idParts = params.id ? String(params.id).split('|') : [];
                const targetName = idParts[0] || params.id;
                let updateFields = { qty: params.qty, expiry_date: params.expiryDate, location: params.location, receiver: params.receiver, notes: params.notes, barcode: params.barcode };
                if (params.productName) {
                    updateFields.product_name = params.productName.trim();
                }
                let q1 = supabase.from('expiries').update(updateFields);
                if (idParts.length >= 4 && idParts[3]) {
                    q1 = q1.eq('id', idParts[3]);
                } else if (params.id && !params.id.includes('|')) {
                    q1 = q1.eq('id', params.id);
                } else {
                    q1 = q1.eq('product_name', targetName);
                    if (idParts[1]) q1 = q1.eq('quantity', idParts[1]);
                    if (idParts[2]) q1 = q1.eq('expiry_date', idParts[2]);
                }
                await q1;
                break;
            case 'updateExpiryStatus':
                const statParts = params.id ? String(params.id).split('|') : [];
                const tName = statParts[0] || params.id;
                let updates = { status: params.status };
                if (params.newQty !== undefined) updates.qty = params.newQty;
                else if (params.qty !== undefined) updates.qty = params.qty;
                if (params.originalPrice) updates.original_price = params.originalPrice;
                if (params.offerPrice) updates.offer_price = params.offerPrice;
                
                let q2 = supabase.from('expiries').update(updates);
                if (params.dbId) {
                    q2 = q2.eq('id', params.dbId);
                } else if (statParts.length >= 4 && statParts[3]) {
                    q2 = q2.eq('id', statParts[3]);
                } else {
                    q2 = q2.eq('product_name', tName);
                    if (statParts[2]) q2 = q2.eq('expiry_date', statParts[2]);
                }
                await q2;

                // Also update catalog
                let catUpdate = {};
                if (params.status === 'في عرض') { catUpdate.is_offer = true; if(params.offerPrice) catUpdate.offer_price = params.offerPrice; }
                else if (params.status === 'مش في عرض') { catUpdate.is_offer = false; catUpdate.offer_price = 0; }
                if (tName !== 'غير محدد' && tName !== 'غير محدد (بانتظار المزامنة)') {
                    await supabase.from('catalog').update(catUpdate).eq('product_name', tName);
                }
                break;
            case 'addOutOfStock':
                await supabase.from('out_of_stock').insert([{ customer_name: params.customer, phone: params.phone, product: params.product, reason: params.reason }]);
                break;
            case 'deleteShipping':
                await window.secureDelete('settings_shipping', 'zone_name', params.name);
                responseData = { success: true };
                break;
            case 'deleteDriver':
                await window.secureDelete('couriers', 'name', params.name);
                responseData = { success: true };
                break;
            case 'deleteModerator':
                await window.secureDelete('moderators', 'name', params.name);
                responseData = { success: true };
                break;
            case 'addUser':
                await supabase.from('users').insert([{ username: params.user, display_name: params.user, password: params.pass, permissions: params.perms, status: 'نشط' }]);
                responseData = { success: true };
                break;
            case 'deleteProduct':
                await window.secureDelete('catalog', 'product_name', params.name);
                responseData = { success: true };
                break;
            case 'updateCatalog':
                await supabase.from('catalog').update({ price: params.price, available: params.avail }).eq('product_name', params.name);
                responseData = { success: true };
                break;
            case 'addExpiriesBatch':
                const expItems = JSON.parse(params.itemsStr || "[]");
                await supabase.from('expiries').insert(expItems.map(item => ({
                    product_name: item.name,
                    expiry_date: item.exp,
                    quantity: item.qty,
                    original_price: item.price,
                    status: 'صلاحية قريبة'
                })));
                responseData = { success: true };
                break;
            case 'updateExpiryItemData':
                await supabase.from('expiries').update({ status: params.status, offer_price: params.offerPrice, notes: params.notes }).eq('product_name', params.product);
                responseData = { success: true };
                break;
            case 'deleteOutOfStock':
                if (params.id) {
                    await supabase.from('out_of_stock').delete().eq('id', params.id);
                } else {
                    await supabase.from('out_of_stock').delete().eq('product', params.product).ilike('phone', '%' + params.phone + '%');
                }
                break;
            case 'addInventoryLog':
                await supabase.from('inventory_logs').insert([{ log_id: params.logId, from_location: params.from, to_location: params.to, reg_name: params.regName, items: params.items, notes: params.notes, timestamp: new Date().toLocaleString() }]);
                break;
            case 'checkIn': {
                const empName = params.employeeName;
                const todayDate = params.date || (window.getSyncedDate ? window.getSyncedDate() : new Date()).toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
                
                const { data: existIn, error: existErr } = await supabase.from('attendance')
                    .select('*')
                    .eq('employee_name', empName)
                    .eq('date', todayDate)
                    .eq('status', 'حاضر');
                
                if (existErr) {
                    return createJsonResponse({ success: false, error: "خطأ في التحقق من الحضور: " + existErr.message });
                }
                if (existIn && existIn.length > 0) {
                    return createJsonResponse({ success: false, error: "أنت مسجل حضور بالفعل اليوم" });
                }

                const checkInTime = (window.getSyncedDate ? window.getSyncedDate() : new Date()).toLocaleTimeString('en-US', { hour12: true, hour: '2-digit', minute:'2-digit', timeZone: 'Africa/Cairo' });
                const { error: insErr } = await supabase.from('attendance').insert([{ 
                    employee_name: empName, 
                    date: todayDate, 
                    check_in: checkInTime, 
                    status: 'حاضر' 
                }]);

                if (insErr) {
                    return createJsonResponse({ success: false, error: "فشل تسجيل الحضور: " + insErr.message });
                }

                responseData = { success: true, message: "تم تسجيل الحضور بنجاح", time: checkInTime };
                break;
            }
            case 'checkOut': {
                const empName = params.employeeName;
                const todayDate = params.date || (window.getSyncedDate ? window.getSyncedDate() : new Date()).toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });

                // Fetch attendance records for this employee with status 'حاضر'
                const { data: attRecords, error: fetchErr } = await supabase.from('attendance')
                    .select('*')
                    .eq('employee_name', empName)
                    .eq('status', 'حاضر')
                    .order('date', { ascending: false });

                if (fetchErr) {
                    return createJsonResponse({ success: false, error: "خطأ في قراءة بيانات الحضور: " + fetchErr.message });
                }

                if (!attRecords || attRecords.length === 0) {
                    return createJsonResponse({ success: false, error: "لم يتم العثور على سجل حضور مفتوح" });
                }

                // Best matching record:
                // 1. Open record for today (check_out is null / empty / '-')
                let targetRecord = attRecords.find(r => r.date === todayDate && (!r.check_out || r.check_out === '-' || String(r.check_out).trim() === ''));
                
                // 2. Any open record for this employee (e.g. overnight shift started yesterday)
                if (!targetRecord) {
                    targetRecord = attRecords.find(r => !r.check_out || r.check_out === '-' || String(r.check_out).trim() === '');
                }

                // 3. Fallback: record for today
                if (!targetRecord) {
                    targetRecord = attRecords.find(r => r.date === todayDate);
                }

                if (!targetRecord) {
                    return createJsonResponse({ success: false, error: "لم يتم العثور على سجل حضور مفتوح" });
                }

                const checkInTime = targetRecord.check_in;
                const checkOutTime = (window.getSyncedDate ? window.getSyncedDate() : new Date()).toLocaleTimeString('en-US', { hour12: true, hour: '2-digit', minute:'2-digit', timeZone: 'Africa/Cairo' });
                const hoursStr = calculateAttendanceHoursString(checkInTime, checkOutTime, targetRecord.date, todayDate);

                const { error: updErr } = await supabase.from('attendance')
                    .update({ check_out: checkOutTime, hours: hoursStr })
                    .eq('id', targetRecord.id);

                if (updErr) {
                    return createJsonResponse({ success: false, error: "فشل حفظ تسجيل الانصراف: " + updErr.message });
                }

                responseData = { success: true, message: "تم تسجيل الانصراف بنجاح", time: checkOutTime, hours: hoursStr };
                break;
            }
            case 'requestLeave':
                await supabase.from('attendance').insert([{ employee_name: params.employeeName, date: params.date, status: params.leaveType, request_status: 'بانتظار الموافقة', notes: params.notes }]);
                responseData = { success: true, message: "تم إرسال طلب الإجازة" };
                break;
            case 'manageLeave': {
                let updateData = { request_status: params.decision === 'approve' ? '✅ تمت الموافقة' : '❌ مرفوضة' };
                if (params.decision === 'approve') {
                    updateData.hours = '8:00';
                }
                const { error: mngErr } = await supabase.from('attendance').update(updateData).eq('employee_name', params.employeeName).eq('date', params.date);
                if (mngErr) return createJsonResponse({ success: false, error: mngErr.message });
                responseData = { success: true };
                break;
            }
            case 'bulkUploadAttendance':
                const attItems = JSON.parse(params.dataStr || "[]");
                const attRows = attItems.map(item => ({ employee_name: item.empName, date: item.date, check_in: item.checkIn, check_out: item.checkOut, hours: item.hours, status: item.status, notes: item.notes }));
                await supabase.from('attendance').insert(attRows);
                responseData = { success: true };
                break;
            case 'editAttendance': {
                let targetId = params.recordId ? parseInt(params.recordId, 10) : null;
                
                // If recordId not provided or invalid, find existing record by employee and date
                if (!targetId) {
                    const { data: existAtt } = await supabase.from('attendance')
                        .select('id')
                        .eq('employee_name', params.employeeName)
                        .eq('date', params.date)
                        .order('id', { ascending: true })
                        .limit(1);
                    if (existAtt && existAtt.length > 0) {
                        targetId = existAtt[0].id;
                    }
                }

                if (targetId) {
                    const { error: editErr } = await supabase.from('attendance')
                        .update({
                            check_in: params.checkIn,
                            check_out: params.checkOut,
                            hours: params.hours,
                            status: params.status,
                            notes: params.notes
                        })
                        .eq('id', targetId);
                    if (editErr) return createJsonResponse({ success: false, error: editErr.message });
                    
                    // Clean up any other duplicate records for this employee on this date to eliminate ghost rows
                    try {
                        await supabase.from('attendance')
                            .delete()
                            .eq('employee_name', params.employeeName)
                            .eq('date', params.date)
                            .neq('id', targetId);
                    } catch(cleanErr) {
                        console.warn('Duplicate cleanup warning:', cleanErr);
                    }
                } else {
                    const { error: insAttErr } = await supabase.from('attendance').insert([{
                        employee_name: params.employeeName,
                        date: params.date,
                        check_in: params.checkIn,
                        check_out: params.checkOut,
                        hours: params.hours,
                        status: params.status || 'حاضر',
                        notes: params.notes
                    }]);
                    if (insAttErr) return createJsonResponse({ success: false, error: insAttErr.message });
                }
                responseData = { success: true };
                break;
            }
            case 'addLeaveByAdmin': {
                const { error: leaveErr } = await supabase.from('attendance').insert([{ employee_name: params.employeeName, date: params.date, status: params.type, notes: params.notes }]);
                if (leaveErr) return createJsonResponse({ success: false, error: leaveErr.message });
                responseData = { success: true };
                break;
            }
            case 'removeDuplicates':
                // For simplicity, skip complex logic as unique constraints typically handle this, just return success
                responseData = { success: true };
                break;
            case 'settleOrder': {
                const { data: updatedOrd } = await supabase.from('orders').update({
                    status: 'تم التوصيل ومُحاسب',
                    final_total: params.finalTotal,
                    products_total: params.productsTotal,
                    discount: params.discount,
                    shipping_cost: params.shipping
                }).eq('order_id', params.orderId).select('phone');
                if (updatedOrd && updatedOrd[0] && updatedOrd[0].phone) {
                    await updateCustomerStatsInDatabase(updatedOrd[0].phone);
                }
                responseData = { success: true };
                break;
            }
            
            case 'deleteUser':
                await window.secureDelete('users', 'username', params.user);
                break;
            case 'addShipping':
                await supabase.from('settings_shipping').insert([{ zone_name: params.name, price: params.price, delivery_type: params.deliveryType, duration: params.duration, zone_type: params.zoneType }]);
                responseData = { success: true };
                break;
            case 'editShipping':
                await supabase.from('settings_shipping').update({ price: params.price, duration: params.duration }).eq('zone_name', params.name);
                responseData = { success: true };
                break;
            case 'addDriver':
                await supabase.from('couriers').insert([{ name: params.name, phone: params.phone }]);
                responseData = { success: true };
                break;
            case 'editDriver':
                await supabase.from('couriers').update({ phone: params.phone }).eq('name', params.name);
                responseData = { success: true };
                break;
            case 'addExpiry':
                await supabase.from('expiries').insert([{
                    product_name: params.name, quantity: params.qty, expiry_date: params.expiryDate,
                    location: params.location, reg_date: params.regDate, receiver: params.receiver,
                    notes: params.notes, original_price: params.originalPrice || '', offer_price: params.offerPrice || '',
                    status: params.status || '', barcode: params.barcode || ''
                }]);
                responseData = { success: true };
                break;
            case 'removeSuspended':
                await supabase.from('suspended_orders').delete().eq('draft_id', params.draftId);
                responseData = { success: true };
                break;
            case 'addUser': {
                const { data: existUser } = await supabase.from('users').select('*').eq('username', params.username);
                if (existUser && existUser.length > 0) {
                    return createJsonResponse({ success: false, error: 'اسم المستخدم موجود بالفعل' });
                }
                await supabase.from('users').insert([{ username: params.username, password: params.password, display_name: params.displayName, permissions: params.permissions, status: 'نشط' }]);
                responseData = { success: true };
                break;
            }
            case 'updateUser': {
                let userUpdates = {};
                if (params.displayName) userUpdates.display_name = params.displayName;
                if (params.permissions) userUpdates.permissions = params.permissions;
                if (params.status) userUpdates.status = params.status;
                if (params.newPassword && params.newPassword !== '') userUpdates.password = params.newPassword;
                await supabase.from('users').update(userUpdates).eq('username', params.username);
                responseData = { success: true };
                break;
            }
            case 'addBulkAttendance': {
                const bulkRecords = JSON.parse(params.records || '[]');
                const bulkRows = bulkRecords.map(rec => ({
                    employee_name: rec.empName, date: rec.date, check_in: rec.checkIn,
                    check_out: rec.checkOut, hours: rec.hours, status: rec.status,
                    request_status: rec.reqStatus || '', notes: rec.notes || ''
                }));
                if (bulkRows.length > 0) await supabase.from('attendance').insert(bulkRows);
                responseData = { success: true, message: 'تم رفع البيانات بنجاح' };
                break;
            }
            case 'fixAmPmData':
                responseData = { success: true, fixedCount: 0 };
                break;
            case 'getInventoryLogs': {
                let invQuery = supabase.from('inventory_logs').select('*');
                if (params.q) {
                    let searchId = String(params.q).toUpperCase();
                    if (!searchId.startsWith('TRX-')) searchId = 'TRX-' + searchId;
                    invQuery = invQuery.eq('log_id', searchId);
                } else {
                    invQuery = invQuery.order('id', { ascending: false });
                }
                const { data: invData } = await invQuery;
                responseData = (invData || []).map(log => ({
                    logId: log.log_id || log.id, from: log.from_location, to: log.to_location,
                    regName: log.reg_name, timestamp: log.timestamp, items: log.items, notes: log.notes
                }));
                break;
            }
            case 'getExpiries': {
                const { data: expData } = await fetchAllSupabaseRows(supabase.from('expiries').select('*'));
                responseData = { expiries: (expData || []).map(e => ({
                    id: (e.product_name || '') + '|' + (e.quantity || '') + '|' + (e.expiry_date || '') + (e.id ? '|' + e.id : ''),
                    name: e.product_name || '', qty: e.quantity || '', expiryDate: e.expiry_date || '',
                    location: e.location || '', registrarName: e.registrar_name || '', regDate: e.reg_date || '',
                    receiver: e.receiver || '', notes: e.notes || '', originalPrice: e.original_price || '',
                    offerPrice: e.offer_price || '', status: e.status || '', barcode: e.barcode || ''
                })) };
                break;
            }
            case 'syncFirebaseInventory': {
                try {
                    if (typeof window.updateSyncProgress === 'function') {
                        window.updateSyncProgress(15, '<i class="fa-solid fa-cloud-arrow-down"></i> جاري جلب بضاعة الكاشير من الفايربيز...');
                    }

                    // 1. Fetch Firebase data
                    const fbResp = await fetch('https://candyclubsync-default-rtdb.firebaseio.com/products.json');
                    const fbDataRaw = await fbResp.json();
                    const fbItems = Array.isArray(fbDataRaw) ? fbDataRaw : Object.values(fbDataRaw || {});
                    const fbStockMap = {};
                    const fbProductMap = new Map();

                    const aliases = window.KNOWN_BARCODE_ALIASES || {
                        '5011061058027': '7015661058027',
                        '7015661058027': '5011061058027',
                        '855400091266': '8857660091266',
                        '8857660091266': '855400091266'
                    };

                    fbItems.forEach(item => {
                        if (!item) return;
                        const b = item.Barcode;
                        const name = String(item.Name || '').trim();
                        const stock = parseFloat(item.Stock) || 0;
                        const price = parseFloat(item.Price) || 0;

                        let canonicalKey = '';
                        if (Array.isArray(b) && b.length > 0) canonicalKey = String(b[0]).trim();
                        else if (b) canonicalKey = String(b).trim();
                        if (!canonicalKey) canonicalKey = name;

                        const addBarcodeEntry = (code) => {
                            if (!code) return;
                            const parts = String(code).split(',');
                            for (let p of parts) {
                                const clean = p.trim();
                                if (clean) {
                                    fbStockMap[clean] = stock;
                                    fbStockMap[clean.toLowerCase()] = stock;
                                    if (name) {
                                        fbProductMap.set(clean, { name, price, stock, canonicalKey });
                                        fbProductMap.set(clean.toLowerCase(), { name, price, stock, canonicalKey });
                                    }
                                }
                            }
                        };
                        if (Array.isArray(b)) {
                            b.forEach(addBarcodeEntry);
                        } else if (b) {
                            addBarcodeEntry(b);
                        }
                    });

                    // ربط الباركودات البديلة المعروفة لضمان التطابق التلقائي المتبادل مع أصناف الكاشير
                    for (const [aliasBc, origBc] of Object.entries(aliases)) {
                        if (fbProductMap.has(origBc)) {
                            const pData = fbProductMap.get(origBc);
                            fbProductMap.set(aliasBc, pData);
                            fbProductMap.set(aliasBc.toLowerCase(), pData);
                            if (fbStockMap.hasOwnProperty(origBc)) {
                                fbStockMap[aliasBc] = fbStockMap[origBc];
                            }
                        }
                        if (fbProductMap.has(aliasBc)) {
                            const pData = fbProductMap.get(aliasBc);
                            fbProductMap.set(origBc, pData);
                            fbProductMap.set(origBc.toLowerCase(), pData);
                            if (fbStockMap.hasOwnProperty(aliasBc)) {
                                fbStockMap[origBc] = fbStockMap[aliasBc];
                            }
                        }
                    }

                    // دالة ذكية للبحث عن المنتج باستخدام كافة تنوعات الباركود والبادئات
                    const findFbProduct = (barcodeStr) => {
                        if (!barcodeStr) return null;
                        const variants = (typeof window.getBarcodeVariants === 'function')
                            ? window.getBarcodeVariants(barcodeStr)
                            : String(barcodeStr).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
                        for (let v of variants) {
                            if (fbProductMap.has(v)) return fbProductMap.get(v);
                            if (fbProductMap.has(v.toLowerCase())) return fbProductMap.get(v.toLowerCase());
                        }
                        return null;
                    };

                    if (typeof window.updateSyncProgress === 'function') {
                        window.updateSyncProgress(30, `<i class="fa-solid fa-boxes-stacked"></i> تم تحميل ${fbItems.length} صنف، جاري فحص الصلاحيات...`);
                    }

                    // 2. Fetch Supabase expiries
                    const { data: gsData } = await fetchAllSupabaseRows(supabase.from('expiries').select('*'));
                    let namesUpdatedCount = 0;
                    const expiriesNamesToUpdate = [];

                    if (gsData && gsData.length > 0) {
                        for (const row of gsData) {
                            const bcode = String(row.barcode || '').trim();
                            const currentName = String(row.product_name || '').trim();
                            if (!bcode) continue;

                            const match = findFbProduct(bcode);
                            if (match && match.name && match.name.trim() && match.name.trim() !== currentName) {
                                expiriesNamesToUpdate.push({ id: row.id, newName: match.name.trim(), row });
                            }
                        }
                    }

                    // تحديث أسماء الأصناف في جدول الصلاحيات بشكل متوازي سريع (حزم من 15)
                    if (expiriesNamesToUpdate.length > 0) {
                        for (let i = 0; i < expiriesNamesToUpdate.length; i += 15) {
                            const chunk = expiriesNamesToUpdate.slice(i, i + 15);
                            await Promise.all(chunk.map(async item => {
                                await supabase.from('expiries').update({ product_name: item.newName }).eq('id', item.id);
                                item.row.product_name = item.newName;
                                namesUpdatedCount++;
                            }));
                            const pct = Math.min(55, 30 + Math.round((i / expiriesNamesToUpdate.length) * 25));
                            if (typeof window.updateSyncProgress === 'function') {
                                window.updateSyncProgress(pct, `<i class="fa-solid fa-pen"></i> جاري تحديث أسماء الصلاحيات (${namesUpdatedCount} / ${expiriesNamesToUpdate.length})...`);
                            }
                        }
                    }

                    // 3. Update placeholder/outdated product names in immutable archive (expiry_receipts_log) by barcode ONLY (strictly leaves quantities untouched)
                    let archiveUpdatedCount = 0;
                    try {
                        const { data: archiveRows, error: arcErr } = await fetchAllSupabaseRows(
                            supabase.from('expiry_receipts_log')
                                .select('id, barcode, product_name')
                                .not('barcode', 'is', null)
                                .neq('barcode', '')
                        );
                        if (!arcErr && Array.isArray(archiveRows)) {
                            const archiveNamesToUpdate = [];
                            for (const arcRow of archiveRows) {
                                const bcode = String(arcRow.barcode || '').trim();
                                const curName = String(arcRow.product_name || '').trim();
                                if (!bcode) continue;

                                const match = findFbProduct(bcode);
                                if (match && match.name && match.name.trim() && match.name.trim() !== curName) {
                                    archiveNamesToUpdate.push({ id: arcRow.id, newName: match.name.trim() });
                                }
                            }
                            if (archiveNamesToUpdate.length > 0) {
                                for (let i = 0; i < archiveNamesToUpdate.length; i += 15) {
                                    const chunk = archiveNamesToUpdate.slice(i, i + 15);
                                    await Promise.all(chunk.map(async item => {
                                        await supabase.from('expiry_receipts_log').update({ product_name: item.newName }).eq('id', item.id);
                                        if (Array.isArray(window.receiptsArchiveData)) {
                                            let winItem = window.receiptsArchiveData.find(w => String(w.id) === String(item.id));
                                            if (winItem) winItem.name = item.newName;
                                        }
                                        archiveUpdatedCount++;
                                    }));
                                }
                            }
                        }
                    } catch(e) {
                        console.warn("Could not sync names to expiry_receipts_log:", e);
                    }

                    // 4. تطبيق نظام التخصيم التلقائي للمبيعات (FIFO) حصرياً على جدول الصلاحيات الحية (expiries)
                    // ملاحظة هامة: سجل الأرشيف (expiry_receipts_log) يظل ثابتاً تماماً دون أي مساس بكمياته
                    let deductedProductsCount = 0;
                    let totalDeductedPieces = 0;

                    if (typeof window.updateSyncProgress === 'function') {
                        window.updateSyncProgress(65, '<i class="fa-solid fa-calculator"></i> جاري مقارنة وتخصيم المبيعات بنظام FIFO...');
                    }

                    if (gsData && gsData.length > 0) {
                        const productBatchesMap = new Map();

                        gsData.forEach(row => {
                            const bcode = String(row.barcode || '').trim();
                            if (!bcode) return;
                            const match = findFbProduct(bcode);
                            if (!match) return;

                            const prodKey = match.canonicalKey || bcode;
                            if (!productBatchesMap.has(prodKey)) {
                                productBatchesMap.set(prodKey, {
                                    fbStock: match.stock,
                                    prodName: match.name,
                                    rows: []
                                });
                            }
                            const entry = productBatchesMap.get(prodKey);
                            entry.rows.push({
                                id: row.id,
                                qty: parseFloat(row.qty) || 0,
                                expiryDate: row.expiry_date || '',
                                name: row.product_name
                            });
                        });

                        const batchesToUpdate = [];

                        for (const [prodKey, prodInfo] of productBatchesMap.entries()) {
                            const totalSystemQty = prodInfo.rows.reduce((sum, r) => sum + r.qty, 0);
                            const fbStock = prodInfo.fbStock;

                            // إذا كان رصيد الكاشير أقل من المسجل بالصلاحيات = تم بيع بضاعة
                            const diff = totalSystemQty - fbStock;
                            if (diff > 0.0001) {
                                let qtyToDeduct = diff;
                                let productHadDeduction = false;

                                // ترتيب الدفعات حسب تاريخ الانتهاء تصاعدياً (الأقرب انتهاءً أولاً FIFO)
                                const sortedRows = prodInfo.rows.sort((a, b) => {
                                    const dateA = new Date(a.expiryDate);
                                    const dateB = new Date(b.expiryDate);
                                    const timeA = isNaN(dateA.getTime()) ? 9999999999999 : dateA.getTime();
                                    const timeB = isNaN(dateB.getTime()) ? 9999999999999 : dateB.getTime();
                                    return timeA - timeB;
                                });

                                for (const r of sortedRows) {
                                    if (qtyToDeduct <= 0) break;
                                    if (r.qty > 0) {
                                        const deductFromThisRow = Math.min(r.qty, qtyToDeduct);
                                        const newQty = Number(Math.max(0, r.qty - deductFromThisRow).toFixed(3));
                                        qtyToDeduct -= deductFromThisRow;

                                        batchesToUpdate.push({ id: r.id, newQty, row: r });
                                        productHadDeduction = true;
                                        totalDeductedPieces += deductFromThisRow;
                                    }
                                }

                                if (productHadDeduction) {
                                    deductedProductsCount++;
                                }
                            }
                        }

                        // تنفيذ تحديثات التخصيم بالتوازي بحزم سريعة
                        if (batchesToUpdate.length > 0) {
                            for (let i = 0; i < batchesToUpdate.length; i += 15) {
                                const chunk = batchesToUpdate.slice(i, i + 15);
                                await Promise.all(chunk.map(async b => {
                                    await supabase.from('expiries').update({ qty: String(b.newQty) }).eq('id', b.id);
                                    if (typeof expiryData !== 'undefined' && Array.isArray(expiryData)) {
                                        let inMem = expiryData.find(e => String(e.id || '').endsWith(String(b.id)));
                                        if (inMem) inMem.qty = String(b.newQty);
                                    }
                                }));
                                const pct = Math.min(90, 65 + Math.round((i / batchesToUpdate.length) * 25));
                                if (typeof window.updateSyncProgress === 'function') {
                                    window.updateSyncProgress(pct, `<i class="fa-solid fa-arrow-down-short-wide"></i> جاري حفظ التخصيم (${Math.min(i + 15, batchesToUpdate.length)} / ${batchesToUpdate.length} دفعة)...`);
                                }
                            }
                        }
                    }

                    let msgParts = [];
                    const totalNamesUpdated = namesUpdatedCount + archiveUpdatedCount;
                    if (totalNamesUpdated > 0) {
                        msgParts.push(`تم تحديث أسماء ${totalNamesUpdated} منتج`);
                    }
                    if (deductedProductsCount > 0) {
                        msgParts.push(`تم تخصيم مبيعات ${totalDeductedPieces} قطعة لـ ${deductedProductsCount} صنف (الأقرب انتهاءً أولاً)`);
                    }
                    if (msgParts.length === 0) {
                        msgParts.push('الأرصدة وأسماء المنتجات متطابقة تماماً مع الكاشير');
                    }
                    responseData = { success: true, message: msgParts.join(' | ') };
                } catch (fbErr) {
                    responseData = { success: false, error: 'فشل الاتصال بقاعدة بيانات الفايربيز: ' + fbErr.message };
                }
                break;
            }
            default:
                console.log("Unhandled Supabase action:", action);
                break;
        }
        
        // ⭐ Bump system version if mutating action succeeded
        if (action && !action.startsWith('get') && responseData && responseData.success !== false) {
            if (typeof window.bumpSystemActivity === 'function') {
                window.bumpSystemActivity();
            }
        }

        return createJsonResponse(responseData);
        
    } catch (err) {
        console.error("Supabase Interceptor Error:", err);
        if (typeof showToast === 'function') showToast("حدث خطأ في الاتصال بقاعدة البيانات", "error");
        return createJsonResponse({ success: false, error: err.message });
    }
}

function createJsonResponse(data) {
    return {
        ok: true,
        status: 200,
        json: async () => data,
        text: async () => JSON.stringify(data)
    };
}



window.formatTimeInput = function(input) {
    let val = input.value.replace(/[^\d]/g, '');
    if (val.length > 2) {
        val = val.substring(0, 2) + ':' + val.substring(2, 4);
    } else {
        val = val.substring(0, 2);
    }
    input.value = val;
};

function parseAttendanceTimeToMinutes(timeStr) {
    if (!timeStr) return null;
    let s = String(timeStr).trim();
    s = s.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
    let isPM = /م|pm/i.test(s);
    let isAM = /ص|am/i.test(s);
    
    let match = s.match(/(\d{1,2}):(\d{1,2})/);
    if (!match) return null;
    let h = parseInt(match[1], 10);
    let m = parseInt(match[2], 10);
    
    if (isPM && h !== 12) h += 12;
    if (isAM && h === 12) h = 0;
    
    return h * 60 + m;
}

function calculateAttendanceHoursString(inTimeStr, outTimeStr, inDate, outDate) {
    let inMins = parseAttendanceTimeToMinutes(inTimeStr);
    let outMins = parseAttendanceTimeToMinutes(outTimeStr);
    if (inMins === null || outMins === null) return "0 ساعة";
    
    let diffMins = outMins - inMins;
    if (inDate && outDate && inDate !== outDate) {
        try {
            let d1 = new Date(inDate + 'T00:00:00');
            let d2 = new Date(outDate + 'T00:00:00');
            let days = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));
            if (days === 1) {
                // Legitimate overnight shift (e.g. 10 PM to 6 AM)
                diffMins += 24 * 60;
            } else if (days > 1) {
                // Multi-day gap (forgot to checkout days ago) -> calculate as normal shift within 24h
                if (diffMins < 0) diffMins += 24 * 60;
            }
        } catch(e) {}
    } else if (diffMins < 0) {
        diffMins += 24 * 60;
    }
    
    if (diffMins < 0) diffMins = 0;
    let h = Math.floor(diffMins / 60);
    let m = diffMins % 60;
    return h + ' ساعة' + (m > 0 ? ' و ' + m + ' دقيقة' : '');
}

function formatHoursDisplay(hStr) {
    if (!hStr || hStr === '-') return '-';
    hStr = String(hStr).trim();
    if (hStr.includes(':')) {
        let p = hStr.replace('ساعة', '').trim().split(':');
        return String(parseInt(p[0]||0)).padStart(2, '0') + ':' + String(parseInt(p[1]||0)).padStart(2, '0');
    }
    
    let h = 0;
    let hMatch = hStr.match(/(\d+(?:\.\d+)?)\s*ساعة/);
    let mMatch = hStr.match(/(\d+(?:\.\d+)?)\s*دقيقة/);
    
    if (hMatch) {
        h += parseFloat(hMatch[1]);
    } else if (!isNaN(parseFloat(hStr))) {
        h += parseFloat(hStr);
    }
    
    if (mMatch) {
        h += parseFloat(mMatch[1]) / 60;
    }
    
    if (h === 0 && !hStr.includes('0')) return hStr; // Fallback to original text if couldn't parse
    
    let tHrs = Math.floor(h);
    let tMins = Math.round((h - tHrs) * 60);
    if (tMins === 60) { tHrs++; tMins = 0; }
    
    return String(tHrs).padStart(2, '0') + ":" + String(tMins).padStart(2, '0');
}


// ⭐ V16: متغير المستخدم الحالي
let currentUser = null;

// Defensive wrapper for any external handleKeyDown handlers that may access undefined values.
// This avoids uncaught TypeError crashes when a third-party script binds document.handleKeyDown.
(function () {
    function safeHandleKeyDown(original) {
        function wrapped(event) {
            if (!event || !event.target) {
                return;
            }
            try {
                return original.call(this, event);
            } catch (err) {
                console.warn('Wrapped handleKeyDown caught error:', err);
                return;
            }
        }
        wrapped.__isSafeWrapped = true;
        return wrapped;
    }

    function patchDocumentHandleKeyDown() {
        try {
            const doc = document;
            const current = doc.handleKeyDown;
            if (typeof current === 'function' && !current.__isSafeWrapped) {
                doc.handleKeyDown = safeHandleKeyDown(current);
            }
        } catch (err) {
            console.warn('patchDocumentHandleKeyDown failed:', err);
        }
    }

    document.addEventListener('DOMContentLoaded', patchDocumentHandleKeyDown);
    window.addEventListener('load', patchDocumentHandleKeyDown);

    let attempts = 0;
    const intervalId = setInterval(() => {
        patchDocumentHandleKeyDown();
        attempts += 1;
        if (attempts >= 5) {
            clearInterval(intervalId);
        }
    }, 500);
})();

