// ⭐ التحكم الدقيق في إظهار زر الطلبات المعلقة وزر معلقات البوكيه حسب الشاشة النشطة
window.updateSuspendedButtonVisibility = function(targetId) {
    const suspendedBtn = document.getElementById('openSuspendedBtn');
    const giftsSuspendedBtn = document.getElementById('openGiftsSuspendedBtn');

    let isCreateTab = false;
    let isGiftsTab = false;

    if (typeof targetId === 'string' && targetId) {
        isCreateTab = (targetId === 'create-tab');
        isGiftsTab = (targetId === 'gifts-tab' || targetId === 'gifts-reports-tab');
    } else {
        const createTab = document.getElementById('create-tab');
        isCreateTab = createTab ? (createTab.classList.contains('active') || createTab.style.display === 'block') : false;
        const giftsTab = document.getElementById('gifts-tab');
        const giftsReportsTab = document.getElementById('gifts-reports-tab');
        isGiftsTab = (giftsTab && (giftsTab.classList.contains('active') || giftsTab.style.display === 'block')) ||
                     (giftsReportsTab && (giftsReportsTab.classList.contains('active') || giftsReportsTab.style.display === 'block'));
    }

    if (suspendedBtn) {
        if (isCreateTab) {
            suspendedBtn.classList.remove('is-hidden-tab');
            suspendedBtn.style.setProperty('display', 'inline-flex', 'important');
        } else {
            suspendedBtn.classList.add('is-hidden-tab');
            suspendedBtn.style.setProperty('display', 'none', 'important');
        }
    }

    if (giftsSuspendedBtn) {
        if (isGiftsTab) {
            giftsSuspendedBtn.classList.remove('is-hidden-tab');
            giftsSuspendedBtn.style.setProperty('display', 'inline-flex', 'important');
            if (window.GiftsApp && typeof GiftsApp.updateSuspendedBadge === 'function') {
                GiftsApp.updateSuspendedBadge();
            }
        } else {
            giftsSuspendedBtn.classList.add('is-hidden-tab');
            giftsSuspendedBtn.style.setProperty('display', 'none', 'important');
        }
    }
};

document.querySelectorAll('.nav-item').forEach(btn => {
    btn.addEventListener('click', (e) => {
        if (btn.classList.contains('locked-nav-item')) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            if (window.showToast) {
                window.showToast("ليس لديك صلاحية لفتح هذه الشاشة. تواصل مع الإدارة للإشتراك 🔒", "error");
            }
            return false;
        }
        
        let targetId = btn.getAttribute('data-target');
        
        // ⭐ تحديد القسم الجديد
        let newModuleGroup = null;
        for (let group in window.MODULE_GROUPS) {
            if (window.MODULE_GROUPS[group].tabs.includes(targetId)) {
                newModuleGroup = group;
                break;
            }
        }
        
        // إذا كان هناك انتقال لقسم جديد تماماً، نظهر شاشة التحميل
        if (newModuleGroup && newModuleGroup !== window.currentActiveModuleGroup) {
            window.currentActiveModuleGroup = newModuleGroup;
            
            let overlay = document.getElementById('module-loading-overlay');
            let loadingText = document.getElementById('module-loading-text');
            let loadingIcon = document.getElementById('module-loading-icon');
            
            if (overlay && loadingText && loadingIcon) {
                let modData = window.MODULE_GROUPS[newModuleGroup];
                loadingText.innerText = `جاري تحميل ${modData.name}...`;
                loadingIcon.className = modData.icon;
                // لون أيقونة مختلف لكل قسم
                let colors = { 'orders': '#E91E8C', 'marketing': '#1565C0', 'products': '#e67e22', 'hr': '#00897b', 'gifts': '#E91E8C', 'admin': '#795548' };
                loadingIcon.style.color = colors[newModuleGroup] || 'var(--primary)';
                
                // overlay.style.display = 'flex'; // DISABLED FOR SPEED
            }
            
            // جلب البيانات الخاصة بالقسم الجديد فقط إذا كان القسم يحتاجها والمستخدم يملك الصلاحية
            if (typeof loadDataFromServer === 'function' && typeof window.shouldLoadCoreOrdersData === 'function' && window.shouldLoadCoreOrdersData()) {
                if (['orders', 'admin'].includes(newModuleGroup)) {
                    loadDataFromServer();
                }
            }
        }

        document.querySelectorAll('.nav-item').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.tab-pane').forEach(c => c.classList.remove('active'));
        btn.classList.add('active');
        let targetElement = document.getElementById(targetId);
        if (targetElement) targetElement.classList.add('active');
        
        // ⭐ V16: تحميل المستخدمين إذا تم فتح التاب
        if (targetId === 'users-tab') {
            loadUsersList();
        } else if (targetId === 'branch-settings-tab') {
            if (typeof window.loadBranchSettingsAdmin === 'function') window.loadBranchSettingsAdmin();
        } else if (targetId === 'dashboard-tab') {
            if (typeof window.loadModeratorSlaAdmin === 'function') window.loadModeratorSlaAdmin();
        }
        if (targetId === 'waitlist-tab') {
            if (typeof initWaitlistTab === 'function') initWaitlistTab();
            if (typeof renderWaitlistTab === 'function') renderWaitlistTab();
        }
        if (targetId === 'hr-tab') { if (typeof initHrTab === 'function') initHrTab(); }
        if (targetId === 'hr-admin-tab') { if (typeof initHrAdminTab === 'function') initHrAdminTab(); }
        if (targetId === 'gifts-tab') {
            let subtab = btn.getAttribute('data-subtab') || 'builder';
            if (typeof window.lazyLoadGiftsModule === 'function') {
                window.lazyLoadGiftsModule(subtab);
            }
        }
        if (targetId === 'gifts-reports-tab') {
            let subtab = btn.getAttribute('data-subtab') || 'analytics';
            if (typeof window.lazyLoadGiftsReportsModule === 'function') {
                window.lazyLoadGiftsReportsModule(subtab);
            }
        }

        // إظهار زر المعلقات فقط عند فتح صفحة إنشاء الطلبات وإخفاؤه تماماً في باقي الصفحات
        if (typeof window.updateSuspendedButtonVisibility === 'function') {
            window.updateSuspendedButtonVisibility(targetId);
        }

        // 🚨 فحص حالة أوردرات المودريتور فور فتح خانة إنشاء الطلبات
        if (targetId === 'create-tab' && typeof window.checkModeratorShippingStatus === 'function') {
            window.checkModeratorShippingStatus();
        }

        // Load expiry data every time the tab is opened, with a custom loading screen
        if (btn.getAttribute('data-target') === 'expiry-tab') {
            loadExpiryData(); // Fetch fresh data every time
            
            // Set default reg date to today if empty
            let regDateInput = document.getElementById('expRegDate');
            if (regDateInput && !regDateInput.value) {
                let today = new Date();
                let yyyy = today.getFullYear();
                let mm = String(today.getMonth() + 1).padStart(2, '0');
                let dd = String(today.getDate()).padStart(2, '0');
                regDateInput.value = `${yyyy}-${mm}-${dd}`;
            }
            if (typeof window.initCustomMonthPicker === 'function') {
                window.initCustomMonthPicker();
            }
        } else if (btn.getAttribute('data-target') === 'offers-tab') {
            if (typeof window.initOffersTab === 'function') {
                window.initOffersTab();
            }
        } else if (btn.getAttribute('data-target') === 'price-tags-tab') {
            if (typeof initPriceTagsTab === 'function') {
                initPriceTagsTab();
            }
        } else if (btn.getAttribute('data-target') === 'moderators-tab') {
            if (typeof renderModeratorsDashboard === 'function') {
                renderModeratorsDashboard();
            }
        } else if (btn.getAttribute('data-target') === 'shipping-tab') {
            if (typeof renderShippingRoom === 'function') {
                renderShippingRoom();
            }
        } else {
            // Memory cleanup: Clear expiryData when leaving the tab to free up memory
            if (typeof expiryData !== 'undefined' && expiryData.length > 0) {
                // Save active offers before clearing so the catalog doesn't break
                window.cachedActiveOffers = expiryData.filter(item => item.status === 'في عرض').map(item => item.name);
                expiryData = [];
                
                const detailsList = document.getElementById('detailsList');
                if (detailsList) detailsList.innerHTML = '';
                const detailsSection = document.getElementById('expiryDetailsSection');
                if (detailsSection) detailsSection.style.display = 'none';
                
                // Reset counters
                ['expOffersItems','expTotalItems','expCriticalItems','expAlertItems','expAttentionItems','expSafeItems','expFarItems'].forEach(id => {
                    let el = document.getElementById(id);
                    if (el) el.innerText = '0';
                });
            }
        }
    });
});

// ⭐ مراقبة فورية لتبديل الشاشات لضمان بقاء زر الطلبات المعلقة محصوراً بشاشة إنشاء الطلبات فقط
try {
    const tabPanes = document.querySelectorAll('.tab-pane');
    if (tabPanes.length > 0 && typeof MutationObserver !== 'undefined') {
        const tabObserver = new MutationObserver(() => {
            if (typeof window.updateSuspendedButtonVisibility === 'function') {
                window.updateSuspendedButtonVisibility();
            }
        });
        tabPanes.forEach(tp => {
            tabObserver.observe(tp, { attributes: true, attributeFilter: ['class', 'style'] });
        });
    }
} catch (e) {
    console.warn("Tab observer init error:", e);
}

// فحص وتحديث الحالة المبدئية عند بدء التشغيل
