// ==========================================
// ⭐ الزر الموحد للتحديث الشامل للنظام بالكامل (طلبات، مخزون، بوكيهات، ومنتجات)
// ==========================================
window.refreshAllSystemData = async function() {
    const quickRefreshBtn = document.getElementById('quickRefreshBtn');
    const refreshIcon = quickRefreshBtn ? quickRefreshBtn.querySelector('i') : null;
    if (refreshIcon) refreshIcon.classList.add('fa-spin');
    if (quickRefreshBtn) quickRefreshBtn.style.pointerEvents = 'none';

    if (typeof showToast === 'function') {
        showToast("جاري تحديث كافة البيانات والمنتجات...", "warning");
    }

    // تفريغ الكاش لإجبار الجلب المباشر
    window.supabaseStaticCache = {};
    try {
        localStorage.removeItem('candy_firebase_products_cache');
    } catch(e) {}

    try {
        await Promise.allSettled([
            typeof fetchCatalogFromFirebase === 'function' ? fetchCatalogFromFirebase() : Promise.resolve(),
            typeof loadDataFromServer === 'function' ? loadDataFromServer() : Promise.resolve()
        ]);

        // تحديث موديول البوكيهات والهدايا بالكامل إن كان مفعّلاً
        if (window.GiftsApp) {
            try {
                if (typeof window.GiftsApp.loadCatalogProducts === 'function') {
                    await window.GiftsApp.loadCatalogProducts();
                }
                if (typeof window.GiftsApp.loadBouquets === 'function') {
                    await window.GiftsApp.loadBouquets();
                }
                if (typeof window.GiftsApp.updateHeaderStats === 'function') {
                    window.GiftsApp.updateHeaderStats();
                }
                if (typeof window.GiftsApp.renderShowcase === 'function') {
                    window.GiftsApp.renderShowcase();
                }
                if (typeof window.GiftsApp.renderCatalogView === 'function') {
                    window.GiftsApp.renderCatalogView();
                }
            } catch (errGifts) {
                console.warn("Gifts module refresh warning:", errGifts);
            }
        }

        if (typeof showToast === 'function') {
            showToast("تم تحديث كافة البيانات والمنتجات والبوكيهات بنجاح", "success");
        }
    } catch (err) {
        console.error("Global refresh error:", err);
        if (typeof showToast === 'function') {
            showToast("حدث خطأ أثناء التحديث", "error");
        }
    } finally {
        if (refreshIcon) refreshIcon.classList.remove('fa-spin');
        if (quickRefreshBtn) quickRefreshBtn.style.pointerEvents = 'auto';
    }
};

// ==========================================
// ⭐ Smart System Version & Global Activity Tracker (V16.3)
// ==========================================
window.lastKnownSystemVersion = parseInt(localStorage.getItem('cc_last_system_activity') || '0', 10);

window.bumpSystemActivity = async function() {
    const now = Date.now();
    window.lastKnownSystemVersion = now;
    localStorage.setItem('cc_last_system_activity', String(now));
    
    try {
        const { data, error } = await supabase
            .from('settings_shipping')
            .select('id')
            .eq('zone_name', '_SYSTEM_VERSION_')
            .eq('zone_type', 'system')
            .limit(1);

        if (data && data.length > 0) {
            await supabase
                .from('settings_shipping')
                .update({ price: now, delivery_type: String(now) })
                .eq('id', data[0].id);
        } else {
            await supabase
                .from('settings_shipping')
                .insert([{
                    zone_name: '_SYSTEM_VERSION_',
                    zone_type: 'system',
                    price: now,
                    delivery_type: String(now)
                }]);
        }
    } catch (e) {
        console.warn('[SmartSync] Silent bumpSystemActivity error:', e);
    }
};

window.checkAndSyncSystemUpdates = async function(force = false) {
    // 1. If tab is in background (hidden) and not forced, skip to save network & logs
    if (document.hidden && !force) {
        return;
    }
    // 2. If a modal is open, avoid interrupting user interaction
    if (document.querySelector('.modal-overlay.active')) {
        return;
    }

    try {
        // Lightweight check: ONLY query the system version timestamp (~50 bytes)
        const { data, error } = await supabase
            .from('settings_shipping')
            .select('price')
            .eq('zone_name', '_SYSTEM_VERSION_')
            .eq('zone_type', 'system')
            .limit(1);

        if (error) {
            console.warn('[SmartSync] Error fetching version:', error);
            return;
        }

        if (!data || data.length === 0) {
            // First time initialization if row doesn't exist
            window.bumpSystemActivity();
            return;
        }

        const serverVersion = parseFloat(data[0].price) || 0;

        // If server has a newer timestamp than our local known version
        if (serverVersion > (window.lastKnownSystemVersion || 0) || force) {
            console.log(`[SmartSync] New activity detected on server (${serverVersion} > ${window.lastKnownSystemVersion}). Refreshing data...`);
            window.lastKnownSystemVersion = serverVersion;
            localStorage.setItem('cc_last_system_activity', String(serverVersion));
            
            if (typeof loadDataFromServer === 'function') {
                await loadDataFromServer();
            }
        } else {
            console.log('[SmartSync] No new activity detected. Skipping heavy database fetch.');
        }
    } catch (err) {
        console.warn('[SmartSync] Check failed silently:', err);
    }
};

window.supabaseStaticCache = {};
const CACHE_RULES = {
    'users': 60 * 60 * 1000,
    'settings_shipping': 60 * 60 * 1000,
    'couriers': 60 * 60 * 1000,
    'moderators': 60 * 60 * 1000,
    'catalog': 2 * 60 * 1000 
};

async function fetchCachedSupabaseTable(tableName, queryBuilder) {
    let now = Date.now();
    let cacheInfo = window.supabaseStaticCache[tableName];
    let expiry = CACHE_RULES[tableName] || 0;
    
    if (expiry > 0 && cacheInfo && (now - cacheInfo.timestamp < expiry)) {
        return { data: cacheInfo.data, error: cacheInfo.error };
    }
    
    const result = await fetchAllSupabaseRows(queryBuilder);
    if (!result.error) {
        window.supabaseStaticCache[tableName] = { data: result.data, error: result.error, timestamp: now };
    }
    return result;
}

// 🛡️ فاحص الصلاحيات الذكي لتجنب تحميل جداول الأوردرات والشحن والحسابات الضخمة للموظفين غير المصرح لهم (كقسم الهدايا أو شئون الموظفين)
window.shouldLoadCoreOrdersData = function() {
    let u = window.currentUser || (typeof currentUser !== 'undefined' ? currentUser : null);
    if (!u) {
        try {
            const stored = localStorage.getItem('cc_user');
            if (stored) u = JSON.parse(stored);
        } catch(e) {}
    }
    if (!u) return false;
    if (u.permissions === 'ALL') return true;
    const perms = String(u.permissions || '').split(',').map(p => p.trim());
    const coreOrderPerms = [
        'create', 'history', 'shipping', 'moderators', 'reports', 
        'shortages', 'financials', 'catalog', 'customers', 'suspended'
    ];
    return perms.some(p => coreOrderPerms.includes(p));
};

async function loadDataFromServer(customDate = null) {
    const syncStatus = document.getElementById('sync-status');

    // ⚡ حماية الأجهزة الضعيفة: إذا كان الموظف لا يملك صلاحيات قسم الأوردرات/التقارير (مثل موظفي الهدايا فقط)، يتم تخطي جلب الـ 15 جدول
    if (!window.shouldLoadCoreOrdersData()) {
        console.log('[Performance Guard] Skipping 15 heavy Supabase tables: user permissions do not require core orders/shipping/financials.');
        if (syncStatus) { syncStatus.innerText = "متصل"; syncStatus.style.color = "#10b981"; }
        return;
    }

    if (syncStatus) { syncStatus.innerText = "جاري التحميل..."; syncStatus.style.color = "#FF8C00"; }

    let hrAdminTab = document.getElementById('hr-admin-tab');
    if (hrAdminTab && hrAdminTab.classList.contains('active')) {
        if (typeof initHrAdminTab === 'function') setTimeout(initHrAdminTab, 100);
    }
    let hrTab = document.getElementById('hr-tab');
    if (hrTab && hrTab.classList.contains('active')) {
        if (typeof initHrTab === 'function') setTimeout(initHrTab, 100);
    }

    let fetchDate = customDate || currentFilterDate;
    let todayReal = new Date().toLocaleDateString('en-CA');
    let currentMonth = fetchDate.substring(0, 7);
    let todayMonth = todayReal.substring(0, 7);

    try {
        // Fetch all data in parallel
        const [
            { data: rawHistory, error: eh1 },
            { data: rawPending, error: eh2 },
            { data: rawShipped, error: eh3 },
            { data: rawUncollected, error: eh4 },
            { data: rawCustomers, error: e2 },
            { data: rawCatalog, error: e3 },
            { data: rawUsers, error: e4 },
            { data: rawShipping, error: e5 },
            { data: rawCouriers, error: e6 },
            { data: rawModerators, error: e7 },
            { data: rawOOS, error: e8 },
            { data: rawSuspended, error: e9 },
            { data: rawExpiries, error: e10 },
            { data: rawSettled, error: e11 },
            { data: rawRecentSettled, error: e12 }
        ] = await Promise.all([
            supabase.from('orders').select('*').eq('order_date', fetchDate).order('created_at', { ascending: false }).range(0, 49),
            fetchAllSupabaseRows(supabase.from('orders').select('*').eq('status', 'قيد التجهيز')),
            fetchAllSupabaseRows(supabase.from('orders').select('*').eq('status', 'في الشحن')),
            fetchAllSupabaseRows(supabase.from('orders').select('*').eq('status', 'تم التوصيل')),
            fetchAllSupabaseRows(supabase.from('customers').select('*').order('created_at', { ascending: true })),
            fetchCachedSupabaseTable('catalog', supabase.from('catalog').select('*').order('created_at', { ascending: true })),
            fetchCachedSupabaseTable('users', supabase.from('users').select('*').order('created_at', { ascending: true })),
            fetchCachedSupabaseTable('settings_shipping', supabase.from('settings_shipping').select('*')),
            fetchCachedSupabaseTable('couriers', supabase.from('couriers').select('*')),
            fetchCachedSupabaseTable('moderators', supabase.from('moderators').select('*')),
            fetchAllSupabaseRows(supabase.from('out_of_stock').select('*')),
            fetchAllSupabaseRows(supabase.from('suspended_orders').select('*')),
            fetchAllSupabaseRows(supabase.from('expiries').select('*')),
            fetchAllSupabaseRows(supabase.from('orders').select('driver_name,shipping_cost,order_date,status').eq('status', 'تم التوصيل ومُحاسب')),
            supabase.from('orders').select('*').eq('status', 'تم التوصيل ومُحاسب').order('id', { ascending: false }).range(0, 49)
        ]);

        for (const err of [eh1, eh2, eh3, eh4, e2, e3, e4, e5, e6, e7, e8, e9, e10, e11, e12]) {
            if (err) throw err;
        }

        // Combine orders efficiently
        let allOrdersMap = new Map();
        if (rawHistory) rawHistory.forEach(o => allOrdersMap.set(o.order_id, o));
        if (rawPending) rawPending.forEach(o => allOrdersMap.set(o.order_id, o));
        if (rawShipped) rawShipped.forEach(o => allOrdersMap.set(o.order_id, o));
        if (rawUncollected) rawUncollected.forEach(o => allOrdersMap.set(o.order_id, o));
        if (rawRecentSettled) rawRecentSettled.forEach(o => allOrdersMap.set(o.order_id, o));
        
        let rawOrders = Array.from(allOrdersMap.values());

        // Extract mapping to a reusable helper
        window.mapOrderRowToLocal = function(o) {
            return {
                id: o.order_id,
                date: o.order_date,
                time: o.order_time,
                platform: o.platform,
                name: o.customer_name,
                gov: o.governorate,
                address: o.address,
                phone: o.phone,
                phone2: o.alt_phone || "",
                orderType: o.delivery_type,
                paymentMethod: o.payment_method || "",
                payment: o.payment_method || "",
                driver: o.driver_name || "",
                deliveryDate: o.delivery_date || "",
                reservationDate: o.delivery_date || "",
                products: o.products || "",
                subtotal: o.products_total,
                discount: o.discount,
                shipping: o.shipping_cost,
                total: parseFloat(o.final_total) || 0,
                status: o.status,
                notes: o.notes,
                seller: o.moderator_name || "",
                moderator: o.moderator_name || "",
                deposit: o.deposit || 0,
                remaining: (o.remaining !== undefined && o.remaining !== null && o.remaining !== "") ? o.remaining : o.final_total,
                raw_remaining: o.remaining,
                createdAt: o.created_at || (o.order_date ? (o.order_date + 'T' + (o.order_time || '00:00:00')) : '')
            };
        };

        // Transform orders
        let allOrders = (rawOrders || []).map(window.mapOrderRowToLocal);

        // History for selected date
        let historyOrders = allOrders.filter(o => o.date === fetchDate);

        // Pending orders (قيد التجهيز)
        let pendingOrders = allOrders.filter(o => o.status === "قيد التجهيز");

        // Shipped orders
        let shippedOrders = allOrders.filter(o => o.status === "في الشحن" && o.driver);

        // Uncollected (تم التوصيل)
        let uncollectedOrders = allOrders.filter(o => o.status === "تم التوصيل" && o.driver);

        // Set global variables
        window.allOrdersData = allOrders;
        orderHistoryData = historyOrders;
        window.orderHistoryData = historyOrders;
        window.pendingOrdersData = pendingOrders;
        window.shippedOrdersData = shippedOrders;
        window.uncollectedOrdersData = uncollectedOrders;

        // Suspended orders
        window.suspendedOrdersData = (rawSuspended || []).map(s => {
            let parsed = {};
            try {
                parsed = typeof s.draft_json === 'string' ? JSON.parse(s.draft_json) : (s.draft_json || {});
            } catch(e) {
                console.warn('Error parsing draft_json:', e);
            }
            return { ...parsed, _supabaseId: s.id, draftId: s.draft_id, id: s.draft_id };
        });
        updateSuspendedCount();

        // Customers
        let custStats = {};
        (rawOrders || []).forEach(o => {
            let p = String(o.phone).trim();
            if(!p) return;
            if(!custStats[p]) custStats[p] = { count: 0, total: 0, lastDate: '' };
            if (o.status !== 'ملغي' && o.status !== 'مرتجع') {
                custStats[p].count += 1;
                custStats[p].total += parseFloat(o.final_total) || 0;
            }
            if (o.order_date && (!custStats[p].lastDate || o.order_date > custStats[p].lastDate)) {
                custStats[p].lastDate = o.order_date;
            }
        });

        let existingCustPhones = new Set();
        window.customersData = (rawCustomers || []).map(c => {
            let p = String(c.phone).trim();
            existingCustPhones.add(p);
            let st = custStats[p] || { count: 0, total: 0, lastDate: '' };
            return {
                name: c.customer_name, phone: c.phone, gov: c.governorate,
                address: c.address, count: st.count || 0, total: st.total || 0, lastDate: st.lastDate || c.last_order_date
            };
        });

        // Add any customers from orders that are not in the customers table
        (rawOrders || []).forEach(o => {
            let p = String(o.phone).trim();
            if (p && !existingCustPhones.has(p)) {
                existingCustPhones.add(p);
                let st = custStats[p] || { count: 0, total: 0, lastDate: '' };
                window.customersData.push({
                    name: o.customer_name || 'بدون اسم', phone: p, gov: o.governorate || '',
                    address: o.address || '', count: st.count || 0, total: st.total || 0, lastDate: st.lastDate || o.order_date
                });
            }
        });

        window.usersData = (rawUsers || []).map(u => ({
            username: u.username, password: u.password, displayName: u.display_name,
            permissions: u.permissions, status: u.status, lastLogin: u.last_login
        }));
        if (typeof loadUsersList === 'function') loadUsersList();
        if (typeof window.loadReceiptsArchiveData === 'function') window.loadReceiptsArchiveData();

        // Expiries
        window.expiriesData = (rawExpiries || []).map(e => ({
            id: (e.product_name || '') + '|' + (e.qty || '') + '|' + (e.expiry_date || ''),
            dbId: e.id,
            name: e.product_name, qty: e.qty, expiryDate: e.expiry_date,
            location: e.location, registrarName: e.registrar_name,
            regDate: e.reg_date, receiver: e.receiver, notes: e.notes,
            originalPrice: e.original_price, offerPrice: e.offer_price,
            status: e.status, barcode: e.barcode
        }));
        if (typeof renderExpiryDashboard === 'function') {
            expiryData = Array.isArray(window.expiriesData) ? window.expiriesData : [];
            expiryData = expiryData.map(item => {
                if (item.regDate && typeof item.regDate === 'string' && item.regDate.includes("||")) {
                    let parts = item.regDate.split("||");
                    item.batchId = parts[1];
                    let d = new Date(parseInt(parts[1]));
                    if (!isNaN(d.getTime())) {
                        let hours = d.getHours(); let minutes = d.getMinutes();
                        let ampm = hours >= 12 ? 'PM' : 'AM';
                        hours = hours % 12; hours = hours ? hours : 12;
                        minutes = minutes < 10 ? '0' + minutes : minutes;
                        item.regDate = parts[0].trim() + " " + hours + ':' + minutes + ' ' + ampm;
                    } else { item.regDate = parts[0].trim(); }
                }
                return item;
            });
            renderExpiryDashboard();
        }

        // Catalog
        if (typeof syncAndMergeCatalogData === 'function') {
            syncAndMergeCatalogData(rawCatalog);
        } else if (typeof window.syncAndMergeCatalogData === 'function') {
            window.syncAndMergeCatalogData(rawCatalog);
        } else {
            catalogData = (rawCatalog || []).map(c => ({
                name: c.product_name, price: c.price, isOffer: c.is_offer || false,
                offerPrice: c.offer_price || 0, stock: c.stock || 0, barcode: c.barcode || ""
            }));
            renderCatalog();
        }

        // Out of stock
        oosData = (rawOOS || []).map(o => ({
            id: o.id, customer: o.customer_name, phone: o.phone, product: o.product, reason: o.reason || o.purpose, date: o.created_at || o.date, image_url: o.image_url || null
        }));
        renderOutOfStock(oosData);

        // Shipping zones
        const govSelect = document.getElementById('governorate');
        let currentGov = govSelect ? govSelect.value : "";
        const zonesAlexList = document.getElementById('zonesAlexList');
        const zonesGovList = document.getElementById('zonesGovList');
        if (zonesAlexList) zonesAlexList.innerHTML = '';
        if (zonesGovList) zonesGovList.innerHTML = '';
        if (govSelect) govSelect.innerHTML = '<option value="">اختر من القائمة</option>';
        shippingData = {};

        const renderZoneItem = (z, zoneType, container) => {
            shippingData[z.zone_name] = { name: z.zone_name, price: z.price, type: z.delivery_type, duration: z.duration };
            if (container) {
                let specialClass = z.delivery_type === 'next_day' ? 'zone-next-day' : '';
                container.innerHTML += `
                    <div class="zone-premium-card ${specialClass}">
                        <div class="zone-info-main">
                            <strong class="zone-title"><i class='fa-solid fa-location-dot'></i> ${z.zone_name}</strong>
                            <div class="zone-details-row">
                                <span class="price-badge premium-badge"><i class='fa-solid fa-money-bill-wave'></i> ${z.price} ج.م</span>
                                <span class="duration-badge"><i class='fa-regular fa-clock'></i> ${z.duration}</span>
                            </div>
                        </div>
                        <div class="zone-actions">
                            <button type="button" class="btn-outline interactive-btn" onclick="editZoneUI('${z.zone_name}', '${z.price}', '${z.delivery_type}', '${z.duration}')"><span class="btn-text-mobile-hide">تعديل</span> <i class='fa-solid fa-pencil'></i></button>
                            <button type="button" class="btn-danger interactive-btn" onclick="deleteItem('deleteZone', '${z.zone_name}')"><span class="btn-text-mobile-hide">حذف</span> <i class='fa-solid fa-xmark'></i></button>
                        </div>
                    </div>`;
            }
        };

        let alexZones = (rawShipping || []).filter(z => z.zone_type === 'alex');
        let govZones = (rawShipping || []).filter(z => z.zone_type === 'govs');
        alexZones.forEach(z => renderZoneItem(z, 'alex', zonesAlexList));
        govZones.forEach(z => renderZoneItem(z, 'govs', zonesGovList));

        window.latestServerData = { alex: alexZones.map(z => ({name: z.zone_name, price: z.price, type: z.delivery_type, duration: z.duration})), govs: govZones.map(z => ({name: z.zone_name, price: z.price, type: z.delivery_type, duration: z.duration})) };
        window.allShippingZones = rawShipping || [];
        if (typeof window.renderZonesGrid === 'function') {
            window.renderZonesGrid();
        }
        window.updateGovernoratesDropdown();
        if (govSelect && currentGov) govSelect.value = currentGov;

        // Drivers
        window.driversList = (rawCouriers || []).map(c => ({ name: c.name, phone: c.phone }));
        const driverSelect = document.getElementById('driverNameSelect');
        const driversDisplayList = document.getElementById('driversDisplayList');
        const assignDriverSelect = document.getElementById('assignDriverSelect');
        const closeDriverSelect = document.getElementById('closeDriverSelect');
        const previousAssignDriver = assignDriverSelect?.value || '';
        const previousCloseDriver = closeDriverSelect?.value || '';
        if (driversDisplayList) driversDisplayList.innerHTML = '';
        if (driverSelect) driverSelect.innerHTML = '<option value="">اختر المندوب</option>';
        if (assignDriverSelect) assignDriverSelect.innerHTML = '<option value="">اختر المندوب</option>';
        if (closeDriverSelect) closeDriverSelect.innerHTML = '<option value="">اختر المندوب</option>';

        if (window.driversList.length > 0) {
            let driverSelectHtml = '<option value="">اختر المندوب</option>';
            let displayListHtml = '';
            window.driversList.forEach(c => {
                driverSelectHtml += `<option value="${c.name}">${c.name}</option>`;
                displayListHtml += `<div class="driver-card">
                    <div>
                        <strong class="driver-card-header"><i class='fa-solid fa-motorcycle'></i> ${c.name}</strong><br>
                        <span class="phone-badge" style="margin-top:5px;display:inline-block;"><i class='fa-solid fa-mobile-screen'></i> ${c.phone}</span>
                    </div>
                    <div class="driver-card-actions">
                        <button type="button" class="btn-outline interactive-btn" style="flex:1;padding:6px;font-size:0.8rem;border-radius:6px;" onclick="editDriverUI('${c.name}', '${c.phone}')">تعديل <i class='fa-solid fa-pencil'></i></button>
                        <button type="button" class="interactive-btn btn-delete" style="flex:1;padding:6px;font-size:0.8rem;border-radius:6px;" onclick="deleteItem('deleteDriver', '${c.name}')">حذف <i class='fa-solid fa-xmark'></i></button>
                    </div>
                </div>`;
            });
            if (driverSelect) driverSelect.innerHTML = driverSelectHtml;
            if (assignDriverSelect) assignDriverSelect.innerHTML = driverSelectHtml;
            if (closeDriverSelect) closeDriverSelect.innerHTML = driverSelectHtml;
            if (driversDisplayList) driversDisplayList.innerHTML = displayListHtml;
        }
        if (assignDriverSelect) assignDriverSelect.value = previousAssignDriver;
        if (closeDriverSelect) closeDriverSelect.value = previousCloseDriver;

        updateSmartSuggestionsFromFirebase();

        // Moderators
        const modSelect = document.getElementById('moderatorSelect');
        let currentMod = modSelect ? modSelect.value : "";
        const modsList = document.getElementById('moderatorsList');
        let allMods = (rawModerators || []).map(m => m.name);
        window.allModeratorsList = allMods;

        if (allMods.length > 0) {
            let modSelectHtml = '<option value="">اختر اسمك</option>';
            let modsListHtml = '';
            allMods.forEach(m => {
                modSelectHtml += `<option value="${m}">${m}</option>`;
                modsListHtml += `<div class="data-row mod-row-item">
                    <span class="mod-row-name"><i class='fa-solid fa-user'></i> ${m}</span>
                    <button type="button" class="interactive-btn btn-delete" style="padding:4px 8px;font-size:0.8rem;border-radius:8px;" onclick="deleteItem('deleteModerator', '${m}')"><i class='fa-solid fa-xmark'></i></button>
                </div>`;
            });
            if (modSelect) modSelect.innerHTML = modSelectHtml;
            if (modsList) modsList.innerHTML = modsListHtml;
        } else {
            if (modSelect) modSelect.innerHTML = '<option value="">اختر اسمك</option>';
            if (modsList) modsList.innerHTML = '<p class="empty-msg">لا يوجد كاشيرية مسجلين</p>';
        }
        if (modSelect && currentMod) modSelect.value = currentMod;

        // Compute monthly stats locally
        let monthSales = 0, monthOrderCount = 0, completedMonthCount = 0, returnedCount = 0;
        allOrders.forEach(o => {
            if (o.date && o.date.substring(0, 7) === currentMonth) {
                if (o.status !== "مرتجع") { monthOrderCount++; monthSales += parseFloat(o.total) || 0; }
                if (o.status === "تم التوصيل" || o.status === "تم التوصيل ومُحاسب") completedMonthCount++;
                if (o.status === "مرتجع") returnedCount++;
            }
        });

        let reportMonthFilter = document.getElementById('reportMonthFilter');
        if (!reportMonthFilter || !reportMonthFilter.value) {
            if (document.getElementById('monthSales')) document.getElementById('monthSales').innerText = monthSales;
            if (document.getElementById('monthCount')) document.getElementById('monthCount').innerText = monthOrderCount;
            if (document.getElementById('completedMonthCount')) document.getElementById('completedMonthCount').innerText = completedMonthCount;
            if (document.getElementById('returnedCount')) document.getElementById('returnedCount').innerText = returnedCount;
        }

        // Financials - compute from orders
        window.financialsData = [];
        let finMap = {};
        let driverStatsMap = {};
        allOrders.forEach(o => {
            if (!o.driver) return;
            if (!finMap[o.driver]) finMap[o.driver] = { 
                name: o.driver, 
                ordersCount: 0, 
                inTransit: 0, 
                cashOrdersCount: 0,
                cashCollected: 0, 
                instaOrdersCount: 0,
                instaTotal: 0,
                shippingFees: 0, 
                productsTotal: 0,
                netDue: 0, 
                statusText: "لا توجد مديونية" 
            };
            if (!driverStatsMap[o.driver]) driverStatsMap[o.driver] = { monthProfit: 0, monthOrderCount: 0, totalProfit: 0, totalCount: 0 };
            
            // Only orders that are delivered but NOT settled count towards pending cash collection
            if (o.status === "تم التوصيل") {
                finMap[o.driver].ordersCount++;
                let total = parseFloat(o.total) || 0;
                let shipping = parseFloat(o.shipping) || 0;
                let productCost = Math.max(0, total - shipping);
                let payStr = (o.paymentMethod || o.payment || '').toLowerCase();
                let isInsta = payStr.includes('إنستا') || payStr.includes('انستا') || payStr.includes('insta') || payStr.includes('محفظة') || payStr.includes('فودافون') || payStr.includes('فيزا');
                
                let explicitRem = (o.raw_remaining !== undefined && o.raw_remaining !== null && o.raw_remaining !== '') ? parseFloat(o.raw_remaining) : null;
                let rem = 0;
                
                // FORCE rem to 0 for InstaPay because the DB might have saved the full total automatically when left blank
                if (isInsta) {
                    rem = 0;
                } else {
                    rem = explicitRem !== null ? explicitRem : total;
                }

                finMap[o.driver].shippingFees += shipping;
                finMap[o.driver].productsTotal += productCost;

                if (isInsta) {
                    finMap[o.driver].instaOrdersCount++;
                    finMap[o.driver].instaTotal += total;
                    if (rem > 0) {
                        finMap[o.driver].cashCollected += rem;
                    }
                } else {
                    finMap[o.driver].cashOrdersCount++;
                    finMap[o.driver].cashCollected += rem;
                }
            }
            if (o.status === "في الشحن") finMap[o.driver].inTransit++;

            // Stats include all delivered orders (settled or not)
            // Settled orders are processed separately below to avoid double counting
            if (o.status === "تم التوصيل") {
                let orderProfit = parseFloat(o.shipping) || 0;
                driverStatsMap[o.driver].totalProfit += orderProfit;
                driverStatsMap[o.driver].totalCount++;
                
                if (o.date && o.date.substring(0, 7) === currentMonth) {
                    driverStatsMap[o.driver].monthProfit += orderProfit;
                    driverStatsMap[o.driver].monthOrderCount++;
                }
            }
        });
        
        // Add rawSettled stats
        if (rawSettled) {
            rawSettled.forEach(o => {
                let driver = o.driver_name;
                if (!driver) return;
                if (!driverStatsMap[driver]) driverStatsMap[driver] = { monthProfit: 0, monthOrderCount: 0, totalProfit: 0, totalCount: 0 };
                
                let orderProfit = parseFloat(o.shipping_cost) || 0;
                driverStatsMap[driver].totalProfit += orderProfit;
                driverStatsMap[driver].totalCount++;
                
                if (o.order_date && o.order_date.substring(0, 7) === currentMonth) {
                    driverStatsMap[driver].monthProfit += orderProfit;
                    driverStatsMap[driver].monthOrderCount++;
                }
            });
        }
        
        // Add legacy stats to restore missing driver names from before Supabase migration
        const legacyStats = {
            'محمود': { totalProfit: 2425, totalCount: 43, monthProfit_2026_08: 0, monthCount_2026_08: 0 },
            'عمرو النوبي': { totalProfit: 1625, totalCount: 23, monthProfit_2026_08: 40, monthCount_2026_08: 1 },
            'الحلواني': { totalProfit: 1130, totalCount: 18, monthProfit_2026_08: 0, monthCount_2026_08: 0 },
            'شركة الشحن (المحافظات)': { totalProfit: 1000, totalCount: 5, monthProfit_2026_08: 200, monthCount_2026_08: 1 },
            'رضا': { totalProfit: 5835, totalCount: 95, monthProfit_2026_08: 600, monthCount_2026_08: 9 }
        };
        
        Object.keys(legacyStats).forEach(driver => {
            if (!driverStatsMap[driver]) driverStatsMap[driver] = { monthProfit: 0, monthOrderCount: 0, totalProfit: 0, totalCount: 0 };
            driverStatsMap[driver].totalProfit += legacyStats[driver].totalProfit;
            driverStatsMap[driver].totalCount += legacyStats[driver].totalCount;
            if (currentMonth === '2026-08') {
                driverStatsMap[driver].monthProfit += legacyStats[driver].monthProfit_2026_08;
                driverStatsMap[driver].monthOrderCount += legacyStats[driver].monthCount_2026_08;
            }
        });

        Object.values(finMap).forEach(f => {
            f.netDue = Math.round((f.cashCollected - f.shippingFees) * 100) / 100;
            if (f.netDue > 0) {
                f.statusText = "مطلوب توريد من المندوب";
            } else if (f.netDue < 0) {
                f.statusText = "مستحق صرفه للمندوب";
            } else {
                f.statusText = "الحساب متصفي بالكامل";
            }
            window.financialsData.push(f);
        });
        
        window.latestServerData = { ...window.latestServerData, history: historyOrders, pendingOrders, shippedOrders, uncollectedOrders, financials: window.financialsData, driverStats: driverStatsMap };
        if (typeof renderFinancials === 'function') renderFinancials(window.financialsData);

        buildMonthFilterOptions();

        let shippedCont = document.getElementById('shippedOrdersContainer');
        if (shippedCont) shippedCont.innerHTML = '<p class="empty-msg">برجاء اختيار المندوب والضغط على "عرض العهدة"</p>';

        renderHistoryList(orderHistoryData);
        renderShippingRoom(orderHistoryData);
        updateAdvancedDashboard(orderHistoryData);
        checkBookingAlerts();
        if (typeof renderModeratorsDashboard === 'function') renderModeratorsDashboard();

        let overlay = document.getElementById('module-loading-overlay');
        if (overlay) overlay.style.display = 'none';
        if (syncStatus) { syncStatus.innerText = "متصل"; syncStatus.style.color = "#00C853"; }

        if (window.isFirstLoad === undefined) {
            window.isFirstLoad = false;
            window.lastFilterDate = currentFilterDate;
            if (currentUser) showToast(`أهلاً بك يا ${currentUser.displayName}`);
        } else {
            if (window.lastFilterDate === currentFilterDate) {
                let oldHistoryIds = (window._prevHistoryIds || []);
                let hasNewProcessing = historyOrders.some(o => !oldHistoryIds.includes(o.id) && o.status && o.status.includes("تجهيز"));
                if (hasNewProcessing) playOrderSound();
            }
            window.lastFilterDate = currentFilterDate;
        }
        window._prevHistoryIds = historyOrders.map(o => o.id);

        // Update local system version from server row if available, or current time
        const sysVerRow = (rawShipping || []).find(r => r.zone_name === '_SYSTEM_VERSION_' && r.zone_type === 'system');
        if (sysVerRow && sysVerRow.price) {
            window.lastKnownSystemVersion = parseFloat(sysVerRow.price) || Date.now();
        } else {
            window.lastKnownSystemVersion = Date.now();
        }
        localStorage.setItem('cc_last_system_activity', String(window.lastKnownSystemVersion));

        // ⭐ مزامنة بيانات الفرع ورابط الواتساب من جدول branch_settings الموحد
        if (typeof window.loadBranchLocation === 'function') {
            window.loadBranchLocation();
        }

        // ⭐ مزامنة وتحديث بوكيهات قسم الهدايا تلقائياً مع السيرفر إن كان الموديول مفتوحاً
        if (window.GiftsApp && typeof window.GiftsApp.loadBouquets === 'function') {
            window.GiftsApp.loadBouquets().then(() => {
                if (typeof window.GiftsApp.updateHeaderStats === 'function') window.GiftsApp.updateHeaderStats();
                if (typeof window.GiftsApp.renderShowcase === 'function') window.GiftsApp.renderShowcase();
                if (typeof window.GiftsApp.renderCatalogView === 'function') window.GiftsApp.renderCatalogView();
            }).catch(e => console.warn("Gifts refresh during loadDataFromServer error:", e));
        }

        // 🚨 فحص حالة شحن وتوصيل أوردرات المودريتور وتطبيق القفل والتحذيرات
        if (typeof window.fetchModeratorSlaConfig === 'function') {
            await window.fetchModeratorSlaConfig();
        }
        if (typeof window.checkModeratorShippingStatus === 'function') {
            window.checkModeratorShippingStatus();
        }
        if (typeof window.loadModeratorSlaAdmin === 'function' && document.getElementById('adminSlaCard')) {
            window.loadModeratorSlaAdmin();
        }

    } catch (err) {
        console.error("Supabase Load Error:", err);
        let overlay = document.getElementById('module-loading-overlay');
        if (overlay) overlay.style.display = 'none';
        if (syncStatus) { syncStatus.innerText = "خطأ اتصال"; syncStatus.style.color = "red"; }
    }
}

// ==========================================
// 🚨 نظام إجبار الشحن والتوصيل الصارم (SLA Enforcement System)
// ==========================================

// 1. جلب إعدادات الرقابة المخزنة في Supabase (افتراضياً معطل OFF)
window.fetchModeratorSlaConfig = async function(force = false) {
    if (!window.supabase) return window.moderatorSlaConfig;
    try {
        const { data, error } = await window.supabase
            .from('settings_shipping')
            .select('*')
            .eq('zone_name', '_MODERATOR_SLA_CONFIG_')
            .eq('zone_type', 'system')
            .limit(1);

        if (!error && data && data.length > 0) {
            const row = data[0];
            window.moderatorSlaConfig = {
                enabled: row.delivery_type === 'enabled',
                maxHours: parseFloat(row.price) || 24,
                lastUpdated: row.duration || ''
            };
        } else {
            window.moderatorSlaConfig = {
                enabled: false,
                maxHours: 24,
                lastUpdated: ''
            };
        }
    } catch (e) {
        console.warn('[SLA] Error fetching SLA config:', e);
        if (!window.moderatorSlaConfig) {
            window.moderatorSlaConfig = { enabled: false, maxHours: 24, lastUpdated: '' };
        }
    }
    return window.moderatorSlaConfig;
};

// 2. مزامنة عناصر واجهة المدير الإدارية
window.syncSlaAdminUI = function() {
    const card = document.getElementById('adminSlaCard');
    const badge = document.getElementById('adminSlaStatusBadge');
    const statusText = document.getElementById('adminSlaStatusText');
    const toggle = document.getElementById('adminSlaToggle');
    const toggleLabel = document.getElementById('adminSlaToggleLabel');
    const hoursInp = document.getElementById('adminSlaHoursInput');
    const lastUpdateEl = document.getElementById('adminSlaLastUpdate');

    const cfg = window.moderatorSlaConfig || { enabled: false, maxHours: 24, lastUpdated: '' };

    if (toggle) toggle.checked = !!cfg.enabled;
    if (hoursInp) hoursInp.value = cfg.maxHours || 24;
    if (lastUpdateEl && cfg.lastUpdated) {
        lastUpdateEl.innerText = `آخر تحديث: ${cfg.lastUpdated}`;
    }

    if (cfg.enabled) {
        if (card) { card.classList.remove('is-disabled'); card.classList.add('is-active'); }
        if (badge) { badge.className = 'sla-status-pill active'; }
        if (statusText) statusText.innerText = 'مفعل وشغال لحظياً (ON)';
        if (toggleLabel) {
            toggleLabel.innerText = 'مفعل (يتم قفل الشاشة عند التأخير)';
            toggleLabel.style.color = '#059669';
        }
    } else {
        if (card) { card.classList.remove('is-active'); card.classList.add('is-disabled'); }
        if (badge) { badge.className = 'sla-status-pill disabled'; }
        if (statusText) statusText.innerText = 'معطل حالياً (OFF)';
        if (toggleLabel) {
            toggleLabel.innerText = 'معطل (لن يقفل على أي مودريتور)';
            toggleLabel.style.color = '#64748b';
        }
    }
};

// 3. التغيير الفوري للمظهر عند لمس المفتاح قبل الحفظ
window.handleSlaToggleChange = function(checked) {
    const toggleLabel = document.getElementById('adminSlaToggleLabel');
    const card = document.getElementById('adminSlaCard');
    const badge = document.getElementById('adminSlaStatusBadge');
    const statusText = document.getElementById('adminSlaStatusText');

    if (checked) {
        if (card) { card.classList.remove('is-disabled'); card.classList.add('is-active'); }
        if (badge) { badge.className = 'sla-status-pill active'; }
        if (statusText) statusText.innerText = 'بانتظار الحفظ لتطبيقه...';
        if (toggleLabel) {
            toggleLabel.innerText = 'مفعل (اضغط حفظ للتطبيق فوراً)';
            toggleLabel.style.color = '#059669';
        }
    } else {
        if (card) { card.classList.remove('is-active'); card.classList.add('is-disabled'); }
        if (badge) { badge.className = 'sla-status-pill disabled'; }
        if (statusText) statusText.innerText = 'بانتظار الحفظ لإلغائه...';
        if (toggleLabel) {
            toggleLabel.innerText = 'معطل (اضغط حفظ للإلغاء فوراً)';
            toggleLabel.style.color = '#64748b';
        }
    }
};

// 4. حفظ الإعدادات في Supabase والبث اللحظي للجميع
window.saveModeratorSlaAdmin = async function() {
    const toggle = document.getElementById('adminSlaToggle');
    const hoursInp = document.getElementById('adminSlaHoursInput');
    const saveBtn = document.getElementById('adminSlaSaveBtn');

    const isEnabled = toggle ? toggle.checked : false;
    const maxHours = hoursInp ? Math.max(1, parseFloat(hoursInp.value) || 24) : 24;

    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ والتطبيق...';
    }

    try {
        const nowStr = new Date().toLocaleString('ar-EG');
        const payload = {
            enabled: isEnabled,
            maxHours: maxHours,
            lastUpdated: nowStr
        };

        // أ) الحفظ في سوبا بيز في جدول settings_shipping الموحد
        const { data: existing, error: chkErr } = await window.supabase
            .from('settings_shipping')
            .select('id')
            .eq('zone_name', '_MODERATOR_SLA_CONFIG_')
            .eq('zone_type', 'system')
            .limit(1);

        if (!chkErr && existing && existing.length > 0) {
            await window.supabase
                .from('settings_shipping')
                .update({
                    price: maxHours,
                    delivery_type: isEnabled ? 'enabled' : 'disabled',
                    duration: nowStr
                })
                .eq('id', existing[0].id);
        } else {
            await window.supabase
                .from('settings_shipping')
                .insert([{
                    zone_name: '_MODERATOR_SLA_CONFIG_',
                    zone_type: 'system',
                    price: maxHours,
                    delivery_type: isEnabled ? 'enabled' : 'disabled',
                    duration: nowStr
                }]);
        }

        // ب) إرسال بث فوري (Realtime Broadcast) لجميع المتصفحات المفتوحة حالياً
        if (window.candySystemRealtimeChannel) {
            try {
                await window.candySystemRealtimeChannel.send({
                    type: 'broadcast',
                    event: 'sla_config_updated',
                    payload: payload
                });
            } catch (bcErr) {
                console.warn('[Realtime] Broadcast send error:', bcErr);
            }
        }

        // ج) تحديث الإعداد المحلي فوراً
        window.moderatorSlaConfig = payload;

        // د) رفع نشاط النظام لإجبار المزامنة الذكية على التحديث
        if (typeof window.bumpSystemActivity === 'function') {
            window.bumpSystemActivity();
        }

        // هـ) تحديث الواجهة ورسالة تأكيد
        window.syncSlaAdminUI();
        if (typeof showToast === 'function') {
            showToast(isEnabled 
                ? `✅ تم تفعيل الرقابة بمهلة (${maxHours} ساعة) وتطبيقها لحظياً على الجميع دون خروج!` 
                : "✅ تم إلغاء تفعيل الرقابة وفتح أجهزة المودريتور لحظياً فوراً!", "success");
        }

        // و) إعادة فحص وتدقيق الأوردرات المتأخرة في الكارت
        window.loadModeratorSlaAdmin(false);

    } catch (err) {
        console.error('[SLA] Save error:', err);
        if (typeof showToast === 'function') showToast("فشل حفظ إعدادات الرقابة، تحقق من الاتصال", "error");
    } finally {
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = '<i class="fa-solid fa-bolt"></i> حفظ وتطبيق فورياً على الجميع';
        }
    }
};

// 5. تحميل الإعدادات وتدقيق الأوردرات المتأخرة لعرضها في الداشبورد
window.loadModeratorSlaAdmin = async function(force = false) {
    await window.fetchModeratorSlaConfig(force);
    window.syncSlaAdminUI();

    const auditCountEl = document.getElementById('adminSlaAuditCount');
    const auditListEl = document.getElementById('adminSlaAuditList');
    if (!auditCountEl || !auditListEl) return;

    const allOrders = window.allOrdersData || [];
    const now = Date.now();
    const maxHours = (window.moderatorSlaConfig && window.moderatorSlaConfig.maxHours) ? window.moderatorSlaConfig.maxHours : 24;

    const overdueList = [];
    allOrders.forEach(o => {
        if (o.status !== 'قيد التجهيز' && o.status !== 'في الشحن') return;
        
        let orderTime = 0;
        if (o.createdAt) orderTime = new Date(o.createdAt).getTime();
        else if (o.date) orderTime = new Date(`${o.date} ${o.time || '12:00:00'}`).getTime();
        if (!orderTime || isNaN(orderTime)) return;

        const hoursElapsed = (now - orderTime) / (1000 * 60 * 60);
        let limit = (o.status === 'قيد التجهيز') ? maxHours : 240;

        if (hoursElapsed >= limit) {
            overdueList.push({
                order: o,
                hoursElapsed: Math.round(hoursElapsed),
                moderator: o.moderator || o.seller || 'غير محدد',
                status: o.status
            });
        }
    });

    if (overdueList.length === 0) {
        auditCountEl.className = 'sla-audit-count zero';
        auditCountEl.innerText = '0 أوردر متأخر (كل شيء سليم)';
        auditListEl.innerHTML = '<div style="text-align: center; color: #059669; padding: 15px; font-weight: 700;"><i class="fa-solid fa-circle-check" style="font-size: 1.5rem; display: block; margin-bottom: 6px;"></i> ممتاز! لا توجد أي أوردرات متأخرة عن الشحن في النظام حالياً.</div>';
    } else {
        auditCountEl.className = 'sla-audit-count';
        auditCountEl.innerText = `${overdueList.length} أوردر متأخر`;
        let html = '';
        overdueList.forEach(item => {
            html += `
                <div style="display: flex; justify-content: space-between; align-items: center; padding: 9px 12px; border-bottom: 1px solid #f1f5f9; font-size: 0.88rem;">
                    <div>
                        <strong style="color: #0f172a;">#${item.order.id}</strong> - 
                        <span>${item.order.name || 'بدون اسم'}</span>
                        <span style="color: #64748b; margin-right: 8px;">(المودريتور: <strong style="color: #2563eb;">${item.moderator}</strong>)</span>
                    </div>
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <span style="background: #f1f5f9; color: #475569; padding: 2px 8px; border-radius: 6px; font-size: 0.78rem;">${item.status}</span>
                        <span style="background: #fee2e2; color: #dc2626; padding: 2px 8px; border-radius: 6px; font-weight: 800; font-size: 0.78rem;">مر عليه ${item.hoursElapsed} ساعة</span>
                    </div>
                </div>
            `;
        });
        auditListEl.innerHTML = html;
    }
};

window.toggleSlaAuditDetails = function() {
    const details = document.getElementById('adminSlaAuditDetails');
    const chevron = document.getElementById('adminSlaAuditChevron');
    if (!details) return;
    const isHidden = details.style.display === 'none';
    details.style.display = isHidden ? 'block' : 'none';
    if (chevron) {
        chevron.innerHTML = isHidden ? '<i class="fa-solid fa-chevron-up"></i>' : '<i class="fa-solid fa-chevron-down"></i>';
    }
};

window.navigateToShippingTab = function() {
    const shipBtn = document.querySelector('button.nav-item[data-target="shipping-tab"]');
    if (shipBtn) {
        shipBtn.click();
    } else {
        document.querySelectorAll('.tab-pane').forEach(tp => tp.classList.remove('active'));
        const shipTab = document.getElementById('shipping-tab');
        if (shipTab) shipTab.classList.add('active');
        document.querySelectorAll('.nav-item').forEach(b => {
            if (b.getAttribute('data-target') === 'shipping-tab') b.classList.add('active');
            else b.classList.remove('active');
        });
    }
};

window.renderModeratorLockout = function(overdueOrders) {
    const lockoutCard = document.getElementById('moderatorLockoutCard');
    const warningBanner = document.getElementById('moderatorWarningBanner');
    const orderFields = document.getElementById('orderFieldsContainer');
    const currentName = (window.currentUser && (window.currentUser.displayName || window.currentUser.username)) || 'المودريتور';

    if (warningBanner) warningBanner.style.display = 'none';
    if (!lockoutCard) return;

    let ordersHtml = '';
    overdueOrders.forEach(item => {
        const o = item.order;
        const delayBadge = item.stage === 1
            ? `<span class="overdue-order-badge"><i class="fa-solid fa-clock"></i> متأخر عن الشحن (${item.delayHours > 0 ? item.delayHours + ' س إضافية' : Math.round(item.elapsedHours) + ' ساعة'})</span>`
            : `<span class="overdue-order-badge"><i class="fa-solid fa-truck"></i> في الشحن متأخر (${item.delayText})</span>`;

        ordersHtml += `
            <div class="overdue-order-row">
                <div class="overdue-order-meta">
                    <span class="overdue-order-id">#${o.id}</span>
                    <span class="overdue-order-name">${o.name || 'بدون اسم'} (${o.phone || 'بدون هاتف'})</span>
                    <span class="overdue-order-dest"><i class="fa-solid fa-location-dot" style="color:#ef4444; margin-left:3px;"></i>${o.gov || ''} ${o.address ? '- ' + o.address : ''}</span>
                    <span style="font-size:0.78rem; color:#64748b; font-weight:700;"><i class="fa-solid fa-tag" style="margin-left:3px;"></i>${item.categoryName || (item.stage === 1 ? 'قيد التجهيز' : 'في الشحن')}</span>
                </div>
                <div>
                    ${delayBadge}
                </div>
            </div>
        `;
    });

    lockoutCard.innerHTML = `
        <div class="lockout-card-header">
            <div class="lockout-shield-icon">
                <i class="fa-solid fa-shield-halved"></i>
            </div>
            <div class="lockout-header-info">
                <h3><i class="fa-solid fa-lock" style="margin-left:6px;"></i> خانة إنشاء الطلبات موقوفة مؤقتاً لحسابك (${currentName})</h3>
                <p>لديك <strong>${overdueOrders.length} أوردر(ات) معلقة</strong> تجاوزت المهلة المسموح بها للشحن أو التوصيل. المنظومة تشترط شحن الأوردرات أو إغلاقها في قسم الشحن أولاً لتتمكن من إنشاء طلبات جديدة.</p>
            </div>
        </div>

        <div class="overdue-orders-container">
            ${ordersHtml}
        </div>

        <div class="lockout-actions-row">
            <button type="button" class="btn-resolve-shipping interactive-btn" onclick="window.navigateToShippingTab()">
                <i class="fa-solid fa-truck-fast"></i> الانتقال لقسم الشحن لإسناد / إغلاق الأوردرات فوراً
            </button>
        </div>
    `;

    lockoutCard.style.display = 'block';

    // Disable order creation fields & lock submit
    if (orderFields) {
        orderFields.style.opacity = '0.35';
        orderFields.style.pointerEvents = 'none';
        orderFields.style.filter = 'grayscale(60%)';
    }

    const saveBtn = document.getElementById('saveAndPrintBtn');
    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.style.opacity = '0.4';
        saveBtn.style.cursor = 'not-allowed';
        saveBtn.title = 'موقوف لوجود أوردرات متأخرة';
    }
};

window.clearModeratorShippingLock = function() {
    const lockoutCard = document.getElementById('moderatorLockoutCard');
    const orderFields = document.getElementById('orderFieldsContainer');
    const saveBtn = document.getElementById('saveAndPrintBtn');

    if (lockoutCard) {
        lockoutCard.style.display = 'none';
        lockoutCard.innerHTML = '';
    }

    if (orderFields) {
        orderFields.style.opacity = '1';
        orderFields.style.pointerEvents = 'auto';
        orderFields.style.filter = 'none';
    }

    if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.style.opacity = '1';
        saveBtn.style.cursor = 'pointer';
        saveBtn.title = '';
    }
};

window.renderModeratorWarning = function(warningOrders) {
    const warningBanner = document.getElementById('moderatorWarningBanner');
    if (!warningBanner) return;

    let minMinutes = 60;
    let closestOrder = null;
    warningOrders.forEach(w => {
        if (w.remainingMinutes < minMinutes) {
            minMinutes = w.remainingMinutes;
            closestOrder = w.order;
        }
    });

    warningBanner.innerHTML = `
        <div class="warning-banner-content">
            <div class="warning-banner-icon">
                <i class="fa-solid fa-hourglass-half"></i>
            </div>
            <div class="warning-banner-text">
                <h4>تنبيه: اقتراب انتهاء مهلة الشحن</h4>
                <p>لديك أوردر برقم <strong>#${closestOrder ? closestOrder.id : ''}</strong> للعميل (<strong>${closestOrder ? closestOrder.name : ''}</strong>) متبقي له <strong>${minMinutes} دقيقة</strong> قبل قفل خانة إنشاء الطلبات.</p>
            </div>
        </div>
        <div style="display:flex; align-items:center; gap:10px;">
            <span class="warning-banner-badge"><i class="fa-solid fa-clock"></i> متبقي ${minMinutes} دقيقة</span>
            <button type="button" class="interactive-btn" onclick="window.navigateToShippingTab()" style="background:#f59e0b; color:#fff; border:none; padding:7px 14px; border-radius:10px; font-weight:800; cursor:pointer; font-family:inherit; font-size:0.85rem;">
                شحن الآن <i class="fa-solid fa-arrow-left"></i>
            </button>
        </div>
    `;
    warningBanner.style.display = 'flex';
};

window.clearModeratorWarning = function() {
    const warningBanner = document.getElementById('moderatorWarningBanner');
    if (warningBanner) {
        warningBanner.style.display = 'none';
        warningBanner.innerHTML = '';
    }
};

window.checkModeratorShippingStatus = function() {
    // 0. صمام الأمان: إن كانت الميزة معطلة من لوحة المدير، فك القفل تماماً فوراً
    if (!window.moderatorSlaConfig || !window.moderatorSlaConfig.enabled) {
        window.clearModeratorShippingLock();
        window.clearModeratorWarning();
        return { locked: false, overdueOrders: [], warningOrders: [] };
    }

    // 1. المدير العام بصلاحية ALL لا يتم قفل الشاشة له أبداً
    if (!window.currentUser || window.currentUser.permissions === 'ALL') {
        window.clearModeratorShippingLock();
        window.clearModeratorWarning();
        return { locked: false, overdueOrders: [], warningOrders: [] };
    }

    const currentModName = (window.currentUser.displayName || window.currentUser.username || '').trim().toLowerCase();
    if (!currentModName) {
        window.clearModeratorShippingLock();
        window.clearModeratorWarning();
        return { locked: false, overdueOrders: [], warningOrders: [] };
    }

    const allOrders = window.allOrdersData || [];
    const now = Date.now();
    const todayStr = (function() {
        const d = new Date();
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    })();

    const overdueOrders = [];
    const warningOrders = [];

    // مهلة السماح المحددة من لوحة المدير بالساعات (الافتراضي 24 ساعة)
    const stage1Limit = (window.moderatorSlaConfig && window.moderatorSlaConfig.maxHours) ? parseFloat(window.moderatorSlaConfig.maxHours) : 24;
    const stage1WarningLimit = Math.max(0.5, stage1Limit - 2.0);

    // فحص أوردرات هذا المودريتور
    allOrders.forEach(o => {
        const orderMod = (o.moderator || o.seller || '').trim().toLowerCase();
        if (orderMod !== currentModName) return;

        // حساب وقت إنشاء الطلب
        let orderTime = 0;
        if (o.createdAt) {
            orderTime = new Date(o.createdAt).getTime();
        } else if (o.date) {
            orderTime = new Date(`${o.date} ${o.time || '12:00:00'}`).getTime();
        }
        if (!orderTime || isNaN(orderTime)) return;

        const hoursElapsed = (now - orderTime) / (1000 * 60 * 60);

        // STAGE 1: قيد التجهيز (لم يتم شحنها للمندوب بعد)
        if (o.status === 'قيد التجهيز') {
            const isFutureDate = (o.orderType === 'special_date' || (o.orderType && o.orderType.includes('حجز')) || (o.deliveryDate && o.deliveryDate > todayStr));
            if (isFutureDate && o.deliveryDate > todayStr) {
                return;
            }

            if (hoursElapsed >= stage1Limit) {
                overdueOrders.push({
                    order: o,
                    stage: 1,
                    type: 'لم يتم شحنه للمندوب',
                    limitHours: stage1Limit,
                    elapsedHours: hoursElapsed,
                    delayHours: Math.round(hoursElapsed - stage1Limit),
                    badgeText: `متأخر عن الشحن ${Math.round(hoursElapsed)} ساعة`
                });
            } else if (hoursElapsed >= stage1WarningLimit) {
                const remMinutes = Math.max(1, Math.round((stage1Limit - hoursElapsed) * 60));
                warningOrders.push({
                    order: o,
                    stage: 1,
                    remainingMinutes: remMinutes,
                    badgeText: `متبقي ${remMinutes} دقيقة للشحن`
                });
            }
        }

        // STAGE 2: في الشحن (خرجت مع المندوب ولم تُسجل كـ تم التوصيل)
        else if (o.status === 'في الشحن') {
            let maxHours = 6;
            let categoryName = 'إسكندرية (نفس اليوم - حد أقصى 6 ساعات)';

            const oType = (o.orderType || '').toLowerCase();
            const gov = (o.gov || '').trim();

            if (oType === 'gov_shipping' || oType.includes('محافظات') || (gov && gov !== 'الإسكندرية' && !gov.includes('اسكندر'))) {
                maxHours = 240; // 10 days
                categoryName = 'شحن محافظات (حد أقصى 10 أيام)';
            } else if (oType === 'special_date' || oType.includes('حجز') || (o.deliveryDate && o.deliveryDate !== o.date)) {
                maxHours = 72; // 3 days
                categoryName = 'إسكندرية ثاني يوم/حجز (حد أقصى 3 أيام)';
            } else {
                maxHours = 6; // 6 hours
                categoryName = 'إسكندرية نفس اليوم (حد أقصى 6 ساعات)';
            }

            if (hoursElapsed >= maxHours) {
                const delayHrs = Math.round(hoursElapsed - maxHours);
                const delayText = delayHrs > 24 ? `${Math.round(delayHrs / 24)} يوم` : `${delayHrs} ساعة`;
                overdueOrders.push({
                    order: o,
                    stage: 2,
                    type: 'في الشحن مع المندوب ولم يتم إغلاقه',
                    limitHours: maxHours,
                    elapsedHours: hoursElapsed,
                    categoryName: categoryName,
                    delayText: delayText,
                    badgeText: `مع المندوب (${o.driver || 'غير محدد'}) متأخر ${delayText}`
                });
            }
        }
    });

    if (overdueOrders.length > 0) {
        window.renderModeratorLockout(overdueOrders);
        return { locked: true, overdueOrders, warningOrders };
    } else {
        window.clearModeratorShippingLock();
        if (warningOrders.length > 0) {
            window.renderModeratorWarning(warningOrders);
        } else {
            window.clearModeratorWarning();
        }
        return { locked: false, overdueOrders: [], warningOrders };
    }
};

// Periodic background check every 60 seconds
setInterval(() => {
    if (typeof window.checkModeratorShippingStatus === 'function') {
        const createTab = document.getElementById('create-tab');
        if (createTab && createTab.classList.contains('active')) {
            window.checkModeratorShippingStatus();
        }
    }
}, 60000);

function checkBookingAlerts() {
    let banner = document.getElementById('booking-alert-banner');
    if (!banner) return;
    
    let today = new Date();
    today.setHours(0, 0, 0, 0);

    let hasAlert = window.pendingOrdersData.some(o => {
        if (!o.orderType || !o.orderType.includes('حجز')) return false;
        
        let resDateStr = o.reservationDate || o.expectedDate || o.specialDate || o.spDate;
        if (!resDateStr) return false;
        
        let resDate = new Date(resDateStr);
        if (isNaN(resDate.getTime())) return false;
        
        resDate.setHours(0, 0, 0, 0);
        let diffTime = resDate - today;
        let diffDays = diffTime / (1000 * 60 * 60 * 24);
        
        return diffDays >= 0 && diffDays <= 2;
    });

    if (hasAlert) banner.style.display = 'block';
    else banner.style.display = 'none';
}

const courierAccountsView = { selectedName: '', query: '', payment: 'cash' };

function getActiveCourierOrderCheckboxes(checkedOnly = false) {
    const card = document.querySelector('#financialsDisplayList .courier-account-detail:not([hidden])');
    return card ? Array.from(card.querySelectorAll('.financial-order-checkbox' + (checkedOnly ? ':checked' : ''))) : [];
}

function syncCourierSelectionControls() {
    const checkboxes = getActiveCourierOrderCheckboxes();
    const checked = checkboxes.filter(cb => cb.checked).length;
    const selectAll = document.getElementById('selectAllFinancialsCheckbox');
    if (selectAll) {
        selectAll.disabled = checkboxes.length === 0;
        selectAll.checked = checkboxes.length > 0 && checked === checkboxes.length;
        selectAll.indeterminate = checked > 0 && checked < checkboxes.length;
    }
    const label = document.getElementById('courierSelectionLabel');
    if (label) label.textContent = courierAccountsView.selectedName
        ? `تحديد كل أوردرات ${courierAccountsView.selectedName}` : 'تحديد كل أوردرات المندوب';
    const counter = document.getElementById('courierSelectedCount');
    if (counter) counter.textContent = checked ? `${checked} أوردر محدد` : '';
    const button = document.getElementById('closeSelectedFinancialsBtn');
    if (button && !button.disabled) {
        button.style.display = checked > 0 ? 'inline-block' : 'none';
        button.textContent = `تقفيل المحدد (${checked})`;
    }
}

function prepareCourierAccountsWorkspace(container) {
    const cards = Array.from(container.children).filter(card => card.classList.contains('financial-row'));
    const toolbar = document.getElementById('courierSelectionToolbar');
    if (toolbar) toolbar.hidden = cards.length === 0;
    if (!cards.length) { syncCourierSelectionControls(); return; }
    const workspace = document.createElement('div');
    workspace.className = 'courier-accounts-workspace';
    const sidebar = document.createElement('aside');
    sidebar.className = 'courier-accounts-sidebar';
    sidebar.innerHTML = `<details class="courier-list-panel">
        <summary class="courier-list-summary"><span class="courier-current-name"></span><span class="courier-list-summary-hint">تغيير المندوب</span></summary>
        <div class="courier-list-content"><input type="search" class="courier-account-search" aria-label="ابحث باسم المندوب" placeholder="ابحث باسم المندوب..." autocomplete="off">
        <div class="courier-accounts-list" aria-label="حسابات المناديب"></div><p class="courier-accounts-empty" hidden>لا يوجد مندوب مطابق للبحث.</p></div>
    </details>`;
    const listPanel = sidebar.querySelector('details');
    const isCompact = () => window.matchMedia && window.matchMedia('(max-width: 760px)').matches;
    listPanel.open = !isCompact();
    const search = sidebar.querySelector('input');
    const list = sidebar.querySelector('.courier-accounts-list');
    const empty = sidebar.querySelector('.courier-accounts-empty');
    const detail = document.createElement('div');
    detail.className = 'courier-accounts-detail';
    const entries = cards.map((card, index) => ({ card, name: card.dataset.courierName || '', pending: Number(card.dataset.courierOrders) || 0, index }));
    entries.sort((a, b) => b.pending - a.pending || a.name.localeCompare(b.name, 'ar'));
    let activeEntry = entries.find(entry => entry.name === courierAccountsView.selectedName) || entries[0];
    courierAccountsView.selectedName = activeEntry.name;

    const selectCourier = entry => {
        if (document.getElementById('closeSelectedFinancialsBtn')?.disabled) return;
        container.querySelectorAll('.financial-order-checkbox').forEach(cb => { cb.checked = false; });
        activeEntry = entry;
        courierAccountsView.selectedName = entry.name;
        entries.forEach(item => {
            item.card.hidden = item !== entry;
            item.button.setAttribute('aria-pressed', String(item === entry));
        });
        sidebar.querySelector('.courier-current-name').textContent = `${entry.name} · ${entry.pending} أوردر`;
        if (isCompact()) {
            listPanel.open = false;
            sidebar.querySelector('summary').focus?.();
        }
        syncCourierSelectionControls();
    };

    entries.forEach(entry => {
        const card = entry.card;
        card.classList.add('courier-account-detail');
        card.id = 'courier-account-detail-' + entry.index;
        card.hidden = entry !== activeEntry;
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'courier-account-choice';
        button.setAttribute('aria-controls', card.id);
        button.setAttribute('aria-pressed', String(entry === activeEntry));
        const title = document.createElement('span');
        title.className = 'courier-account-choice-title';
        const name = document.createElement('span');
        name.textContent = entry.name;
        const count = document.createElement('span');
        count.className = 'courier-account-choice-count';
        count.textContent = `${entry.pending} أوردر`;
        title.append(name, count);
        const status = document.createElement('span');
        status.className = 'courier-account-choice-status';
        status.textContent = card.querySelector('.financial-status')?.textContent.trim().replace(/\s+/g, ' ') || '';
        button.append(title, status);
        button.addEventListener('click', () => selectCourier(entry));
        entry.button = button;
        list.appendChild(button);

        const performance = card.lastElementChild;
        const groups = Array.from(card.children).filter(child => child.querySelector('.financial-order-item'));
        if (groups.length) {
            const tabs = document.createElement('div');
            tabs.className = 'courier-payment-tabs';
            tabs.setAttribute('role', 'tablist');
            tabs.setAttribute('aria-label', 'نوع دفع أوردرات المندوب');
            const panels = groups.map((group, groupIndex) => {
                const type = group.querySelector('.financial-payment-badge--instapay') ? 'instapay' : 'cash';
                const tab = document.createElement('button');
                tab.type = 'button';
                tab.className = 'courier-payment-tab';
                tab.id = `courier-payment-${entry.index}-${groupIndex}`;
                tab.setAttribute('role', 'tab');
                group.id = tab.id + '-panel';
                group.classList.add('courier-payment-panel');
                group.setAttribute('role', 'tabpanel');
                group.setAttribute('aria-labelledby', tab.id);
                tab.setAttribute('aria-controls', group.id);
                const count = group.querySelectorAll('.financial-order-checkbox').length;
                tab.textContent = `${type === 'cash' ? 'كاش' : 'إنستاباي / إلكتروني'} (${count})`;
                tabs.appendChild(tab);
                const scrollList = group.lastElementChild;
                if (scrollList) {
                    scrollList.tabIndex = 0;
                    scrollList.setAttribute('aria-label', `أوردرات ${type === 'cash' ? 'الكاش' : 'الدفع الإلكتروني'} — يمكن تمرير القائمة`);
                }
                return { group, tab, type };
            });
            const activate = (panel, remember = true) => {
                panels.forEach(item => {
                    item.group.hidden = item !== panel;
                    item.tab.setAttribute('aria-selected', String(item === panel));
                    item.tab.tabIndex = item === panel ? 0 : -1;
                });
                if (remember) courierAccountsView.payment = panel.type;
            };
            panels.forEach((panel, index) => {
                panel.tab.addEventListener('click', () => activate(panel));
                panel.tab.addEventListener('keydown', event => {
                    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
                    event.preventDefault();
                    const next = panels[(index + (event.key === 'ArrowLeft' ? 1 : -1) + panels.length) % panels.length];
                    activate(next);
                    next.tab.focus();
                });
            });
            card.insertBefore(tabs, groups[0]);
            activate(panels.find(panel => panel.type === courierAccountsView.payment) || panels[0], false);
        }
        if (performance && !groups.includes(performance)) {
            const disclosure = document.createElement('details');
            disclosure.className = 'courier-performance';
            const summary = document.createElement('summary');
            summary.textContent = 'أداء المندوب وإحصائياته';
            disclosure.append(summary, performance);
            card.appendChild(disclosure);
        }
        detail.appendChild(card);
    });
    const filter = () => {
        const query = normalizeArabicText(search.value);
        courierAccountsView.query = search.value;
        let visible = 0;
        entries.forEach(entry => {
            entry.button.hidden = !normalizeArabicText(entry.name).includes(query);
            if (!entry.button.hidden) visible++;
        });
        empty.hidden = visible > 0;
    };
    search.value = courierAccountsView.query;
    search.addEventListener('input', filter);
    filter();
    sidebar.querySelector('.courier-current-name').textContent = `${activeEntry.name} · ${activeEntry.pending} أوردر`;
    workspace.append(sidebar, detail);
    container.replaceChildren(workspace);
    syncCourierSelectionControls();
}

function renderFinancials(finList) {
    let container = document.getElementById('financialsDisplayList');
    if (!container) return;
    container.innerHTML = '';

    let allDrivers = window.driversList || [];
    let driversMap = {};
    allDrivers.forEach(d => {
        driversMap[d.name] = { name: d.name, ordersCount: 0, cashCollected: 0, shippingFees: 0, netDue: 0, statusText: "لا توجد مديونية" };
    });

    finList.forEach(f => {
        if (!driversMap[f.name]) {
            driversMap[f.name] = f;
        } else {
            driversMap[f.name] = { ...driversMap[f.name], ...f };
        }
    });

    let driversArray = Object.values(driversMap);
    if (driversArray.length === 0) {
        container.innerHTML = '<p class="empty-msg">لا توجد مناديب مسجلة.</p>';
        return;
    }

    driversArray.forEach(f => {
        let netDue = parseFloat(f.netDue) || 0;

        let todayCount = 0;
        let todayProfit = 0;
        if(window.latestServerData && window.latestServerData.todayDriverStats && window.latestServerData.todayDriverStats[f.name]) {
            todayCount = window.latestServerData.todayDriverStats[f.name].count || 0;
            todayProfit = window.latestServerData.todayDriverStats[f.name].profit || 0;
        }

        let isSettled = netDue === 0;
        let statusColor = netDue > 0 ? "#27ae60" : (netDue < 0 ? "#c0392b" : "#9e9e9e");
        let cardClass = isSettled ? "financial-row driver-card settled" : "financial-row driver-card";
        let cardShadow = isSettled ? "none" : "0 4px 6px rgba(0,0,0,0.05)";
        let cardOpacity = isSettled ? "0.8" : "1";
        let cardBorderColor = isSettled ? "#e0e0e0" : "#eaeaea";

        let driverOrders = (window.uncollectedOrdersData || []).filter(o => o.driver === f.name);
        let ordersHtml = '';
        if (driverOrders.length > 0) {
            ordersHtml = `<div style="margin-top: 10px; border-top: 1px dashed #ccc; padding-top: 10px;">
                <strong style="font-size:0.85rem; color:var(--primary);"><i class=\'fa-solid fa-box\'></i> أوردرات معلقة (لم يتم تسويتها):</strong>`;
            driverOrders.forEach(o => {
                ordersHtml += `
                    <div class="financial-order-item" style="background:#fdfdfd; padding:8px; border:1px solid #eee; border-radius:6px; margin-top:5px; display:flex; justify-content:space-between; align-items:center;">
                            <span style="font-size:0.75rem; color:#777;">${o.payment} | إجمالي: ${o.total}ج | شحن: ${o.shipping}ج</span><br>
                            <span style="font-size:0.85rem; font-weight:bold; color:var(--danger);">المطلوب تحصيله: ${o.remaining}ج</span>
                        </div>
                        <button class="btn-settle interactive-btn" onclick="settleDriverOrder('${o.id}', this, '${o.payment}')" style="background:var(--success); color:white; border:none; padding:6px 12px; border-radius:6px; cursor:pointer;">تسوية <i class=\'fa-solid fa-money-bill\'></i></button>
                    </div>
                `;
            });
            ordersHtml += `</div>`;
        }

        container.innerHTML += `
            <div class="${cardClass}" style="background: #fff; padding: 15px; border-radius: 12px; border: 1px solid ${cardBorderColor}; margin-bottom: 12px; box-shadow: ${cardShadow}; opacity: ${cardOpacity}; transition: all 0.3s ease;">
                <div class="financial-header" style="display:flex; justify-content:space-between; align-items:center; border-bottom: 1px solid #f0f0f0; padding-bottom:8px; margin-bottom:10px;">
                    <span style="font-weight:bold; font-size:1.1rem; color:var(--text-dark);"><i class=\'fa-solid fa-motorcycle\'></i> ${f.name}</span>
                    <span style="font-size: 0.85rem; background:#f0f0f0; color:var(--text-dark); padding:3px 8px; border-radius:12px; font-weight:bold;">${f.ordersCount || 0} طلب</span>
                </div>
                <div class="financial-details" style="display:flex; justify-content:space-between; font-size:0.9rem; margin-bottom:10px;">
                    <span style="background:#e8f4f8; padding:5px 10px; border-radius:6px; color:#555;">الكاش: <strong style="color:#2980b9;">${f.cashCollected || 0}</strong> ج</span>
                    <span style="background:#f9ebea; padding:5px 10px; border-radius:6px; color:#555;">الشحن: <strong style="color:#c0392b;">${f.shippingFees || 0}</strong> ج</span>
                </div>
                <div class="financial-status" style="background: ${statusColor}15; color: ${statusColor}; padding: 8px; border-radius: 6px; text-align:center; font-weight:bold; border: 1px dashed ${statusColor};">
                    ${f.statusText || "لا توجد مديونية"} ${netDue !== 0 ? `( ${Math.abs(netDue)} ج.م )` : ''}
                </div>

                <!-- أوردرات وأرباح اليوم -->
                <div style="background:#e8f5e9; padding:8px; border-radius:6px; border-right:4px solid var(--success); margin-bottom:10px; display:flex; justify-content:space-between; align-items:center; font-size:0.9rem;">
                    <div><strong style="color:var(--success);"><i class="fa-solid fa-calendar-day"></i> أوردرات اليوم:</strong> <span>${todayCount} أوردر</span></div>
                    <div><strong style="color:var(--success);">أرباح اليوم:</strong> <span>${todayProfit} ج.م</span></div>
                </div>
                ${ordersHtml}
            </div>
        `;
    });
}

// <i class=\'fa-solid fa-star\'></i> حماية تصفية الأوردر برسالة واضحة بناءً على نوع الدفع
window.settleDriverOrder = function (orderId, btn, payMethod) {
    let isInsta = (payMethod || '').includes('إنستا') || (payMethod || '').includes('انستا') || (payMethod || '').includes('insta') || (payMethod || '').includes('محفظة');
    let msg = `هل أنت متأكد من تسوية الأوردر (${orderId})؟`;
    if (isInsta) {
        msg = `هل قمت بصرف مستحقات الشحن للمندوب عن أوردر الإنستاباي (${orderId})؟`;
    } else {
        msg = `هل استلمت النقدية من المندوب الخاصة بالأوردر (${orderId})؟`;
    }

    customConfirm(msg, () => {
        btn.innerText = "جاري...";
        btn.disabled = true;

        let formData = new URLSearchParams();
        formData.append('action', 'settleOrder');
        formData.append('orderId', orderId);

        fetch(GOOGLE_SHEETS_URL, { method: 'POST', mode: 'no-cors', body: formData })
            .then(() => {
                showToast("<i class=\'fa-solid fa-check\'></i> تمت المحاسبة وتسوية الأوردر بنجاح!", "success");
                loadDataFromServer();
            }).catch(() => {
                showToast("<i class=\'fa-solid fa-xmark\'></i> حدث خطأ في الاتصال", "error");
                btn.innerHTML = "تسوية <i class=\'fa-solid fa-money-bill\'></i>";
                btn.disabled = false;
            });
    });
};

// ==========================================
// 4. حساب أجازة الجمعة والعربون <i class=\'fa-solid fa-rocket\'></i>
// ==========================================
function calculateDeliveryDateSkippingFriday(durationText) {
    if (!durationText) return "";
    let match = durationText.match(/\d+/);
    if (!match) return durationText;

    let daysToAdd = parseInt(match[0]);
    let d = new Date();
    let added = 0;

    while (added < daysToAdd) {
        d.setDate(d.getDate() + 1);
        if (d.getDay() !== 5) {
            added++;
        }
    }

    let options = { weekday: 'long', month: 'numeric', day: 'numeric' };
    return d.toLocaleDateString('ar-EG', options);
}

const deliveryTypeSelect = document.getElementById('deliveryType');
const govSelect = document.getElementById('governorate');
if (deliveryTypeSelect) {
    deliveryTypeSelect.addEventListener('change', () => {
        let type = deliveryTypeSelect.value;
        let addressFields = document.getElementById('addressFields');
        let specialDateContainer = document.getElementById('specialDateContainer');
        if (type === 'branch') {
            if (addressFields) addressFields.classList.add('hidden-field');
            if (specialDateContainer) specialDateContainer.classList.add('hidden-field');
            if (document.getElementById('shippingCost')) document.getElementById('shippingCost').value = 0;
            let infoSpan = document.querySelector('#deliveryInfo span'); if (infoSpan) infoSpan.innerHTML = "استلام من الفرع <i class=\'fa-solid fa-store\'></i>";
        } else if (type === 'gov_shipping') {
            if (addressFields) addressFields.classList.remove('hidden-field');
            if (specialDateContainer) specialDateContainer.classList.add('hidden-field');
            triggerGovCalc();
        } else if (type === 'special_date') {
            if (addressFields) addressFields.classList.remove('hidden-field');
            if (specialDateContainer) specialDateContainer.classList.remove('hidden-field');
            triggerGovCalc();
        } else {
            if (addressFields) addressFields.classList.remove('hidden-field');
            if (specialDateContainer) specialDateContainer.classList.add('hidden-field');
            triggerGovCalc();
        }
        window.updateGovernoratesDropdown();
        calculateTotal();
    });
}

window.updateGovernoratesDropdown = function () {
    const govSelect = document.getElementById('governorate');
    if (!govSelect || !window.latestServerData) return;
    let data = window.latestServerData;
    let type = document.getElementById('deliveryType') ? document.getElementById('deliveryType').value : 'normal';

    let currentVal = govSelect.value;
    let html = '<option value="">اختر من القائمة</option>';

    if (type === 'gov_shipping') {
        if (data.govs && data.govs.length > 0) {
            html += `<optgroup label="&#xf48b; المحافظات" style="font-family: 'Font Awesome 6 Free', 'Cairo', sans-serif; font-weight: 900;">`;
            data.govs.forEach(z => {
                html += `<option value="${z.name}">${z.name} (${z.price} ج)</option>`;
            });
            html += `</optgroup>`;
        }
    } else {
        if (data.alex && data.alex.length > 0) {
            html += `<optgroup label="&#xf0c1; مناطق الإسكندرية" style="font-family: 'Font Awesome 6 Free', 'Cairo', sans-serif; font-weight: 900;">`;
            data.alex.forEach(z => {
                html += `<option value="${z.name}">${z.name} (${z.price} ج)</option>`;
            });
            html += `</optgroup>`;
        }
    }
    
    govSelect.innerHTML = html;

    if (Array.from(govSelect.options).some(opt => opt.value === currentVal)) {
        govSelect.value = currentVal;
    }
};

function triggerGovCalc() {
    if (!govSelect) return;
    let zone = govSelect.value;
    let costInput = document.getElementById('shippingCost');
    let dateDisplay = document.querySelector('#deliveryInfo span');

    if (!zone || !shippingData[zone]) {
        if (costInput) costInput.value = 0;
        if (dateDisplay) dateDisplay.innerText = "--";
        calculateTotal(); return;
    }
    let info = shippingData[zone];
    if (costInput) costInput.value = info.price || 0;

    if (dateDisplay) {
        let type = deliveryTypeSelect ? deliveryTypeSelect.value : 'normal';
        if (type === 'special_date') {
            dateDisplay.innerHTML = "حسب التاريخ المختار <i class=\'fa-regular fa-calendar-days\'></i>";
        } else if (info.type === 'next_day') {
            dateDisplay.innerHTML = "تاني يوم <i class=\'fa-solid fa-truck-fast\'></i>";
        } else {
            let exactDate = calculateDeliveryDateSkippingFriday(info.duration);
            dateDisplay.innerText = exactDate ? `المتوقع: ${exactDate}` : `خلال ${info.duration}`;
        }
    }
    calculateTotal();
}
if (govSelect) govSelect.addEventListener('change', triggerGovCalc);



// ==========================================
// 5. سجل الأوردرات (العرض الذكي والطباعة)
// ==========================================
let currentHistoryPage = 1;
const ITEMS_PER_PAGE = 20;
let currentOrdersList = [];
window.searchResultsCache = []; // <i class=\'fa-solid fa-star\'></i> لتخزين البحث دون مسح السجل

function renderHistoryList(orders, isLoadMore = false) {
    let container = document.getElementById('historyListContainer');
    if (!container) return;

    if (!isLoadMore) {
        container.innerHTML = '';
        currentHistoryPage = 1;
        
        let countSpan = document.getElementById('historyDayCount');
        let searchInput = document.getElementById('orderSearchInput');
        if (countSpan) {
            if (searchInput && searchInput.value.trim() === "") {
                countSpan.innerText = `عدد أوردرات اليوم: ${orders.length}`;
                countSpan.style.display = 'inline-block';
            } else {
                countSpan.style.display = 'none';
            }
        }
        currentOrdersList = orders;

        if (window.pendingOrdersData && window.pendingOrdersData.length > 0 && document.getElementById('orderSearchInput').value.trim() === "") {
            let pendingDiv = document.createElement('div');
            pendingDiv.innerHTML = `<h4 style="color: #e74c3c; padding-bottom: 5px; margin-bottom: 15px; font-weight: bold;"><i class=\'fa-solid fa-circle text-danger\'></i> أوردرات لم تُشحن بعد (${window.pendingOrdersData.length})</h4>`;

            window.pendingOrdersData.forEach(pOrder => {
                let pType = pOrder.orderType || pOrder.type || pOrder.deliveryType || "";
                let dateHtml = `<span style="color: #e74c3c; font-weight: bold; font-size:0.85rem;"><i class=\'fa-regular fa-calendar-days\'></i> ${pOrder.date}</span>`;
                if (pType.includes('حجز') || pType === 'special_date') {
                    let resDate = pOrder.reservationDate || pOrder.expectedDate || pOrder.specialDate || pOrder.spDate;
                    if (resDate) {
                        if (resDate.toString().includes('GMT') || resDate.toString().includes('توقيت')) {
                            let d = new Date(resDate);
                            if (!isNaN(d.getTime())) resDate = `${d.getFullYear()}-${("0" + (d.getMonth() + 1)).slice(-2)}-${("0" + d.getDate()).slice(-2)}`;
                        }
                        dateHtml = `<span style="color: #fff; background: #c2185b; padding: 4px 8px; border-radius: 6px; font-weight: bold; font-size:0.9rem;"><i class=\'fa-regular fa-calendar\'></i> تسليم: ${resDate}</span>`;
                    }
                }
                pendingDiv.innerHTML += `
                    <div class="history-item" style="border-right-color: #e74c3c; background: #fff5f5;">
                        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px;">
                            <strong style="font-size: 1.05rem;">${pOrder.id} | ${pOrder.name}</strong>
                            ${dateHtml}
                        </div>
                        <div style="font-size: 0.9rem; color: #555;">
                            <span><i class=\'fa-solid fa-mobile-screen\'></i> ${pOrder.phone} | <span style="color:#000; font-weight:bold;"><i class=\'fa-solid fa-money-bill-wave\'></i> ${pOrder.total} ج.م</span></span>
                        </div>
                    </div>
                `;
            });
            container.appendChild(pendingDiv);

            let hr = document.createElement('hr');
            hr.style.margin = "20px 0";
            hr.style.borderColor = "var(--border)";
            container.appendChild(hr);
        }

        if (currentOrdersList.length === 0) {
            container.innerHTML += `<p class="empty-msg">لا توجد أوردرات في هذا التاريخ.</p>`;
            return;
        }
    }

    let startIndex = (currentHistoryPage - 1) * ITEMS_PER_PAGE;
    let endIndex = startIndex + ITEMS_PER_PAGE;
    let pageOrders = currentOrdersList.slice(startIndex, endIndex);

    pageOrders.forEach(order => {
        let div = document.createElement('div');
        let statusClass = 'status-other';
        if (order.status === "تم التوصيل ومُحاسب") statusClass = 'status-settled';
        else if (order.status === "تم التوصيل") statusClass = 'status-delivered';
        else if (order.status === "قيد التجهيز") statusClass = 'status-pending';
        else if (order.status === "في الشحن") statusClass = 'status-shipped';
        else if (order.status === "مرتجع") statusClass = 'status-returned';
        
        div.className = `history-item ${statusClass}`;

        let statusColor = (order.status === "تم التوصيل" || order.status === "تم التوصيل ومُحاسب") ? "var(--success)" : "var(--primary)";
        if (order.status === "مرتجع") statusColor = "var(--danger)";

        div.style.borderRightColor = statusColor;

        let typeBadge = '';
        let oType = order.orderType || order.type || order.deliveryType || "";
        if (oType.includes('توصيل منزلي') || oType === 'normal') {
            typeBadge = `<span style="background: #e3f2fd; color: #1565c0; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; margin-right: 5px;"><i class=\'fa-solid fa-truck-fast\'></i> توصيل منزلي</span>`;
        } else if (oType.includes('استلام من الفرع') || oType === 'branch') {
            typeBadge = `<span style="background: #e8f5e9; color: #2e7d32; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; margin-right: 5px;"><i class=\'fa-solid fa-store\'></i> استلام من الفرع</span>`;
        } else if (oType.includes('محافظات') || oType === 'gov_shipping') {
            typeBadge = `<span style="background: #fff3e0; color: #e65100; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; margin-right: 5px;"><i class=\'fa-solid fa-box\'></i> شحن محافظات</span>`;
        } else if (oType.includes('حجز') || oType === 'special_date') {
            let resDate = order.reservationDate || order.expectedDate || order.bookingDate || order.specialDate || order.spDate || order.date;
            if (resDate && (resDate.toString().includes('GMT') || resDate.toString().includes('توقيت'))) {
                let d = new Date(resDate);
                if (!isNaN(d.getTime())) resDate = `${d.getFullYear()}-${("0" + (d.getMonth() + 1)).slice(-2)}-${("0" + d.getDate()).slice(-2)}`;
            }
            let dateText = resDate ? `تسليم: ${resDate}` : 'حجز مسبق';
            typeBadge = `<span style="background: #c2185b; color: #fff; padding: 3px 8px; border-radius: 6px; font-size: 0.85rem; margin-right: 5px; font-weight: bold;"><i class=\'fa-regular fa-calendar\'></i> ${dateText}</span>`;
        }
        
        let payStr = (order.paymentMethod || order.payment || '').toLowerCase();
        let isInsta = payStr.includes('إنستا') || payStr.includes('انستا') || payStr.includes('insta') || payStr.includes('محفظة') || payStr.includes('فودافون') || payStr.includes('فيزا');
        let paymentBadge = isInsta 
            ? `<span style="background: #f3e8ff; color: #7e22ce; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; margin-right: 5px; border: 1px solid #d8b4fe; display: inline-flex; align-items: center; gap: 4px;"><i class=\'fa-solid fa-mobile-screen-button\'></i> إنستاباي</span>`
            : `<span style="background: #ecfdf5; color: #047857; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; margin-right: 5px; border: 1px solid #a7f3d0; display: inline-flex; align-items: center; gap: 4px;"><i class=\'fa-solid fa-money-bill-wave\'></i> كاش</span>`;
        typeBadge += paymentBadge;

        let timeStr = order.time || '--';
        try {
            if (order.time && order.time !== '--') {
                let parts = order.time.split(':');
                if (parts.length >= 2) {
                    let hour = parseInt(parts[0]);
                    let min = parts[1];
                    let ampm = hour >= 12 ? 'مساءً' : 'صباحاً';
                    hour = hour % 12;
                    if (hour === 0) hour = 12;
                    timeStr = `${hour}:${min} ${ampm}`;
                }
            }
        } catch(e) {}

        div.innerHTML = `
            <div class="history-item-header">
                <div class="history-item-identity">
                    <strong style="font-size: 0.98rem; color: var(--text-dark); word-break: break-word;">${order.id} | ${order.name}</strong>
                    <div style="display: inline-flex; flex-wrap: wrap; gap: 4px; align-items: center;">
                        ${typeBadge}
                    </div>
                </div>
                <div class="history-item-actions-cluster">
                    ${(order.status === 'قيد التجهيز') ? `
                    <button type="button" class="order-action-icon-btn edit-action-btn" onclick="startOrderEdit('${order.id}')" title="تعديل الأوردر وإعادته لصفحة الإنشاء" aria-label="تعديل الأوردر">
                        <i class="fa-solid fa-pen-to-square"></i>
                    </button>
                    ` : ''}
                    <button type="button" class="order-action-icon-btn whatsapp-action-btn" onclick="shareToWhatsAppGroup('${order.id}')" title="نسخ ومشاركة لجروب الواتساب" aria-label="مشاركة واتساب">
                        <i class="fa-brands fa-whatsapp"></i>
                    </button>
                    <button type="button" class="order-action-icon-btn print-action-btn" onclick="printHistoryOrder('${order.id}')" title="طباعة الفاتورة" aria-label="طباعة الفاتورة">
                        <i class="fa-solid fa-print"></i>
                    </button>
                    <span class="order-status-pill" style="background: ${statusColor}18; color: ${statusColor}; border: 1px solid ${statusColor}40;">${order.status}</span>
                </div>
            </div>
            <div class="history-item-subbar">
                <span>⏰ ${timeStr}</span>
                <span><i class=\'fa-solid fa-mobile-screen\'></i> ${order.phone}${((order.phone2 || order.secondPhone || order.backupPhone || order.altPhone || order.customerPhone2 || order.otherPhone) && String(order.phone2 || order.secondPhone || order.backupPhone || order.altPhone || order.customerPhone2 || order.otherPhone).trim() !== '') ? ' | <i class=\'fa-solid fa-mobile-screen\'></i> ' + String(order.phone2 || order.secondPhone || order.backupPhone || order.altPhone || order.customerPhone2 || order.otherPhone).trim() : ''}</span>
                <span style="font-weight:bold; color: var(--text-dark);"><i class=\'fa-solid fa-money-bill-wave\'></i> ${order.total} ج.م</span>
            </div>
        `;
        div.onclick = (e) => {
            if (e.target.closest('.order-action-icon-btn')) return;
            showOrderDetailsModal(order.id);
        };
        container.appendChild(div);
    });

    let oldBtn = document.getElementById('loadMoreHistoryBtn');
    if (oldBtn) oldBtn.remove();

    if (endIndex < currentOrdersList.length) {
        let btn = document.createElement('button');
        btn.id = 'loadMoreHistoryBtn';
        btn.innerText = '⬇️ عرض المزيد (محلي)';
        btn.className = 'interactive-btn btn-outline';
        btn.style.width = '100%';
        btn.style.marginTop = '15px';
        btn.onclick = () => {
            currentHistoryPage++;
            renderHistoryList(currentOrdersList, true);
        };
        container.appendChild(btn);
    } else if (currentOrdersList.length >= 50 && (currentOrdersList.length % 50 === 0)) {
        // Server-side Load More Button
        let serverBtn = document.createElement('button');
        serverBtn.id = 'loadMoreFromServerBtn';
        serverBtn.innerText = '☁️ جلب المزيد من السيرفر';
        serverBtn.className = 'interactive-btn btn-search';
        serverBtn.style.width = '100%';
        serverBtn.style.marginTop = '15px';
        serverBtn.onclick = () => {
            serverBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الجلب...';
            serverBtn.disabled = true;
            let currentOffset = currentOrdersList.length;
            
            if (currentOrdersList === window.searchResultsCache) {
                let keyword = document.getElementById('orderSearchInput').value.trim().toLowerCase();
                let searchKeyword = `%${keyword}%`;
                supabase.from('orders').select('*')
                    .or(`order_id.ilike.${searchKeyword},customer_name.ilike.${searchKeyword},phone.ilike.${searchKeyword}`)
                    .range(currentOffset, currentOffset + 49)
                    .then(({data, error}) => appendServerData(data, error));
            } else {
                supabase.from('orders').select('*')
                    .eq('order_date', window.lastFilterDate || currentFilterDate)
                    .order('created_at', { ascending: false })
                    .range(currentOffset, currentOffset + 49)
                    .then(({data, error}) => appendServerData(data, error));
            }
            
            function appendServerData(data, error) {
                if (error || !data || data.length === 0) {
                    serverBtn.innerText = '✅ لا توجد فواتير أخرى';
                    return;
                }
                let mappedData = data.map(window.mapOrderRowToLocal);
                // Append to global lists based on context
                if (currentOrdersList === window.searchResultsCache) {
                    window.searchResultsCache = window.searchResultsCache.concat(mappedData);
                    currentOrdersList = window.searchResultsCache;
                } else {
                    window.orderHistoryData = window.orderHistoryData.concat(mappedData);
                    currentOrdersList = window.orderHistoryData;
                }
                // Refresh local pagination
                currentHistoryPage++;
                renderHistoryList(currentOrdersList, true);
            }
        };
        container.appendChild(serverBtn);
    }
}

// دالة تنظيف الملاحظات للفواتير المطبوعة لمنع طباعة وسوم HTML أو نصوص الهدايا التلقائية
window.cleanNotesForReceipt = function(notesStr) {
    if (!notesStr) return "";
    let clean = String(notesStr)
        // إزالة أي وسوم HTML مثل <i class='...'></i>
        .replace(/<[^>]*>?/gm, '')
        // إزالة وسوم وألفاظ الهدايا التلقائية بجميع أشكالها
        .replace(/\[\s*أوردر\s*هدية\s*\]/gi, '')
        .replace(/\[\s*هدية\s*\]/gi, '')
        .replace(/أوردر\s*هدية\s*[-–—:]?/gi, '')
        .replace(/هدية\s*[-–—:]?/gi, '')
        // تنظيف الشُرط والفواصل والمسافات الزائدة من الأطراف
        .replace(/^[\s\-–—:،,.]+/g, '')
        .replace(/[\s\-–—:،,.]+$/g, '')
        .trim();

    let checkContent = clean.replace(/[\s\-_.:،,]/g, '');
    if (!checkContent || clean === "لا توجد ملاحظات" || clean === "بدون ملاحظات") {
        return "";
    }
    return clean;
};

window.printHistoryOrder = function (orderId) {
    // <i class=\'fa-solid fa-star\'></i> Fix: String() comparison to prevent type mismatch (string vs number)
    let findFn = o => String(o.id) === String(orderId);
    let order = (window.orderHistoryData || []).find(findFn) ||
        (window.searchResultsCache || []).find(findFn) ||
        (window.pendingOrdersData || []).find(findFn) ||
        (window.suspendedOrdersData || []).find(findFn) ||
        (window.uncollectedOrdersData || []).find(findFn);

    if (!order) {
        customAlert("<i class='fa-solid fa-triangle-exclamation' style='color:var(--danger)'></i> خطأ: لم يتم العثور على بيانات الطلب للطباعة.");
        // <i class=\'fa-solid fa-star\'></i> Debug: log all available IDs to help trace mismatch
        console.warn("printHistoryOrder: could not find orderId =", orderId, typeof orderId);
        console.log("Available history IDs:", (window.orderHistoryData || []).map(o => ({ id: o.id, type: typeof o.id })));
        return;
    }
    console.log("Order Data:", order);

    let isOldGift = order.notes && order.notes.includes("هدية");
    let oTypeStr = String(order.orderType || "").toLowerCase();
    let dTypeStr = String(order.deliveryType || "").toLowerCase();
    let isBranch = oTypeStr.includes('استلام') || oTypeStr.includes('فرع') || oTypeStr === 'branch' || dTypeStr.includes('استلام') || dTypeStr.includes('فرع') || dTypeStr === 'branch';

    let printLogo = document.getElementById('print-logo');
    if (printLogo) {
        let pay = order.payment || "";
        let isGovShipping = oTypeStr === 'gov_shipping' || oTypeStr.includes('محافظات') || dTypeStr === 'gov_shipping';
        let isDigitalPay = isGovShipping || pay.includes('إنستا') || pay.includes('انستاباي') || pay.includes('انستا باي') || pay.includes('محفظة') || pay.includes('فودافون') || pay.includes('تحويل');
        if (isBranch) {
            printLogo.src = 'images/logo-branch.png';
        } else if (isDigitalPay) {
            printLogo.src = 'images/logo-digital.png';
        } else {
            printLogo.src = 'images/logo-cash.png';
        }
        printLogo.style.display = 'block';
    }

    if (document.getElementById('receipt-type')) {
        // <i class=\'fa-solid fa-star\'></i> V15.0: تطبيع النص - إزالة "عادي" من "توصيل منزلي عادي"
        let typeStr = (order.orderType || "أوردر توصيل").replace("توصيل منزلي عادي", "توصيل منزلي");
        let govStr = order.gov ? order.gov + " - " : "";
        let orderIdText = order.id ? `<br><span style="font-size:14px; font-weight:normal; font-family: Tahoma, sans-serif;">رقم الأوردر: ${order.id}</span>` : "";
        document.getElementById('receipt-type').innerHTML = isOldGift ? `${govStr}${typeStr} - <i class=\'fa-solid fa-gift\'></i> هدية${orderIdText}` : `${govStr}${typeStr}${orderIdText}`;
    }
    if (document.getElementById('print-date')) document.getElementById('print-date').innerText = order.date || new Date().toLocaleDateString('ar-EG');
    if (document.getElementById('print-time')) document.getElementById('print-time').innerText = order.time || '';

    let printItemsHtml = "";
    let productsArray = [];
    if (order.products) {
        if (typeof order.products === 'string') {
            productsArray = order.products.split('\n');
        } else if (Array.isArray(order.products)) {
            productsArray = order.products;
        }
    } else if (order.items) {
        if (typeof order.items === 'string') {
            try {
                let parsed = JSON.parse(order.items);
                if (Array.isArray(parsed)) productsArray = parsed;
                else productsArray = order.items.split('\n');
            } catch(e) {
                productsArray = order.items.split('\n');
            }
        } else if (Array.isArray(order.items)) {
            productsArray = order.items;
        }
    }

    productsArray.forEach(lineOrItem => {
        if (typeof lineOrItem === 'string' && lineOrItem.trim() !== "") {
            let match = lineOrItem.match(/(.*?) - الكمية: (\d+) \(([\d.]+)ج\)(?: \[([\d.]+)\])?/);
            if (match) {
                let name = match[1].trim();
                let qty = match[2];
                let total = match[3];
                let savedOriginalPrice = match[4] ? parseFloat(match[4]) : null;
                let price = parseFloat(total) / parseFloat(qty);
                
                let originalPrice = price;
                if (savedOriginalPrice && savedOriginalPrice > price) {
                    originalPrice = savedOriginalPrice;
                } else {
                    let safeName = String(name).trim().toLowerCase().replace(/\s+/g, '');
                    let catalogItem = null;
                    if (typeof catalogData !== 'undefined' && Array.isArray(catalogData)) {
                        catalogItem = catalogData.find(prod => String(prod.name).trim().toLowerCase().replace(/\s+/g, '') === safeName);
                    }
                    if (!catalogItem && typeof barcodeCatalogData !== 'undefined' && Array.isArray(barcodeCatalogData)) {
                        catalogItem = barcodeCatalogData.find(prod => String(prod.name).trim().toLowerCase().replace(/\s+/g, '') === safeName);
                    }
                    if (catalogItem && parseFloat(catalogItem.price) > price) {
                        originalPrice = parseFloat(catalogItem.price);
                    }
                }
                
                let printP = isOldGift ? "***" : price;
                if (!isOldGift && originalPrice > price) {
                    printP = `<del style="color:#7f8c8d; font-size:10px;">${originalPrice}</del><br>${price}`;
                }
                printItemsHtml += `
                    <tr>
                        <td>${name}</td>
                        <td>${printP}</td>
                        <td>${qty}</td>
                        <td>${isOldGift ? "***" : total}</td>
                    </tr>
                `;
            } else {
                printItemsHtml += `<tr><td colspan="4" style="text-align:right;">${lineOrItem}</td></tr>`;
            }
        } else if (typeof lineOrItem === 'object' && lineOrItem !== null) {
            let name = lineOrItem.name || lineOrItem.item_name || "منتج";
            let qty = lineOrItem.qty || lineOrItem.quantity || 1;
            let total = lineOrItem.total || lineOrItem.price || 0;
            let savedOriginalPrice = lineOrItem.originalPrice || null;
            let price = parseFloat(total) / parseFloat(qty);
            
            let originalPrice = price;
            if (savedOriginalPrice && savedOriginalPrice > price) {
                originalPrice = savedOriginalPrice;
            } else {
                let safeName = String(name).trim().toLowerCase().replace(/\s+/g, '');
                let catalogItem = null;
                if (typeof catalogData !== 'undefined' && Array.isArray(catalogData)) {
                    catalogItem = catalogData.find(prod => String(prod.name).trim().toLowerCase().replace(/\s+/g, '') === safeName);
                }
                if (!catalogItem && typeof barcodeCatalogData !== 'undefined' && Array.isArray(barcodeCatalogData)) {
                    catalogItem = barcodeCatalogData.find(prod => String(prod.name).trim().toLowerCase().replace(/\s+/g, '') === safeName);
                }
                if (catalogItem && parseFloat(catalogItem.price) > price) {
                    originalPrice = parseFloat(catalogItem.price);
                }
            }

            let printP = isOldGift ? "***" : price;
            if (!isOldGift && originalPrice > price) {
                printP = `<del style="color:#7f8c8d; font-size:10px;">${originalPrice}</del><br>${price}`;
            }
            printItemsHtml += `
                <tr>
                    <td>${name}</td>
                    <td>${printP}</td>
                    <td>${qty}</td>
                    <td>${isOldGift ? "***" : total}</td>
                </tr>
            `;
        }
    });

    let printBookingRow = document.querySelector('.print-booking-row');
    if (oTypeStr.includes('حجز') || oTypeStr === 'special_date') {
        let rDate = order.reservationDate || order.expectedDate || order.specialDate || order.spDate;
        if (rDate) {
            if (printBookingRow) printBookingRow.style.display = 'block';
            if (rDate.toString().includes('GMT') || rDate.toString().includes('توقيت')) {
                let d = new Date(rDate);
                if (!isNaN(d.getTime())) rDate = `${d.getFullYear()}-${("0" + (d.getMonth() + 1)).slice(-2)}-${("0" + d.getDate()).slice(-2)}`;
            }
            if (document.getElementById('print-booking-date')) document.getElementById('print-booking-date').innerText = rDate;
        } else {
            if (printBookingRow) printBookingRow.style.display = 'none';
        }
    } else {
        if (printBookingRow) printBookingRow.style.display = 'none';
    }
    if (document.getElementById('print-customer-name')) document.getElementById('print-customer-name').innerText = order.name || '';
    if (document.getElementById('print-phone')) document.getElementById('print-phone').innerText = order.phone || '';

    let _phone2Val = order.phone2 || order.secondPhone || order.backupPhone || order.altPhone || order.customerPhone2 || order.otherPhone || "";
    let printPhone2Row = document.getElementById('print-phone2-row');
    if (printPhone2Row) {
        if (_phone2Val && String(_phone2Val).trim() !== '') {
            printPhone2Row.style.display = 'block';
            if (document.getElementById('print-phone2')) document.getElementById('print-phone2').innerText = String(_phone2Val).trim();
        } else {
            printPhone2Row.style.display = 'none';
        }
    }

    // <i class=\'fa-solid fa-star\'></i> V14.2: إخفاء العنوان للفرع برمجياً - لا يطبع العنوان نهائياً
    let printAddressRow = document.querySelector('.print-address-row');
    if (isBranch) {
        if (printAddressRow) printAddressRow.style.display = 'none';
        if (document.getElementById('print-address')) document.getElementById('print-address').innerText = '';
    } else {
        if (printAddressRow) printAddressRow.style.display = '';
        if (document.getElementById('print-address')) document.getElementById('print-address').innerText = order.address || order.customerAddress || '';
    }

    if (document.getElementById('print-items-body')) document.getElementById('print-items-body').innerHTML = printItemsHtml || '<tr><td colspan="4">لا توجد تفاصيل</td></tr>';

    if (document.getElementById('print-subtotal')) document.getElementById('print-subtotal').innerText = isOldGift ? "***" : (order.subtotal || order.total || 0);
    if (document.getElementById('print-discount')) document.getElementById('print-discount').innerText = isOldGift ? "***" : (order.discount || 0);

    // <i class=\'fa-solid fa-star\'></i> V15.0: إخفاء سطر الشحن لطلبات استلام الفرع نهائياً
        // <i class='fa-solid fa-star'></i> V15.0: إخفاء سطر الشحن لطلبات استلام الفرع أو إذا كان الشحن 0 نهائياً
    let printShippingRow = document.querySelector('.print-shipping-row');
    let shipVal = parseFloat(order.shipping) || 0;
    if (isBranch || shipVal === 0) {
        if (printShippingRow) printShippingRow.style.setProperty('display', 'none', 'important');
    } else {
        if (printShippingRow) printShippingRow.style.removeProperty('display');
        if (document.getElementById('print-shipping')) document.getElementById('print-shipping').innerText = isOldGift ? "***" : shipVal;
    }

    // طباعة الملاحظات فقط في حال وجود ملاحظات يدوية فعلية مدخلة من العميل (مع استبعاد وسم الهدية التلقائي ووسوم HTML)
    let orderNotes = String(order.notes || order.customerNotes || "").trim();
    let printNotesRow = document.querySelector('.print-notes-row');
    let printNotesEl = document.getElementById('print-notes');
    let printableNotes = (typeof window.cleanNotesForReceipt === 'function') ? window.cleanNotesForReceipt(orderNotes) : orderNotes.replace(/<[^>]*>?/gm, '').trim();
    if (printNotesRow) {
        if (printableNotes) {
            printNotesRow.style.display = 'block';
            if (printNotesEl) printNotesEl.innerText = printableNotes;
        } else {
            printNotesRow.style.display = 'none';
            if (printNotesEl) printNotesEl.innerText = '';
        }
    }

    if (parseFloat(order.deposit) > 0 && !isOldGift) {
        let depositHtml = `<p class="print-deposit-row">تم دفع عربون: <b><span id="print-deposit">${order.deposit}</span></b></p>`;
        document.getElementById('print-deposit-container').innerHTML = depositHtml;
        document.getElementById('print-final').innerText = order.remaining !== undefined ? order.remaining : order.total;
        if (document.getElementById('print-final-label')) document.getElementById('print-final-label').innerText = "المتبقي للدفع";
    } else {
        document.getElementById('print-deposit-container').innerHTML = '';
        document.getElementById('print-final').innerText = isOldGift ? "***" : order.total;
        if (document.getElementById('print-final-label')) document.getElementById('print-final-label').innerText = "الإجمالي النهائي";
    }

    if (document.getElementById('print-payment')) document.getElementById('print-payment').innerText = order.payment || "";

    let sellerP = document.getElementById('print-seller-name');
    if (sellerP) sellerP.innerText = `الكاشير: ${order.seller || 'غير محدد'}`;

    let isGovShipping = oTypeStr === 'gov_shipping' || oTypeStr.includes('محافظات') || dTypeStr === 'gov_shipping';
    if (isGovShipping) {
        document.body.classList.add('print-gov-shipping', 'shipping-mode');
    } else {
        document.body.classList.remove('print-gov-shipping', 'shipping-mode');
    }

    let qrImg = document.querySelector('img[alt="QR Code"]');
    if (qrImg) qrImg.src = 'images/qr-code.png';

    setTimeout(() => {
        if (isGovShipping) {
            let tableContainers = document.querySelectorAll('.receipt-table, .receipt-table-container');
            tableContainers.forEach(el => el.style.display = 'none');
        }

        window.print();

        if (isGovShipping) {
            let tableContainers = document.querySelectorAll('.receipt-table, .receipt-table-container');
            tableContainers.forEach(el => el.style.display = '');
        }
        document.body.classList.remove('print-gov-shipping', 'shipping-mode');
    }, 500);
};


