const phoneInput = document.getElementById('customerPhone');
const phoneStatus = document.getElementById('phoneCheckStatus');

// Sanitize Phone Inputs (Only 11 English digits, no spaces)
function setupPhoneSanitizer(inputId) {
    const el = document.getElementById(inputId);
    if (!el) return;
    el.addEventListener('input', function(e) {
        let val = e.target.value;
        const arabicNumbers = ['٠','١','٢','٣','٤','٥','٦','٧','٨','٩'];
        for (let i = 0; i < 10; i++) {
            val = val.replaceAll(arabicNumbers[i], i.toString());
        }
        val = val.replace(/\D/g, ''); 
        if (val.length > 11) val = val.substring(0, 11);
        e.target.value = val;
    });
}
setupPhoneSanitizer('customerPhone');
setupPhoneSanitizer('phone2');


// <i class=\'fa-solid fa-star\'></i> إصلاح ذاكرة السمكة
function performPhoneSearch() {
    if (!phoneInput || !phoneStatus) return;
    let phoneVal = phoneInput.value.trim().replace(/\D/g, '');
    if (phoneVal.length >= 9) {
        phoneStatus.innerHTML = "<i class=\'fa-solid fa-spinner fa-spin\'></i>";

        let foundCustomer = null;
        if (orderHistoryData && orderHistoryData.length > 0) foundCustomer = orderHistoryData.find(o => o.phone.toString().replace(/\D/g, '').includes(phoneVal));
        if (!foundCustomer && window.pendingOrdersData && window.pendingOrdersData.length > 0) foundCustomer = window.pendingOrdersData.find(o => o.phone.toString().replace(/\D/g, '').includes(phoneVal));

        if (foundCustomer) {
            fillCustomerData(foundCustomer);
        } else {
            // البحث الشامل الصامت في قاعدة العملاء
            (async () => { let keyword = phoneVal; // Supabase Global Search
            const keyword_lower = keyword.toLowerCase();
            const { data: searchResults, error: searchErr } = await fetchAllSupabaseRows(
                supabase.from('orders').select('*')
                .or(`order_id.ilike.%${keyword}%,customer_name.ilike.%${keyword}%,phone.ilike.%${keyword}%`)
            );
            if (searchErr) throw searchErr;
            
            let results = (searchResults || []).map(o => ({
                id: o.order_id, date: o.order_date, time: o.order_time,
                name: o.customer_name, phone: o.phone, phone2: o.alt_phone || "",
                address: o.address, products: o.products, subtotal: o.products_total,
                discount: o.discount, shipping: o.shipping_cost, total: parseFloat(o.final_total) || 0,
                status: o.status, payment: o.payment_method, seller: o.moderator_name,
                orderType: o.delivery_type, deposit: o.deposit || 0,
                remaining: o.remaining || o.final_total,
                gov: o.governorate, platform: o.platform, driver: o.driver_name,
                reservationDate: o.delivery_date || ""
            })).reverse();
            return results; })()
                .then(data => {
                    if (data.length > 0) fillCustomerData(data[0]);
                    else phoneStatus.innerText = "🆕";
                }).catch(() => phoneStatus.innerHTML = "<i class=\'fa-solid fa-magnifying-glass\'></i>");
        }
    } else {
        phoneStatus.innerHTML = "<i class=\'fa-solid fa-magnifying-glass\'></i>";
    }
}

function fillCustomerData(cust) {
    if (document.getElementById('customerName')) document.getElementById('customerName').value = cust.name;
    if (document.getElementById('address') && cust.address && cust.address !== 'استلام من الفرع') {
        document.getElementById('address').value = cust.address;
    }
    phoneStatus.innerHTML = "<i class=\'fa-solid fa-check\'></i>";
    showToast(`تم العثور على العميل: ${cust.name}`, "success");
}

if (phoneStatus) phoneStatus.addEventListener('click', performPhoneSearch);
if (phoneInput) phoneInput.addEventListener('change', performPhoneSearch);

const productsContainer = document.getElementById('productsContainer');

// ==========================================
// دالة التحقق من الحالة الفارغة لقائمة منتجات الفاتورة
// ==========================================
function checkOrderProductsEmptyState() {
    if (!productsContainer) return;
    const rows = productsContainer.querySelectorAll('.product-row');
    let emptyEl = productsContainer.querySelector('.order-products-empty-state');
    if (rows.length === 0) {
        if (!emptyEl) {
            emptyEl = document.createElement('div');
            emptyEl.className = 'order-products-empty-state';
            emptyEl.innerHTML = `
                <i class="fa-solid fa-basket-shopping"></i>
                <div style="font-weight: 700; margin-bottom: 4px;">لا توجد منتجات مضافة بعد</div>
                <div style="font-size: 0.85rem;">ابحث باسم المنتج أو امسح الباركود في الأعلى لإضافته للفاتورة</div>
            `;
            productsContainer.appendChild(emptyEl);
        }
    } else {
        if (emptyEl) emptyEl.remove();
    }
}

// ==========================================
// محرك البحث الحي في الكتالوج والباركود
// ==========================================
function searchAllCatalogProducts(query) {
    if (!query) return [];
    const q = String(query).trim().toLowerCase();
    const results = [];
    const seenNames = new Set();

    // 1. البحث في catalogData (Supabase + عروض)
    if (typeof catalogData !== 'undefined' && Array.isArray(catalogData)) {
        for (const item of catalogData) {
            if (!item || !item.name) continue;
            const nameLower = item.name.toLowerCase();
            const barcodeStr = String(item.barcode || '').toLowerCase();
            if (nameLower.includes(q) || barcodeStr.includes(q)) {
                seenNames.add(nameLower);
                results.push({
                    name: item.name,
                    price: parseFloat(item.price) || 0,
                    isOffer: !!item.isOffer,
                    offerPrice: parseFloat(item.offerPrice) || 0,
                    barcode: item.barcode || '',
                    stock: item.stock !== undefined ? item.stock : ''
                });
            }
            if (results.length >= 25) break;
        }
    }

    // 2. البحث في barcodeCatalogData (Firebase)
    if (results.length < 25 && typeof barcodeCatalogData !== 'undefined' && Array.isArray(barcodeCatalogData)) {
        for (const item of barcodeCatalogData) {
            if (!item || !item.name) continue;
            const nameLower = item.name.toLowerCase();
            if (seenNames.has(nameLower)) continue;
            const barcodeStr = String(item.barcode || '').toLowerCase();
            if (nameLower.includes(q) || barcodeStr.includes(q)) {
                seenNames.add(nameLower);
                results.push({
                    name: item.name,
                    price: parseFloat(item.price) || 0,
                    isOffer: false,
                    offerPrice: 0,
                    barcode: item.barcode || '',
                    stock: item.stock !== undefined ? item.stock : ''
                });
            }
            if (results.length >= 25) break;
        }
    }

    return results;
}

// تهيئة قائمة البحث الحية لخانة إدخال المنتجات
function initOrderProductSearch() {
    const input = document.getElementById('orderBarcodeInput');
    const resultsContainer = document.getElementById('orderProductSearchResults');
    const searchBtn = document.getElementById('orderSearchBarcodeBtn');
    if (!input || !resultsContainer) return;

    let highlightedIndex = -1;

    function renderResults(query) {
        const list = searchAllCatalogProducts(query);
        if (list.length === 0) {
            resultsContainer.innerHTML = `
                <div style="padding: 16px; text-align: center; color: #94a3b8; font-size: 0.9rem;">
                    <i class="fa-solid fa-circle-exclamation" style="margin-left: 6px;"></i> لا توجد أصناف مطابقة لـ "${query}"
                </div>`;
            resultsContainer.style.display = 'block';
            highlightedIndex = -1;
            return;
        }

        resultsContainer.innerHTML = list.map((item, idx) => {
            const hasOffer = item.isOffer && item.offerPrice > 0;
            const priceHtml = hasOffer
                ? `<span class="order-search-item-offer">${item.offerPrice} ج.م</span><del style="color:#94a3b8; font-size:0.75rem;">${item.price} ج.م</del>`
                : `<span class="order-search-item-price">${item.price} ج.م</span>`;
            const barcodeBadge = item.barcode ? `<span style="font-family:monospace; background:#e2e8f0; padding:2px 6px; border-radius:4px; font-size:0.75rem;">${item.barcode}</span>` : '';
            const stockBadge = (item.stock !== '' && !isNaN(Number(item.stock))) ? `<span style="color:#64748b; font-size:0.75rem;">مخزون: ${item.stock}</span>` : '';
            return `
                <div class="order-search-item" data-index="${idx}" data-name="${item.name}" data-price="${item.price}" data-offer="${hasOffer ? item.offerPrice : ''}">
                    <div class="order-search-item-info">
                        <span class="order-search-item-name">${item.name}</span>
                        <div class="order-search-item-meta">${barcodeBadge} ${stockBadge}</div>
                    </div>
                    <div class="order-search-item-price-box">
                        ${priceHtml}
                    </div>
                </div>
            `;
        }).join('');
        resultsContainer.style.display = 'block';
        highlightedIndex = -1;

        resultsContainer.querySelectorAll('.order-search-item').forEach(el => {
            el.addEventListener('click', () => {
                const name = el.getAttribute('data-name');
                const price = el.getAttribute('data-price');
                const offer = el.getAttribute('data-offer');
                addProductRow(name, price, "1", true, offer);
                input.value = '';
                resultsContainer.style.display = 'none';
                input.focus();
            });
        });
    }

    input.addEventListener('input', () => {
        const val = input.value.trim();
        if (typeof parseScaleBarcode === 'function') {
            const scaleInfo = parseScaleBarcode(val);
            if (scaleInfo) {
                if (typeof handleBarcodeMatch === 'function') {
                    if (typeof currentScannerMode !== 'undefined') currentScannerMode = 'order';
                    handleBarcodeMatch(val);
                    input.value = '';
                    resultsContainer.style.display = 'none';
                    return;
                }
            }
        }
        if (!val) {
            resultsContainer.style.display = 'none';
            return;
        }
        renderResults(val);
    });

    input.addEventListener('keydown', (e) => {
        const items = resultsContainer.querySelectorAll('.order-search-item');
        if (resultsContainer.style.display === 'block' && items.length > 0) {
            if (e.key === 'ArrowDown') {
                e.preventDefault();
                highlightedIndex = (highlightedIndex + 1) % items.length;
                updateHighlight(items);
                return;
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                highlightedIndex = (highlightedIndex - 1 + items.length) % items.length;
                updateHighlight(items);
                return;
            } else if (e.key === 'Enter') {
                e.preventDefault();
                if (highlightedIndex >= 0 && items[highlightedIndex]) {
                    items[highlightedIndex].click();
                } else if (items.length > 0) {
                    items[0].click();
                } else if (searchBtn) {
                    searchBtn.click();
                }
                return;
            } else if (e.key === 'Escape') {
                resultsContainer.style.display = 'none';
                return;
            }
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (searchBtn) searchBtn.click();
        }
    });

    function updateHighlight(items) {
        items.forEach((it, idx) => {
            if (idx === highlightedIndex) {
                it.classList.add('highlighted');
                it.scrollIntoView({ block: 'nearest' });
            } else {
                it.classList.remove('highlighted');
            }
        });
    }

    document.addEventListener('click', (e) => {
        if (!input.contains(e.target) && !resultsContainer.contains(e.target)) {
            resultsContainer.style.display = 'none';
        }
    });
}

// ==========================================
// دالة إضافة المنتجات للفاتورة (مقيدة بالكتالوج والباركود)
// ==========================================
function addProductRow(nameVal = "", priceVal = "", qtyVal = "1", isConfirmed = true, offerVal = "") {
    if (!productsContainer) return;

    // منع إضافة صف فارغ بدون اختيار منتج محدد
    if (!nameVal || String(nameVal).trim() === "") {
        const sInp = document.getElementById('orderBarcodeInput');
        if (sInp) {
            sInp.focus();
            sInp.select();
        }
        showToast("يرجى البحث باسم المنتج أو مسح الباركود أولاً", "info");
        return;
    }

    const cleanName = String(nameVal).trim();

    // 1. زيادة الكمية تلقائياً إذا كان الصنف مضافاً مسبقاً في الفاتورة
    const existingRows = Array.from(productsContainer.querySelectorAll('.product-row'));
    let foundRow = existingRows.find(row => {
        const inp = row.querySelector('.product-name-input');
        return inp && inp.value.trim().toLowerCase() === cleanName.toLowerCase();
    });

    if (foundRow) {
        const qInp = foundRow.querySelector('.product-qty-input');
        if (qInp) {
            const currentQty = parseFloat(qInp.value) || 0;
            const addedQty = parseFloat(qtyVal) || 1;
            qInp.value = currentQty + addedQty;
            qInp.dispatchEvent(new Event('input'));
        }
        foundRow.style.transition = 'all 0.3s ease';
        foundRow.style.boxShadow = '0 0 0 2px #10b981';
        setTimeout(() => { if (foundRow) foundRow.style.boxShadow = ''; }, 700);
        calculateTotal();
        if (typeof window.playSuccessBeep === 'function') window.playSuccessBeep();
        showToast(`تمت زيادة كمية (${cleanName}) بنجاح`, "success");
        return;
    }

    // إزالة رسالة الحالة الفارغة
    const emptyEl = productsContainer.querySelector('.order-products-empty-state');
    if (emptyEl) emptyEl.remove();

    // استكمال السعر الأساسي وسعر العرض من الكتالوج إن لم يمررا
    let basePrice = (priceVal !== "" && priceVal !== undefined) ? priceVal : "";
    let offerPrice = (offerVal !== "" && offerVal !== undefined) ? offerVal : "";

    if (basePrice === "" || basePrice === undefined) {
        const catMatch = (typeof catalogData !== 'undefined' && Array.isArray(catalogData) ? catalogData.find(p => p.name === cleanName) : null) ||
                         (typeof barcodeCatalogData !== 'undefined' && Array.isArray(barcodeCatalogData) ? barcodeCatalogData.find(p => p.name === cleanName) : null);
        if (catMatch) {
            basePrice = parseFloat(catMatch.price) || 0;
            if (catMatch.isOffer && parseFloat(catMatch.offerPrice) > 0) {
                offerPrice = parseFloat(catMatch.offerPrice) || 0;
            }
        }
    }

    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.flexDirection = 'column';
    wrapper.style.marginBottom = '10px';

    const div = document.createElement('div');
    div.className = 'product-row confirmed';

    div.innerHTML = `
        <div class="product-col-name" style="position: relative; display: flex; align-items: center;">
            <span class="product-name-title" title="${cleanName}">${cleanName}</span>
            <input type="hidden" class="product-name-input" value="${cleanName}" required>
        </div>
        <input type="number" class="product-price-input" placeholder="السعر" value="${basePrice}" readonly required title="السعر الأساسي مقفل من الكتالوج">
        <input type="number" class="product-offer-input" placeholder="سعر العرض" value="${offerPrice}" step="any" title="يمكن تعديل سعر العرض أو الخصم لهذا الأوردر">
        <input type="number" class="product-qty-input" placeholder="الكمية" value="${qtyVal}" min="1" step="any" required>
        <div class="product-row-actions">
            <button type="button" class="remove-product-btn interactive-btn" title="حذف الصنف"><i class="fa-solid fa-trash-can"></i></button>
            <button type="button" class="btn-confirm-pro interactive-btn" style="display:none;">✔️</button>
        </div>
    `;

    wrapper.appendChild(div);
    productsContainer.appendChild(wrapper);

    let offerInput = div.querySelector('.product-offer-input');
    let qtyInput = div.querySelector('.product-qty-input');
    let removeBtn = div.querySelector('.remove-product-btn');

    offerInput.addEventListener('input', calculateTotal);
    qtyInput.addEventListener('input', calculateTotal);

    removeBtn.addEventListener('click', () => {
        wrapper.remove();
        calculateTotal();
        checkOrderProductsEmptyState();
    });

    calculateTotal();
    if (typeof window.playSuccessBeep === 'function') window.playSuccessBeep();
}

function updateSmartProductsList() {
    if (typeof updateSmartSuggestionsFromFirebase === 'function') {
        updateSmartSuggestionsFromFirebase();
    }
}

if (document.getElementById('addProductBtn')) {
    document.getElementById('addProductBtn').addEventListener('click', () => {
        const sInp = document.getElementById('orderBarcodeInput');
        if (sInp) {
            sInp.focus();
            sInp.select();
        }
        showToast("ابحث باسم المنتج أو امسح الباركود لإضافته للفاتورة", "info");
    });
}

checkOrderProductsEmptyState();
initOrderProductSearch();

// <i class=\'fa-solid fa-star\'></i> نظام العربون والـ NaN
function calculateTotal() {
    let total = 0;
    document.querySelectorAll('.product-row.confirmed').forEach(row => {
        let price = parseFloat(row.querySelector('.product-price-input').value) || 0;
        let offer = parseFloat(row.querySelector('.product-offer-input').value) || 0;
        let finalPrice = offer > 0 ? offer : price;
        let qty = parseFloat(row.querySelector('.product-qty-input').value) || 1;
        total += (finalPrice * qty); // محصنة ضد الـ NaN
    });

    if (document.getElementById('productsTotal')) document.getElementById('productsTotal').value = total;
    let discount = document.getElementById('discount') ? (parseFloat(document.getElementById('discount').value) || 0) : 0;
    let shipping = document.getElementById('shippingCost') ? (parseFloat(document.getElementById('shippingCost').value) || 0) : 0;

    let finalAmount = total + shipping - discount;
    let finalDisplay = document.getElementById('finalTotalDisplay');

    if (finalDisplay) finalDisplay.innerText = finalAmount;

    // حساب العربون
    let depositInput = document.getElementById('depositAmount');
    let remainingDisplay = document.getElementById('remainingAmountDisplay');
    if (depositInput && remainingDisplay) {
        let dep = parseFloat(depositInput.value) || 0;
        let rem = finalAmount - dep;
        if (rem < 0) rem = 0;
        remainingDisplay.innerText = rem;
    }

    let giftCheck = document.getElementById('isGiftCheckbox');
    let hint = document.getElementById('giftHint');
    if (giftCheck && giftCheck.checked) {
        if (!hint) {
            hint = document.createElement('div');
            hint.id = 'giftHint';
            hint.style.cssText = "color:var(--primary); font-size:0.8rem; font-weight:bold; text-align:center; margin-top:5px;";
            hint.innerText = "* أوردر هدية: سيتم حفظ السعر بالإكسيل وإخفاؤه في الفاتورة المطبوعة *";
            finalDisplay.parentNode.appendChild(hint);
        }
    } else {
        if (hint) hint.remove();
    }
}

if (document.getElementById('discount')) document.getElementById('discount').addEventListener('input', calculateTotal);
if (document.getElementById('isGiftCheckbox')) document.getElementById('isGiftCheckbox').addEventListener('change', calculateTotal);
if (document.getElementById('depositAmount')) document.getElementById('depositAmount').addEventListener('input', calculateTotal);

// <i class=\'fa-solid fa-star\'></i> منع اختراق الكيبورد بـ readonly و disabled
const paymentMethod = document.getElementById('paymentMethod');
if (paymentMethod) {
    paymentMethod.addEventListener('change', function() {
        this.classList.remove('payment-cash', 'payment-instapay');
        if (this.value === 'كاش') this.classList.add('payment-cash');
        else if (this.value === 'إنستا باي / محفظة') this.classList.add('payment-instapay');
    });
}
const confirmPaymentBtn = document.getElementById('confirmPaymentBtn');
let isPaymentConfirmed = false;
const upperFields = ['platform', 'customerName', 'customerPhone', 'phone2', 'deliveryType', 'specialDateInput', 'governorate', 'address'];

function toggleGlobalLock(shouldLock) {
    upperFields.forEach(id => {
        let el = document.getElementById(id);
        if (el) {
            if (shouldLock) {
                el.classList.add('locked-field');
                if (el.tagName === 'SELECT') el.disabled = true; else el.readOnly = true;
            } else {
                el.classList.remove('locked-field');
                if (el.tagName === 'SELECT') el.disabled = false; else el.readOnly = false;
            }
        }
    });
}
if (confirmPaymentBtn) {
    confirmPaymentBtn.addEventListener('click', () => {
        if (!paymentMethod || !paymentMethod.value) { showToast("اختر طريقة الدفع أولاً!", "error"); return; }
        if (isPaymentConfirmed) {
            isPaymentConfirmed = false; confirmPaymentBtn.classList.remove('confirmed'); confirmPaymentBtn.innerHTML = "تأكيد ✔️";
            paymentMethod.classList.remove('locked-field'); paymentMethod.disabled = false; toggleGlobalLock(false);
        } else {
            isPaymentConfirmed = true; confirmPaymentBtn.classList.add('confirmed'); confirmPaymentBtn.innerHTML = "تم التأكيد <i class=\'fa-solid fa-lock\'></i>";
            paymentMethod.classList.add('locked-field'); paymentMethod.disabled = true; toggleGlobalLock(true);
        }
    });
}

// ==========================================
// 7. المعلقات 
// ==========================================

function updateSuspendedCount() {
    let count = window.suspendedOrdersData ? window.suspendedOrdersData.length : 0;
    let countEl = document.getElementById('suspendedCount');
    let btn = document.getElementById('openSuspendedBtn');
    if (countEl) countEl.innerText = count;
    if (btn) {
        let icon = btn.querySelector('.btn-suspended-icon');
        if (count > 0) {
            btn.classList.add('has-items');
            btn.classList.remove('is-empty');
            if (icon) icon.className = 'fa-solid fa-folder-open btn-suspended-icon';
        } else {
            btn.classList.remove('has-items');
            btn.classList.add('is-empty');
            if (icon) icon.className = 'fa-solid fa-folder-closed btn-suspended-icon';
        }
        if (typeof window.updateSuspendedButtonVisibility === 'function') {
            window.updateSuspendedButtonVisibility();
        }
    }
}

let suspendBtn = document.getElementById('suspendBtn');
if (suspendBtn) {
    suspendBtn.addEventListener('click', async () => {
        if (typeof window.checkModeratorShippingStatus === 'function') {
            const lockCheck = window.checkModeratorShippingStatus();
            if (lockCheck && lockCheck.locked) {
                showToast("⛔ خانة إنشاء الطلبات موقوفة مؤقتاً لحسابك لوجود أوردرات متأخرة! يرجى شحنها أو إغلاقها أولاً.", "error");
                if (typeof window.playErrorBeep === 'function') window.playErrorBeep();
                const card = document.getElementById('moderatorLockoutCard');
                if (card) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
                return;
            }
        }

        let nameEl = document.getElementById('customerName');
        let name = nameEl && nameEl.value.trim() ? nameEl.value.trim() : "";
        let phoneEl = document.getElementById('customerPhone');
        let phone = phoneEl && phoneEl.value.trim() ? phoneEl.value.trim() : "";

        let prods = [];
        document.querySelectorAll('.product-row').forEach(row => {
            let nEl = row.querySelector('.product-name-input');
            let pEl = row.querySelector('.product-price-input');
            let oEl = row.querySelector('.product-offer-input');
            let qEl = row.querySelector('.product-qty-input');
            let n = nEl ? nEl.value.trim() : "";
            let p = pEl ? pEl.value : "";
            let o = oEl ? oEl.value : "";
            let q = qEl ? qEl.value : "1";
            let c = row.classList.contains('confirmed');
            if (n) prods.push({ name: n, price: p, offer: o, qty: q, confirmed: c });
        });

        if (!name && !phone && prods.length === 0) {
            showToast("لا توجد بيانات لتعليقها!", "warning");
            if (typeof window.playErrorBeep === 'function') window.playErrorBeep();
            return;
        }

        setBtnLoading(suspendBtn, true);

        let draftId = "DRAFT-" + Date.now().toString().slice(-6);
        let now = new Date();
        let timeStr = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

        let moderatorSelect = document.getElementById('moderatorSelect');
        let selectedModerator = moderatorSelect ? moderatorSelect.value : "";

        let draft = {
            id: draftId,
            draftId: draftId,
            date: timeStr,
            time: timeStr,
            customerName: name || "بدون اسم",
            name: name || "بدون اسم",
            phone: phone,
            phone2: document.getElementById('phone2') ? document.getElementById('phone2').value : "",
            platform: document.getElementById('platform') ? document.getElementById('platform').value : "",
            moderator: selectedModerator,
            delType: deliveryTypeSelect ? deliveryTypeSelect.value : "normal",
            spDate: document.getElementById('specialDateInput') ? document.getElementById('specialDateInput').value : "",
            gov: document.getElementById('governorate') ? document.getElementById('governorate').value : "",
            address: document.getElementById('address') ? document.getElementById('address').value : "",
            discount: document.getElementById('discount') ? document.getElementById('discount').value : "",
            shippingCost: document.getElementById('shippingCost') ? document.getElementById('shippingCost').value : "0",
            productsTotal: document.getElementById('productsTotal') ? document.getElementById('productsTotal').value : "0",
            finalTotal: document.getElementById('finalTotalDisplay') ? document.getElementById('finalTotalDisplay').innerText : "0",
            payMethod: paymentMethod ? paymentMethod.value : "",
            isPaymentConfirmed: isPaymentConfirmed || false,
            depositAmount: document.getElementById('depositAmount') ? document.getElementById('depositAmount').value : "",
            notes: document.getElementById('notes') ? document.getElementById('notes').value : "",
            gift: document.getElementById('isGiftCheckbox') ? document.getElementById('isGiftCheckbox').checked : false,
            prods: prods
        };

        let formData = new URLSearchParams();
        formData.append('action', 'suspendOrder');
        formData.append('draftId', draftId);
        formData.append('draftJson', JSON.stringify(draft));

        try {
            let res = await fetch(GOOGLE_SHEETS_URL, { method: 'POST', body: formData });
            let resData = await res.json();
            if (resData && resData.success === false) {
                showToast("فشل تعليق الفاتورة: " + (resData.error || ''), "error");
            } else {
                showToast("⏸️ تم تعليق الفاتورة بنجاح!", "warning");
                if (typeof window.playSuccessBeep === 'function') window.playSuccessBeep();
                
                // Add to memory list
                window.suspendedOrdersData = window.suspendedOrdersData || [];
                window.suspendedOrdersData.unshift(draft);
                updateSuspendedCount();
                resetForm();
            }
        } catch (e) {
            console.error('Suspend error:', e);
            showToast("حدث خطأ أثناء تعليق الفاتورة", "error");
        } finally {
            setBtnLoading(suspendBtn, false, "⏸️ تعليق الطلب");
        }
    });
}

