const ledgerSearchBarcodeBtn = document.getElementById('ledgerSearchBarcodeBtn');
if (ledgerSearchBarcodeBtn) {
    ledgerSearchBarcodeBtn.addEventListener('click', () => {
        const val = document.getElementById('ledgerProdBarcode').value.trim();
        if (!val) {
            showToast("يرجى كتابة الباركود أولاً", "warning");
            return;
        }
        if (typeof currentScannerMode !== 'undefined') {
            currentScannerMode = 'ledger';
        }
        processBarcodeAction(val);
    });
}

const ledgerProdBarcodeInp = document.getElementById('ledgerProdBarcode');
if (ledgerProdBarcodeInp) {
    ledgerProdBarcodeInp.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (ledgerSearchBarcodeBtn) ledgerSearchBarcodeBtn.click();
        }
    });
    ledgerProdBarcodeInp.addEventListener('change', () => {
        const val = ledgerProdBarcodeInp.value.trim();
        if (val) applyLedgerMarketplaceDefaults(val);
        const scaleInfo = parseScaleBarcode(val);
        if (scaleInfo) {
            const found = (typeof barcodeCatalogData !== 'undefined' && Array.isArray(barcodeCatalogData) && barcodeCatalogData.length > 0)
                ? barcodeCatalogData.find(p => String(p.barcode).split(',').map(b => b.trim().toLowerCase()).includes(scaleInfo.itemCode.toLowerCase()) || (scaleInfo.itemCode === '000001' && p.name && p.name.includes('كاندي')))
                : null;
            const ledgerProdName = document.getElementById('ledgerProdName');
            const ledgerProdQty = document.getElementById('ledgerProdQty');
            if (ledgerProdName) ledgerProdName.value = found ? found.name : 'كاندي بالوزن';
            if (ledgerProdQty) ledgerProdQty.value = scaleInfo.weightKg;
            showToast(`<i class='fa-solid fa-scale-balanced'></i> تم قراءة استيكر ميزان: ${scaleInfo.weightGrams} جم (${scaleInfo.weightKg} كجم)`, "success");
            return;
        }
        if (val && typeof barcodeCatalogData !== 'undefined' && barcodeCatalogData.length > 0) {
            const found = barcodeCatalogData.find(p => String(p.barcode).split(',').map(b => b.trim().toLowerCase()).includes(val.toLowerCase()));
            if (found && found.name) {
                const ledgerProdName = document.getElementById('ledgerProdName');
                if (ledgerProdName && (!ledgerProdName.value || ledgerProdName.value.includes('مزامنة') || ledgerProdName.value === 'غير مسجل')) {
                    ledgerProdName.value = found.name;
                }
            }
        }
    });
}

// حماية حقل الكمية في الاستلامات: لو الكاشير مسح باركود بالخطأ أثناء وقوف المؤشر على الكمية، يتم تحويله للباركود فوراً
const ledgerProdQtyInp = document.getElementById('ledgerProdQty');
if (ledgerProdQtyInp) {
    ledgerProdQtyInp.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            const val = String(ledgerProdQtyInp.value || '').trim();
            if (val.length >= 6) {
                e.preventDefault();
                ledgerProdQtyInp.value = '1';
                const bInp = document.getElementById('ledgerProdBarcode');
                if (bInp) {
                    bInp.value = val;
                    if (typeof processBarcodeAction === 'function') {
                        currentScannerMode = 'ledger';
                        processBarcodeAction(val);
                    }
                }
            }
        }
    });
}

