window.promptNewOffer = function (id) {
    customPrompt("تفعيل عرض جديد", (orig, offer) => {
        if (orig === "" || offer === "") {
            showToast("يرجى إدخال السعرين", "warning");
            return;
        }
        saveExpiryOffer(id, 'في عرض', orig, offer);
    });
};

window.saveExpiryOffer = function (id, status, origVal, offerVal) {
    let orig = origVal !== undefined ? origVal : (document.getElementById('origPrice_' + id) ? document.getElementById('origPrice_' + id).value : "");
    let offer = offerVal !== undefined ? offerVal : (document.getElementById('offerPrice_' + id) ? document.getElementById('offerPrice_' + id).value : "");

    showToast("جاري التحديث...", "warning");
    let formData = new URLSearchParams();
    formData.append('action', 'updateExpiryStatus');
    formData.append('id', id);
    formData.append('status', status);
    formData.append('originalPrice', orig);
    formData.append('offerPrice', offer);

    fetch(GOOGLE_SHEETS_URL, { method: 'POST', mode: 'no-cors', body: formData })
        .then(() => {
            showToast("<i class=\'fa-solid fa-check\'></i> تم تحديث العرض والأسعار بنجاح", "success");
            let item = expiryData.find(i => i.id == id);
            if (item) {
                item.status = status;
                item.originalPrice = orig;
                item.offerPrice = offer;
            }
            renderExpiryDashboard();
            updateCatalogWithOffers();
            // Re-render the current view
            if (document.getElementById('detailsTitle').innerText.includes('البحث')) {
                showExpiryDetails('Search');
            } else if (document.getElementById('detailsTitle').innerText.includes('العروض')) {
                showExpiryDetails('Offers');
            } else {
                // If in another category, just close and user can reopen or re-render
                document.getElementById('expiryDetailsSection').style.display = 'none';
            }
        }).catch(() => {
            showToast("<i class=\'fa-solid fa-xmark\'></i> خطأ في الاتصال بالإنترنت", "error");
        });
};

// 3. Status Control (دورة حياة العرض)
window.customQtyConfirm = function (message, currentQty, onConfirm) {
    const overlay = document.createElement('div');
    overlay.style = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.6); z-index: 10000; display: flex; justify-content: center; align-items: center; backdrop-filter: blur(5px);";
    const modal = document.createElement('div');
    modal.style = "background: white; padding: 25px; border-radius: 15px; text-align: center; max-width: 400px; width: 90%; box-shadow: 0 10px 25px rgba(0,0,0,0.2);";
    modal.innerHTML = `
        <h3 style="color: var(--primary); margin-top: 0;">تأكيد الإجراء</h3>
        <p style="font-size: 1.1rem; color: #333; margin-bottom: 15px;">${message}</p>
        <p style="font-size: 0.95rem; color: #666; margin-bottom: 10px;">الكمية الحالية: ${currentQty}</p>
        <input type="number" id="promptSoldQty" value="${currentQty}" min="1" max="${currentQty}" placeholder="الكمية المباعة" style="width: 100%; padding: 10px; margin-bottom: 20px; border-radius: 8px; border: 1px solid #ccc;">
        <div style="display: flex; gap: 10px; justify-content: center;">
            <button id="btnConfirmYes" class="interactive-btn" style="background: #27ae60; color: white; border: none; padding: 10px 20px; border-radius: 8px; font-weight: bold; flex: 1;">تأكيد البيع <i class=\'fa-solid fa-check\'></i></button>
            <button id="btnConfirmNo" class="interactive-btn" style="background: #e74c3c; color: white; border: none; padding: 10px 20px; border-radius: 8px; font-weight: bold; flex: 1;">إلغاء <i class=\'fa-solid fa-xmark\'></i></button>
        </div>
    `;
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    document.getElementById('btnConfirmYes').onclick = () => {
        let val = parseFloat(document.getElementById('promptSoldQty').value);
        if (isNaN(val) || val <= 0 || val > currentQty) {
            showToast("الكمية المدخلة غير صحيحة!", "error");
            return;
        }
        document.body.removeChild(overlay);
        onConfirm(val);
    };
    document.getElementById('btnConfirmNo').onclick = () => {
        document.body.removeChild(overlay);
    };
};

window.changeExpiryStatus = function (idString, newStatus) {
    let msg = "";
    if (newStatus === 'في عرض') {
        msg = "هل تريد تفعيل العرض وجعل السطر فسفوري؟ 🔥";
        customConfirm(msg, () => { executeStatusUpdate(idString, newStatus); });
    } else if (newStatus === 'مش في عرض') {
        msg = "هل تريد إيقاف العرض وإعادته للحالة الطبيعية؟";
        customConfirm(msg, () => { executeStatusUpdate(idString, newStatus); });
    } else if (newStatus === 'Deleted') {
        msg = "يرجى تحديد الكمية المباعة ليتم خصمها (أو بيع الكل لحذفه)";
        let ids = String(idString).split(',');
        let currentQty = 0;
        ids.forEach(id => {
            let item = expiryData.find(i => String(i.id) === String(id));
            if (item) currentQty += (parseFloat(item.qty) || 0);
        });
        if (currentQty === 0) currentQty = 1;
        window.customQtyConfirm(msg, currentQty, (soldQty) => {
            executeStatusUpdate(idString, newStatus, soldQty);
        });
    }
};

function executeStatusUpdate(idString, newStatus, soldQty = null) {
    let ids = String(idString).split(',');
    showToast("جاري التحديث...", "warning");

    if (newStatus === 'Deleted' && soldQty !== null) {
        let remainingSoldQty = Number(soldQty);
        let promises = [];
        for (let id of ids) {
            if (remainingSoldQty <= 0) break;
            let item = expiryData.find(i => String(i.id) === String(id));
            if (!item) continue;
            let itemQty = Number(item.qty) || 0;
            if (itemQty <= 0) continue;
            let qtyToSubtract = Math.min(itemQty, remainingSoldQty);
            let nextQty = Math.max(0, itemQty - qtyToSubtract);
            let nextStatus = nextQty === 0 ? 'نافد' : (item.status === 'نافد' ? 'مش في عرض' : item.status);

            let formData = new URLSearchParams();
            formData.append('action', 'updateExpiryStatus');
            formData.append('id', id);
            if (item.dbId) formData.append('dbId', item.dbId);
            formData.append('status', nextStatus);
            formData.append('newQty', nextQty);
            formData.append('soldQty', qtyToSubtract);
            promises.push(fetch(GOOGLE_SHEETS_URL, { method: 'POST', mode: 'no-cors', body: formData }));
            remainingSoldQty -= qtyToSubtract;
        }
        Promise.all(promises).then(() => {
            let remainingSoldQtyLocal = Number(soldQty);
            for (let id of ids) {
                if (remainingSoldQtyLocal <= 0) break;
                let item = expiryData.find(i => String(i.id) === String(id));
                if (item) {
                    let itemQty = Number(item.qty) || 0;
                    if (itemQty <= 0) continue;
                    let qtyToSubtract = Math.min(itemQty, remainingSoldQtyLocal);
                    let nextQty = Math.max(0, itemQty - qtyToSubtract);
                    item.qty = nextQty;
                    item.status = nextQty === 0 ? 'نافد' : (item.status === 'نافد' ? 'مش في عرض' : item.status);
                    remainingSoldQtyLocal -= qtyToSubtract;
                }
            }
            showToast("<i class=\'fa-solid fa-check\'></i> تم خصم الكمية وتحديث الرصيد بنجاح", "success");
            renderExpiryDashboard();
            updateCatalogWithOffers();
            if (document.getElementById('expiryDetailsSection').style.display === 'block') {
                showExpiryDetails(expiryCurrentCategory, false);
            }
        }).catch(() => {
            showToast("<i class=\'fa-solid fa-xmark\'></i> خطأ في الاتصال بالإنترنت", "error");
        });
    } else {
        let promises = ids.map(id => {
            let formData = new URLSearchParams();
            formData.append('action', 'updateExpiryStatus');
            formData.append('id', id);
            formData.append('status', newStatus);
            return fetch(GOOGLE_SHEETS_URL, { method: 'POST', mode: 'no-cors', body: formData });
        });
        Promise.all(promises).then(() => {
            showToast("<i class=\'fa-solid fa-check\'></i> تم تحديث الحالة بنجاح", "success");
            ids.forEach(id => {
                let item = expiryData.find(i => String(i.id) === String(id));
                if (item) item.status = newStatus;
            });
            renderExpiryDashboard();
            updateCatalogWithOffers();
            if (document.getElementById('expiryDetailsSection').style.display === 'block') {
                showExpiryDetails(expiryCurrentCategory, false);
            }
        }).catch(() => {
            showToast("<i class=\'fa-solid fa-xmark\'></i> خطأ في الاتصال بالإنترنت", "error");
        });
    }
}

function updateCatalogWithOffers() {
    if (!catalogData || catalogData.length === 0) return;
    
    let activeOffers = [];
    if (expiryData && expiryData.length > 0) {
        activeOffers = expiryData.filter(item => item.status === 'في عرض').map(item => item.name);
        window.cachedActiveOffers = activeOffers;
    } else {
        activeOffers = window.cachedActiveOffers || [];
    }
    
    const catalogContainer = document.getElementById('catalogListContainer');
    if (catalogContainer) {
        const rows = catalogContainer.querySelectorAll('.data-row');
        rows.forEach(row => {
            const nameEl = row.querySelector('strong');
            if (nameEl) {
                const productName = nameEl.innerText.replace('🔥', '').replace('عرض خاص', '').trim();
                const hasOffer = activeOffers.some(offerName => productName.includes(offerName) || offerName.includes(productName));

                if (hasOffer) {
                    if (!nameEl.innerHTML.includes('🔥')) {
                        nameEl.innerHTML += ' <span style="background: #ffeb3b; padding: 2px 6px; border-radius: 4px; font-size: 0.8rem; color: #d35400;">عرض خاص 🔥</span>';
                        row.style.border = "2px solid #ffeb3b";
                    }
                } else {
                    if (nameEl.innerHTML.includes('عرض خاص')) {
                        nameEl.innerHTML = productName;
                        row.style.border = "none";
                    }
                }
            }
        });
    }
}

// ==========================================
// Checkbox and Edit Modal Logic (Expiry)
// ==========================================
window.toggleExpirySelection = function(idString, isChecked) {
    let ids = String(idString).split(',');
    ids.forEach(singleId => {
        if (isChecked) {
            selectedExpiryItems.add(String(singleId));
        } else {
            selectedExpiryItems.delete(String(singleId));
        }
    });
    
    const printSelectedBtn = document.getElementById('printSelectedExpiryBtn');
    if (printSelectedBtn) {
        printSelectedBtn.style.display = selectedExpiryItems.size > 0 ? 'inline-block' : 'none';
    }
};

window.openEditExpiryModal = function(id, batchIndex = null) {
    if (!id && id !== 0 && batchIndex === null && batchIndex === undefined) return;
    const idStr = (id !== undefined && id !== null) ? String(id).trim() : '';
    let item = null;
    let isArchiveItem = false;
    
    // 0. Priority: if opened from an active batch modal with known index
    if (batchIndex !== null && batchIndex !== undefined && Array.isArray(window._currentBatchItems) && window._currentBatchItems[batchIndex]) {
        item = window._currentBatchItems[batchIndex];
        isArchiveItem = true;
    }

    // 1. Search in current batch items by ID
    if (!item && Array.isArray(window._currentBatchItems)) {
        item = window._currentBatchItems.find(it => String(it.id) === idStr);
        if (item) isArchiveItem = true;
    }
    
    // 2. Search in window.receiptsArchiveData (used by receipts batches)
    if (!item && Array.isArray(window.receiptsArchiveData)) {
        item = window.receiptsArchiveData.find(i => String(i.id) === idStr);
        if (item) isArchiveItem = true;
    }

    // 3. Search in expiryData
    if (!item && Array.isArray(expiryData)) {
        item = expiryData.find(i => String(i.id) === idStr || String(i.dbId) === idStr);
    }
    
    // 4. Search in window.expiriesData
    if (!item && Array.isArray(window.expiriesData)) {
        item = window.expiriesData.find(i => String(i.id) === idStr || String(i.dbId) === idStr);
    }

    // 5. Try composite match (name|qty|date or name|qty|date|dbId)
    if (!item && idStr.includes('|')) {
        let parts = idStr.split('|');
        let pName = parts[0];
        let pQty = parts[1];
        let pExp = parts[2];
        let pDbId = parts[3];
        
        if (Array.isArray(window._currentBatchItems)) {
            item = window._currentBatchItems.find(i => (pDbId && String(i.id) === pDbId) || (i.name === pName && i.expiryDate === pExp));
            if (item) isArchiveItem = true;
        }
        if (!item && Array.isArray(window.receiptsArchiveData)) {
            item = window.receiptsArchiveData.find(i => (pDbId && String(i.id) === pDbId) || (i.name === pName && i.expiryDate === pExp));
            if (item) isArchiveItem = true;
        }
        if (!item && Array.isArray(expiryData)) {
            item = expiryData.find(i => (pDbId && String(i.dbId) === pDbId) || (i.name === pName && i.expiryDate === pExp));
        }
    }

    // 6. Fallback: match from DOM card in open batch modal
    if (!item) {
        const batchCard = (batchIndex !== null && batchIndex !== undefined)
            ? document.querySelector(`.batch-item-card[data-batch-index="${batchIndex}"]`)
            : document.querySelector(`.batch-item-card[data-item-id="${id}"]`);
        if (batchCard) {
            const nameEl = batchCard.querySelector('.batch-item-name');
            const cardName = nameEl ? nameEl.innerText.replace(/[\n\r]+/g, ' ').trim() : '';
            if (cardName && Array.isArray(window.receiptsArchiveData)) {
                item = window.receiptsArchiveData.find(i => i.name === cardName);
                if (item) isArchiveItem = true;
            }
        }
    }
    
    if (!item) {
        console.warn("openEditExpiryModal: Item not found with id", id);
        if (typeof showToast === 'function') {
            showToast("تعذر العثور على بيانات هذا الصنف للتعديل", "warning");
        }
        return;
    }
    
    const editModal = document.getElementById('editExpiryModal');
    if (!editModal) {
        console.error("editExpiryModal element not found in DOM");
        return;
    }

    const idInput = document.getElementById('editExpiryId');
    idInput.value = item.id !== undefined ? item.id : idStr;
    idInput.dataset.itemKey = idStr;
    idInput.dataset.batchIndex = (batchIndex !== null && batchIndex !== undefined) ? String(batchIndex) : '';
    idInput.dataset.isArchive = isArchiveItem ? "true" : "false";
    idInput.dataset.archiveId = (item.id && /^\d+$/.test(String(item.id))) ? String(item.id) : (isArchiveItem && /^\d+$/.test(idStr) ? idStr : (item.dbId && /^\d+$/.test(String(item.dbId)) ? String(item.dbId) : ''));
    idInput.dataset.dbId = item.dbId ? String(item.dbId) : '';
    idInput.dataset.origName = item.name || '';
    idInput.dataset.origQty = item.qty !== undefined ? item.qty : '';
    idInput.dataset.origExpiry = item.expiryDate || '';
    idInput.dataset.origReceiver = item.receiver || '';
    idInput.dataset.origLocation = item.location || '';
    idInput.dataset.origNotes = item.notes || '';
    idInput.dataset.origBarcode = item.barcode || '';
    idInput.dataset.regDate = item.regDate || '';

    if (document.getElementById('editExpiryName')) {
        document.getElementById('editExpiryName').value = item.name || '';
    }
    if (document.getElementById('editExpiryQty')) {
        document.getElementById('editExpiryQty').value = item.qty !== undefined ? item.qty : '';
    }
    
    let d = new Date(item.expiryDate);
    if (!isNaN(d.getTime())) {
        document.getElementById('editExpiryDate').value = d.toLocaleDateString('en-CA');
    } else {
        document.getElementById('editExpiryDate').value = item.expiryDate || '';
    }
    
    // Receiver is strictly locked and cannot be edited
    const receiverEl = document.getElementById('editExpiryReceiver');
    if (receiverEl) {
        receiverEl.value = item.receiver || '';
        receiverEl.readOnly = true;
        receiverEl.disabled = true;
    }
    if (document.getElementById('editExpiryLocation')) {
        document.getElementById('editExpiryLocation').value = item.location || '';
    }
    if (document.getElementById('editExpiryNotes')) {
        document.getElementById('editExpiryNotes').value = item.notes || '';
    }
    if (document.getElementById('editExpiryBarcode')) {
        document.getElementById('editExpiryBarcode').value = item.barcode || '';
    }
    
    editModal.style.zIndex = '10020';
    editModal.style.display = 'flex';
};

window.closeEditExpiryModal = function() {
    const editModal = document.getElementById('editExpiryModal');
    if (editModal) editModal.style.display = 'none';
};

window.saveEditExpiryModal = async function() {
    const idInput = document.getElementById('editExpiryId');
    if (!idInput) return;
    
    const id = idInput.value;
    const itemKey = idInput.dataset.itemKey || id;
    const batchIndex = idInput.dataset.batchIndex || '';
    const archiveId = idInput.dataset.archiveId || '';
    const origDbId = idInput.dataset.dbId || '';
    const origName = idInput.dataset.origName || '';
    const origExpiry = idInput.dataset.origExpiry || '';
    const origReceiver = idInput.dataset.origReceiver || '';
    const origRegDate = idInput.dataset.regDate || '';
    const origBarcode = idInput.dataset.origBarcode || '';

    const prodNameInput = document.getElementById('editExpiryName');
    const qtyInput = document.getElementById('editExpiryQty');
    const dateInput = document.getElementById('editExpiryDate');
    const locationInput = document.getElementById('editExpiryLocation');
    const notesInput = document.getElementById('editExpiryNotes');
    const barcodeInput = document.getElementById('editExpiryBarcode');

    const prodName = prodNameInput ? prodNameInput.value.trim() : '';
    const qty = qtyInput ? qtyInput.value.trim() : '';
    const date = dateInput ? dateInput.value.trim() : '';
    // Receiver is locked, strictly keep origReceiver
    const receiver = origReceiver || (document.getElementById('editExpiryReceiver') ? document.getElementById('editExpiryReceiver').value.trim() : '');
    const location = locationInput ? locationInput.value.trim() : '';
    const notes = notesInput ? notesInput.value.trim() : '';
    const barcode = barcodeInput ? barcodeInput.value.trim() : '';
    
    if (!qty || !date) {
        showToast("يرجى تعبئة الكمية وتاريخ الانتهاء", "warning");
        return;
    }

    if (!window.supabase) {
        showToast("خطأ: تعذر الاتصال بقاعدة البيانات Supabase", "error");
        return;
    }

    // Save button loading state
    const saveBtn = document.querySelector('#editExpiryModal button[onclick="saveEditExpiryModal()"]');
    const origBtnHtml = saveBtn ? saveBtn.innerHTML : '';
    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ في السيرفر...';
    }

    try {
        const parsedQty = parseFloat(qty) || 0;

        // 1. UPDATE expiry_receipts_log in Supabase (Receipts Audit Archive)
        const archivePayload = {
            quantity: parsedQty,
            expiry_date: date,
            location: location || '',
            notes: notes || '',
            barcode: barcode || ''
        };
        if (prodName) archivePayload.product_name = prodName;
        if (receiver) archivePayload.receiver = receiver;

        let archiveUpdated = false;
        let arcError = null;

        if (archiveId && /^\d+$/.test(String(archiveId).trim())) {
            const { data: updatedRows, error: err } = await supabase
                .from('expiry_receipts_log')
                .update(archivePayload)
                .eq('id', parseInt(archiveId))
                .select('*');
            if (err) {
                arcError = err;
                console.error("Supabase error updating expiry_receipts_log by id:", err);
            } else if (updatedRows && updatedRows.length > 0) {
                archiveUpdated = true;
            }
        }

        // Fallback: match by product_name + (reg_date or expiry_date)
        if (!archiveUpdated && origName) {
            let q = supabase.from('expiry_receipts_log').update(archivePayload).eq('product_name', origName);
            if (origRegDate) {
                q = q.eq('reg_date', origRegDate);
            } else if (origExpiry) {
                q = q.eq('expiry_date', origExpiry);
            }
            const { data: updatedRows2, error: err2 } = await q.select('*');
            if (err2) {
                arcError = arcError || err2;
                console.error("Supabase error updating expiry_receipts_log fallback:", err2);
            } else if (updatedRows2 && updatedRows2.length > 0) {
                archiveUpdated = true;
            }
        }

        // 2. UPDATE expiries in Supabase (Active Warehouse Inventory)
        const expPayload = {
            qty: String(qty),
            expiry_date: date,
            location: location || '',
            notes: notes || '',
            barcode: barcode || ''
        };
        if (prodName) expPayload.product_name = prodName;
        if (receiver) expPayload.receiver = receiver;

        let expUpdated = false;

        // Try updating by origDbId if known
        if (origDbId && /^\d+$/.test(String(origDbId).trim())) {
            const { data: uExp, error: expErr0 } = await supabase
                .from('expiries')
                .update(expPayload)
                .eq('id', parseInt(origDbId))
                .select('*');
            if (!expErr0 && uExp && uExp.length > 0) expUpdated = true;
        }

        // Try finding matching item in in-memory expiries
        if (!expUpdated) {
            let foundExp = (expiryData || []).find(i => 
                (origName && i.name === origName && (origExpiry ? i.expiryDate === origExpiry : true)) ||
                (origRegDate && i.regDate && i.regDate === origRegDate && i.name === origName) ||
                (String(i.id) === String(id) || String(i.dbId) === String(id) || String(i.id) === String(itemKey))
            );
            if (foundExp && foundExp.dbId) {
                const { data: uExp, error: expErr1 } = await supabase
                    .from('expiries')
                    .update(expPayload)
                    .eq('id', foundExp.dbId)
                    .select('*');
                if (!expErr1 && uExp && uExp.length > 0) expUpdated = true;
            }
        }

        // Fallback: update in expiries by product_name and expiry_date
        if (!expUpdated && origName) {
            let q2 = supabase.from('expiries').update(expPayload).eq('product_name', origName);
            if (origExpiry) q2 = q2.eq('expiry_date', origExpiry);
            const { data: uExp2, error: expErr2 } = await q2.select('*');
            if (!expErr2 && uExp2 && uExp2.length > 0) expUpdated = true;
        }

        // Check if both updates failed and an error was thrown
        if (!archiveUpdated && !expUpdated && arcError) {
            throw new Error(arcError.message || "تعذر التعديل في السيرفر");
        }

        // 3. Update in-memory collections:
        // A) window.receiptsArchiveData
        if (Array.isArray(window.receiptsArchiveData)) {
            let arcItem = window.receiptsArchiveData.find(i => 
                (archiveId && String(i.id) === String(archiveId)) ||
                String(i.id) === String(id) || 
                String(i.id) === String(itemKey) || 
                (origName && i.name === origName && (origExpiry ? i.expiryDate === origExpiry : true))
            );
            if (arcItem) {
                if (prodName) arcItem.name = prodName;
                arcItem.qty = parsedQty;
                arcItem.expiryDate = date;
                arcItem.receiver = receiver;
                arcItem.location = location || '';
                arcItem.notes = notes || '';
                if (barcode !== undefined) arcItem.barcode = barcode;
            }
        }

        // B) window._currentBatchItems (live batch modal items)
        if (Array.isArray(window._currentBatchItems)) {
            let bItem = (batchIndex !== '' && window._currentBatchItems[parseInt(batchIndex, 10)])
                ? window._currentBatchItems[parseInt(batchIndex, 10)]
                : window._currentBatchItems.find(it => 
                    (archiveId && String(it.id) === String(archiveId)) ||
                    String(it.id) === String(id) || 
                    String(it.id) === String(itemKey) || 
                    (origName && it.name === origName && (origExpiry ? it.expiryDate === origExpiry : true))
                );
            if (bItem) {
                if (prodName) bItem.name = prodName;
                bItem.qty = parsedQty;
                bItem.expiryDate = date;
                bItem.receiver = receiver;
                bItem.location = location || '';
                bItem.notes = notes || '';
                if (barcode !== undefined) bItem.barcode = barcode;
            }
        }

        // C) expiryData & window.expiriesData
        [expiryData, window.expiriesData].forEach(arr => {
            if (Array.isArray(arr)) {
                let item = arr.find(i => 
                    (origDbId && String(i.dbId) === String(origDbId)) ||
                    String(i.id) === String(id) || 
                    String(i.id) === String(itemKey) || 
                    (origName && i.name === origName && (origExpiry ? i.expiryDate === origExpiry : true))
                );
                if (item) {
                    if (prodName) item.name = prodName;
                    item.qty = String(qty);
                    item.expiryDate = date;
                    item.receiver = receiver;
                    item.location = location || '';
                    item.notes = notes || '';
                    if (barcode !== undefined) item.barcode = barcode;
                }
            }
        });

        // 4. Update the card in the open batch edit modal live
        const batchCard = (batchIndex !== '')
            ? document.querySelector(`.batch-item-card[data-batch-index="${batchIndex}"]`)
            : document.querySelector(`.batch-item-card[data-item-id="${id}"], .batch-item-card[data-item-id="${itemKey}"]`);
        if (batchCard) {
            const nameEl = batchCard.querySelector('.batch-item-name');
            if (nameEl && prodName) {
                nameEl.innerHTML = `<i class="fa-solid fa-box-open" style="color: #ec4899; font-size: 0.9rem;"></i> ${prodName}`;
            }
            const metaEl = batchCard.querySelector('.batch-item-meta');
            if (metaEl) {
                metaEl.innerHTML = `
                    <span style="background: #ecfdf5; color: #059669; border: 1px solid #a7f3d0; padding: 3px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: 700;">
                        <i class="fa-solid fa-cubes"></i> الكمية: <strong>${qty}</strong>
                    </span>
                    <span style="background: #fef3c7; color: #b45309; border: 1px solid #fde68a; padding: 3px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: 700;">
                        <i class="fa-solid fa-calendar-days"></i> الانتهاء: <strong>${date}</strong>
                    </span>
                    <span style="background: #f8fafc; color: #475569; border: 1px solid #e2e8f0; padding: 3px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: 600;">
                        <i class="fa-solid fa-user-check"></i> المستلم: <strong>${receiver}</strong>
                    </span>
                    ${location ? `
                    <span style="background: #f1f5f9; color: #0284c7; border: 1px solid #bae6fd; padding: 3px 10px; border-radius: 20px; font-size: 0.8rem; font-weight: 600;">
                        <i class="fa-solid fa-location-dot"></i> المكان: <strong>${location}</strong>
                    </span>` : ''}
                `;
            }
        }

        // 5. Update total pieces counter in the batch edit modal header
        const totalQtyBadge = document.getElementById('batchModalTotalQty');
        if (totalQtyBadge) {
            let totalSum = 0;
            if (Array.isArray(window._currentBatchItems) && window._currentBatchItems.length > 0) {
                totalSum = window._currentBatchItems.reduce((acc, it) => acc + (parseFloat(it.qty) || 0), 0);
            } else {
                document.querySelectorAll('.batch-item-card').forEach(card => {
                    let text = card.innerText || '';
                    let m = text.match(/الكمية:\s*([\d.]+)/);
                    if (m) totalSum += parseFloat(m[1]) || 0;
                });
            }
            totalQtyBadge.innerText = `${totalSum} قطعة`;
        }

        showToast("<i class='fa-solid fa-check'></i> تم حفظ التعديلات وتحديث السيرفر بنجاح", "success");
        closeEditExpiryModal();

        if (typeof renderExpiryDashboard === 'function') {
            renderExpiryDashboard();
        }
        if (typeof window.renderExpiryCalendarDots === 'function') {
            window.renderExpiryCalendarDots();
        }
        if (document.getElementById('expiryDetailsSection') && document.getElementById('expiryDetailsSection').style.display === 'block') {
            showExpiryDetails(expiryCurrentCategory, false);
        }
    } catch(err) {
        console.error("Error saving expiry:", err);
        showToast("حدث خطأ أثناء حفظ التعديلات في السيرفر: " + (err.message || err), "error");
    } finally {
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = origBtnHtml || '<i class="fa-solid fa-check"></i> حفظ التعديلات في السيرفر';
        }
    }
};

window.printSelectedExpiry = function() {
    if (selectedExpiryItems.size === 0) {
        showToast("لم يتم تحديد أي استلامة", "warning");
        return;
    }
    
    let selectedData = expiryData.filter(item => selectedExpiryItems.has(String(item.id)));
    
    let receivers = [...new Set(selectedData.map(i => i.receiver).filter(r => r && String(r).trim() !== ''))];
    let mergedReceiverName = receivers.length > 0 ? receivers.join(' / ') : "غير محدد";
    
    let reportTitle = `استلامات مجمعة - المستلم: ${mergedReceiverName}`;
    generateCategoryPDF(selectedData, reportTitle);
};

// ==========================================
// 3. Export Logic (تصدير متقدم ExcelJS)
// ==========================================

async function generateExcel(dataToExport, reportTitle, options = {}) {
    if (!dataToExport || dataToExport.length === 0) {
        showToast("لا توجد بيانات للتصدير في هذه القائمة", "warning");
        return;
    }

    try {
        if (typeof ExcelJS === 'undefined') {
            showToast("جاري تجهيز محرك التصدير الذكي...", "warning");
            await new Promise((resolve, reject) => {
                const script = document.createElement('script');
                script.src = 'https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.3.0/exceljs.min.js';
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        }

        const workbook = new ExcelJS.Workbook();
        workbook.creator = 'Candy Club System';
        workbook.created = new Date();

        const sheet1 = workbook.addWorksheet('البيانات التفصيلية', { views: [{ rightToLeft: true }] });
        const hasMarketplaceStatuses = dataToExport.some(row =>
            Object.prototype.hasOwnProperty.call(row, 'talabatStatus') ||
            Object.prototype.hasOwnProperty.call(row, 'instashopStatus')
        );

        sheet1.columns = options.marketplaceArchive ? [
            { header: 'اسم المنتج', key: 'name', width: 35 },
            { header: 'الباركود', key: 'barcode', width: 20 },
            { header: 'تاريخ التسجيل', key: 'reg', width: 18 },
            { header: 'طلبات', key: 'talabatStatus', width: 18 },
            { header: 'InstaShop', key: 'instashopStatus', width: 18 }
        ] : [
            { header: 'اسم المنتج', key: 'name', width: 35 },
            { header: 'الكمية', key: 'qty', width: 12 },
            { header: 'الباركود', key: 'barcode', width: 20 },
            { header: 'تاريخ الانتهاء', key: 'date', width: 18 },
            { header: 'الأيام المتبقية', key: 'days', width: 15 },
            { header: 'المكان / المورد', key: 'loc', width: 22 },
            { header: 'اسم المسجل', key: 'regname', width: 22 },
            { header: 'تاريخ التسجيل', key: 'reg', width: 18 },
            { header: 'المستلم', key: 'rec', width: 18 },
            { header: 'ملاحظات', key: 'notes', width: 30 },
            { header: 'السعر الأساسي', key: 'origPrice', width: 15 },
            { header: 'سعر العرض', key: 'offerPrice', width: 15 },
            { header: 'الحالة', key: 'status', width: 18 },
            ...(hasMarketplaceStatuses ? [
                { header: 'حالة طلبات', key: 'talabatStatus', width: 18 },
                { header: 'حالة InstaShop', key: 'instashopStatus', width: 18 }
            ] : [])
        ];

        sheet1.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 12 };
        sheet1.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF2C3E50' } };
        sheet1.getRow(1).alignment = { vertical: 'middle', horizontal: 'center' };
        sheet1.getRow(1).height = 25;

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        let sortedData = (options && options.marketplaceArchive) ? [...dataToExport] : [...dataToExport].sort((a, b) => {
            let da = new Date(a.expiryDate).getTime();
            let db = new Date(b.expiryDate).getTime();
            return da - db;
        });

        sortedData.forEach(row => {
            let daysRemaining = getDaysRemaining(row.expiryDate);
            let daysFormatted = daysRemaining === 'NoExpiry' ? 'بدون' : (isNaN(daysRemaining) ? '-' : daysRemaining);

            let formattedRegDate = row.regDate ? new Date(row.regDate).toLocaleDateString('en-CA') : '';
            let formattedExpDate = row.expiryDate ? new Date(row.expiryDate).toLocaleDateString('en-CA') : '';
            if (formattedRegDate === 'Invalid Date') formattedRegDate = row.regDate;
            if (formattedExpDate === 'Invalid Date') formattedExpDate = row.expiryDate;

            const newRow = sheet1.addRow(options.marketplaceArchive ? {
                name: row.name || '',
                barcode: row.barcode || '',
                reg: row.regDate || '',
                talabatStatus: window.marketplaceStatusLabel(row.talabatStatus),
                instashopStatus: window.marketplaceStatusLabel(row.instashopStatus)
            } : {
                name: row.name || '',
                origPrice: row.originalPrice || '',
                offerPrice: row.offerPrice || '',
                qty: row.qty || '',
                barcode: row.barcode || '',
                date: formattedExpDate,
                days: daysFormatted,
                reg: formattedRegDate,
                regname: row.registrarName || '',
                loc: row.location || '',
                rec: row.receiver || '',
                status: row.status || '',
                notes: row.notes || '',
                ...(hasMarketplaceStatuses ? {
                    talabatStatus: window.marketplaceStatusLabel(row.talabatStatus),
                    instashopStatus: window.marketplaceStatusLabel(row.instashopStatus)
                } : {})
            });

            newRow.alignment = { vertical: 'middle', horizontal: 'center' };
            newRow.height = 20;

            if (row.status !== 'Deleted' && daysRemaining !== 'NoExpiry' && !isNaN(daysRemaining)) {
                if (daysRemaining < 0) {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFCCCC' } };
                    newRow.font = { color: { argb: 'FFC0392B' }, bold: true };
                } else if (daysRemaining < 7) {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFD6D6' } };
                } else if (daysRemaining < 30) {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFF9C4' } };
                } else if (daysRemaining <= 90) {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFE0B2' } };
                } else if (daysRemaining > 180) {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD4E6F1' } };
                } else {
                    newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD5F5E3' } };
                }
            }

            if (row.status === 'Deleted') {
                newRow.font = { color: { argb: 'FF95A5A6' }, italic: true };
                newRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F4F4' } };
            }
        });

        const buffer = await workbook.xlsx.writeBuffer();
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        let cleanTitle = reportTitle.replace(/<[^>]*>?/gm, '').trim();
        let safeTitle = cleanTitle.replace(/[^a-zA-Z0-9أ-ي]/g, '_');
        link.download = `تقرير_${safeTitle}_${new Date().toLocaleDateString('en-CA')}.xlsx`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        showToast("<i class=\'fa-solid fa-check\'></i> تم تصدير التقرير الاحترافي بنجاح", "success");

    } catch (error) {
        console.error(error);
        showToast("<i class=\'fa-solid fa-xmark\'></i> حدث خطأ أثناء التصدير", "error");
    }
}

function generateMarketplaceArchivePdf(rows, periodLabel) {
    if (!rows.length) {
        showToast('لا توجد سجلات مطابقة للتصدير في هذه الفترة.', 'warning');
        return;
    }
    const printWindow = window.open('', '_blank', 'height=800,width=1000');
    if (!printWindow) {
        showToast('يرجى السماح بالنوافذ المنبثقة لفتح تقرير PDF.', 'error');
        return;
    }

    const safePeriod = escapeMarketplaceArchiveHtml(periodLabel || 'الفترة المحددة');
    const rowsHtml = rows.map((item, idx) => `
        <tr>
            <td style="font-weight: bold; width: 45px;">${idx + 1}</td>
            <td style="text-align: right; font-weight: bold;">${escapeMarketplaceArchiveHtml(item.name || 'اسم غير مسجل')}</td>
            <td dir="ltr">${escapeMarketplaceArchiveHtml(item.barcode || '-')}</td>
            <td dir="ltr">${escapeMarketplaceArchiveHtml(item.regDate || '-')}</td>
            <td class="talabat">${window.marketplaceStatusLabel(item.talabatStatus)}</td>
            <td class="instashop">${window.marketplaceStatusLabel(item.instashopStatus)}</td>
        </tr>`).join('');

    printWindow.document.write(`<!doctype html>
        <html lang="ar" dir="rtl">
        <head>
            <meta charset="utf-8">
            <title>حالات طلبات وInstaShop - ${safePeriod}</title>
            <style>
                body { font-family: 'Tajawal', Arial, sans-serif; color: #172033; padding: 24px; direction: rtl; }
                .report-header { border-bottom: 2px solid #e2e8f0; padding-bottom: 14px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center; }
                h1 { color: #0f172a; font-size: 20px; margin: 0 0 6px; }
                .meta { color: #64748b; font-size: 13px; margin: 0; }
                table { width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 13px; }
                th, td { border: 1px solid #cbd5e1; padding: 8px 10px; text-align: center; }
                th { color: #fff; background: #1e293b; font-weight: bold; }
                th.talabat, td.talabat { color: #c2410c; background: #fff7ed; font-weight: bold; }
                th.instashop, td.instashop { color: #be185d; background: #fdf2f8; font-weight: bold; }
                tbody tr:nth-child(even) { background: #f8fafc; }
                @media print { body { padding: 0; } }
            </style>
        </head>
        <body>
            <div class="report-header">
                <div>
                    <h1>متابعة المنتجات على طلبات وInstaShop</h1>
                    <p class="meta">الفترة المحددة: <strong>${safePeriod}</strong> | عدد السجلات: <strong>${rows.length} منتج</strong> (مرتبة ومطابقة للجدول)</p>
                </div>
            </div>
            <table>
                <thead>
                    <tr>
                        <th>#</th>
                        <th style="text-align: right;">المنتج</th>
                        <th>الباركود</th>
                        <th>تاريخ التسجيل</th>
                        <th class="talabat">طلبات</th>
                        <th class="instashop">InstaShop</th>
                    </tr>
                </thead>
                <tbody>${rowsHtml}</tbody>
            </table>
        </body>
        </html>`);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => printWindow.print(), 250);
}

document.getElementById('exportMarketplaceArchiveExcelBtn')?.addEventListener('click', async event => {
    const startDate = document.getElementById('marketplaceArchiveStartDate')?.value || '';
    const endDate = document.getElementById('marketplaceArchiveEndDate')?.value || '';
    window.renderMarketplaceArchive();

    let rangeLabel = 'كل_الفترات';
    if (startDate && endDate) {
        rangeLabel = `من_${startDate}_إلى_${endDate}`;
    } else if (startDate) {
        rangeLabel = `من_${startDate}`;
    } else if (endDate) {
        rangeLabel = `حتى_${endDate}`;
    }

    await generateExcel(window.marketplaceArchiveFilteredData || [], `حالات_المنصات_${rangeLabel}`, { marketplaceArchive: true });
});

document.getElementById('exportMarketplaceArchivePdfBtn')?.addEventListener('click', () => {
    const startDate = document.getElementById('marketplaceArchiveStartDate')?.value || '';
    const endDate = document.getElementById('marketplaceArchiveEndDate')?.value || '';
    window.renderMarketplaceArchive();

    let rangeLabel = 'جميع الفترات المسجلة';
    if (startDate && endDate) {
        rangeLabel = `من ${startDate} إلى ${endDate}`;
    } else if (startDate) {
        rangeLabel = `من تاريخ ${startDate}`;
    } else if (endDate) {
        rangeLabel = `حتى تاريخ ${endDate}`;
    }

    generateMarketplaceArchivePdf(window.marketplaceArchiveFilteredData || [], rangeLabel);
});

// Export Current List Button (inside Details Section)
const expirySortSelect = document.getElementById('expirySortSelect');
if (expirySortSelect) {
    expirySortSelect.addEventListener('change', (e) => {
        let sortVal = e.target.value;
        if (!expiryFilteredData || expiryFilteredData.length === 0) return;
        
        if (sortVal === 'default') {
            showExpiryDetails(expiryCurrentCategory, true);
            return;
        }
        
        let sorted = [...expiryFilteredData];
        
        if (sortVal === 'expiry_asc') {
            sorted.sort((a, b) => new Date(a.expiryDate || '9999-12-31') - new Date(b.expiryDate || '9999-12-31'));
        } else if (sortVal === 'expiry_desc') {
            sorted.sort((a, b) => new Date(b.expiryDate || '9999-12-31') - new Date(a.expiryDate || '9999-12-31'));
        } else if (sortVal === 'qty_asc') {
            sorted.sort((a, b) => (Number(a.qty) || 0) - (Number(b.qty) || 0));
        } else if (sortVal === 'qty_desc') {
            sorted.sort((a, b) => (Number(b.qty) || 0) - (Number(a.qty) || 0));
        } else if (sortVal === 'name_asc') {
            sorted.sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'ar'));
        }
        
        expiryFilteredData = sorted;
        currentExportData = sorted; // Update export data to match sorted list
        expiryCurrentPage = 1;
        updateExpiryPaginationUI();
        showExpiryDetails(expiryCurrentCategory, false);
    });
}

function normalizeCalendarDate(value) {
    if (value === null || value === undefined || value === '') return null;
    const raw = String(value).trim();
    if (!raw) return null;

    const isoMatch = raw.match(/^\d{4}-\d{2}-\d{2}$/);
    if (isoMatch) return raw;

    const compactMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (compactMatch) {
        return `${compactMatch[1]}-${compactMatch[2]}-${compactMatch[3]}`;
    }

    const dmyMatch = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
    if (dmyMatch) {
        const d = String(dmyMatch[1]).padStart(2, '0');
        const m = String(dmyMatch[2]).padStart(2, '0');
        const y = dmyMatch[3];
        return `${y}-${m}-${d}`;
    }

    const cleanStr = raw.replace(/[^\d\s\:\-\/]/g, '').trim();
    const parsed = new Date(cleanStr || raw);
    if (!isNaN(parsed.getTime())) {
        const year = parsed.getFullYear();
        const month = String(parsed.getMonth() + 1).padStart(2, '0');
        const day = String(parsed.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    return null;
}

function getCalendarMonthKey(value) {
    const normalized = normalizeCalendarDate(value);
    if (!normalized) return null;
    const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return null;
    return `${match[1]}-${match[2]}`;
}

function getCalendarDateKey(value) {
    const normalized = normalizeCalendarDate(value);
    if (!normalized) return null;
    const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return null;
    return `${match[1]}-${match[2]}-${match[3]}`;
}

function getSortDateValue(value) {
    const normalized = normalizeCalendarDate(value);
    if (!normalized) return Number.NEGATIVE_INFINITY;
    return new Date(`${normalized}T12:00:00`).getTime();
}

