                if (isToday) rowStyle = 'background:linear-gradient(135deg,#e8f5e9,#f1f8e9); border-bottom:2px solid #66bb6a; border-right:4px solid #2e7d32;';

                let empNameEscaped = selectedEmp.replace(/'/g, "\\'");

